await withApp(async (w, d, T) => {
  section("70i. appendTailText is format-aware: a tailed file parses new chunks under ITS OWN format, not the global default");
  const bracketFmt = { id: "fmt-bracket-tail", name: "Bracket", mode: "pattern", pattern: "[%d] %p (%t) %m%n", regex: "", tsFormat: "yyyy-MM-dd HH:mm:ss", builtin: false, edited: false, createdAt: Date.now() };
  T.state.logFormats.push(bracketFmt);

  const node = { id: "fake-tail", entries: [], tail: { pending: "" }, formatId: bracketFmt.id };
  const changed = w.appendTailText(node, "[2024-01-15 10:00:05] WARN (main) tail line one\n");
  assert(changed === true, "appendTailText reports a change when a new entry lands");
  assert(node.entries.length === 1, "one entry appended");
  assert(node.entries[0].level === "WARN" && node.entries[0].thread === "main" && node.entries[0].message === "tail line one",
    "the appended entry is parsed under the file's OWN custom format, not the default log4net shape");

  // A second chunk in the SAME custom shape keeps working (not a one-shot fluke).
  w.appendTailText(node, "[2024-01-15 10:00:06] INFO (main) tail line two\n");
  assert(node.entries.length === 2 && node.entries[1].message === "tail line two", "a subsequent chunk parses correctly too");

  // Default-format node (no formatId) still works via appendTailText, proving
  // this codepath's dispatch didn't regress the un-configured case either.
  const defaultNode = { id: "fake-tail-2", entries: [], tail: { pending: "" }, formatId: null };
  w.appendTailText(defaultNode, makeLog(0, 1));
  assert(defaultNode.entries.length === 1 && defaultNode.entries[0].message === "message 0", "a node with no formatId still tails under the builtin default");
});

await withApp(async (w, d, T) => {
  section("70j. Builtin default row: Edit + Reset (not Delete); Reset reverts both the displayed fields AND actual parsing behavior");
  await waitForFormatConfig(T);
  fireClick(d.querySelector("#btnSettings"), w);

  const defaultRow = () => d.querySelector("#formatList .filter-library-row");
  assert(defaultRow().querySelector(".filter-library-row-del") === null, "the builtin default row has no Delete button");
  const resetBtn = () => [...defaultRow().querySelectorAll("button")].find(b => b.textContent === "Reset");
  assert(resetBtn(), "...and has a Reset button in its place");
  assert(resetBtn().className === "btn-mini-outline", "Reset uses the same secondary-button style as Cancel elsewhere, got " + resetBtn().className);

  // Sanity: an unedited default parses a normal log4net-shaped file correctly.
  const before = await w.addFile("before.log", makeLog(0, 3), () => {});
  assert(before.entries[1].level === "INFO" && before.entries[1].thread === "main" && before.entries[1].method === "DoWork" && before.entries[1].message === "message 1",
    "sanity: unedited default parses a normal file correctly");

  // Edit the default: rename it and replace the pattern with something that
  // only extracts level+message (drops thread/method entirely) — a clearly
  // DIFFERENT, verifiable parse result, not just a cosmetic name change.
  fireClick(defaultRow().querySelector("button.btn-mini-outline"), w); // "Edit"
  d.querySelector("#formatEditName").value = "Renamed default";
  d.querySelector("#formatEditPattern").value = "%p %m%n";
  fireClick(d.querySelector("#formatEditSave"), w);
  // saveFormatEdit's IndexedDB write is async — wait for the state asserted on.
  await waitFor(() => {
    const fmt = T.state.logFormats.find(f => f.id === "fmt-default");
    return !!fmt && fmt.name === "Renamed default";
  });

  const editedFmt = T.state.logFormats.find(f => f.id === "fmt-default");
  assert(editedFmt.name === "Renamed default" && editedFmt.edited === true, "editing the builtin default updates it in place and flags it edited");
  assert(defaultRow().querySelector(".filter-library-row-name").textContent.includes("Renamed default"), "the row reflects the new name");

  const duringEdit = await w.addFile("during-edit.log", makeLog(10, 1), () => {});
  assert(duringEdit.entries.length === 1, "sanity: the edited pattern still matches the line as a single entry, got " + duringEdit.entries.length);
  assert(duringEdit.entries[0].thread === "" && duringEdit.entries[0].method === "",
    "while edited, the SAME file shape now parses under the new (different) pattern — thread/method no longer extracted");
  assert(isNaN(duringEdit.entries[0].ts), "...and the %d-less pattern has no ts group at all, so ts is NaN");

  // Reset: reverts the row AND restores the original untouched fast-path parsing.
  fireClick(resetBtn(), w);
  // resetDefaultFormat mutates the format object BEFORE awaiting its
  // IndexedDB write and only re-renders AFTER it resolves — so the barrier
  // has to be a POST-write effect (the row's own re-render), not the state,
  // which is already correct while the write is still in flight. Waiting on
  // the state would let the group finish and tear the window down mid-write,
  // which crashes the shard in renderLevelBar.
  await waitFor(() => !defaultRow().querySelector(".filter-library-row-name").textContent.includes("Renamed"));

  const resetFmt = T.state.logFormats.find(f => f.id === "fmt-default");
  assert(resetFmt.edited === false, "Reset clears the edited flag");
  assert(resetFmt.name === "Default (log4net-style)" && resetFmt.pattern === '%d\\t%p\\t"%t"\\t%c\\t[%M]\\t"%m"%n' && resetFmt.tsFormat === "yyyy-MM-dd HH:mm:ss,SSS",
    "Reset restores the exact original name/pattern/tsFormat, got " + JSON.stringify(resetFmt.pattern));
  assert(defaultRow().querySelector(".filter-library-row-name").textContent.includes("Default (log4net-style)") && !defaultRow().querySelector(".filter-library-row-name").textContent.includes("Renamed"),
    "the row's displayed name reverts too");

  const after = await w.addFile("after-reset.log", makeLog(20, 3), () => {});
  assert(after.entries[1].level === "INFO" && after.entries[1].thread === "main" && after.entries[1].method === "DoWork" && after.entries[1].message === "message 1",
    "after Reset, a normal file parses exactly as it did before the edit — not just the displayed fields, the actual parse behavior");
});

/* ============================================================
   GROUP 71 — Configurable font size
   Origin: this session (2026-08-21), FEATURE_BACKLOG.md "Configurable font
   size — adjustable in Settings and via a keyboard shortcut". A whole-UI
   zoom (document.documentElement.style.zoom) rather than a font-size
   variable threaded through every hardcoded font-size in the file — see
   applyFontScale's own comment. Settings row (+/- buttons, a Reset button)
   and Ctrl+Plus/Ctrl+Minus both funnel into the same function, persisted to
   localStorage like the theme toggle.
   ============================================================ */
group(71);
await withApp(async (w, d, T) => {
  section("71. Configurable font size");

  const html = d.documentElement;
  assert(html.style.zoom === "1", "default font scale is 100% (zoom:1) at boot, got " + JSON.stringify(html.style.zoom));
  assert(d.getElementById("fontScaleValue").textContent === "100%", "Settings shows 100% by default");

  fireClick(d.getElementById("fontScaleUp"), w);
  assert(html.style.zoom === "1.1", "the + button increases zoom by one step (10%)");
  assert(d.getElementById("fontScaleValue").textContent === "110%", "...and the Settings value label updates too");
  assert(w.localStorage.getItem("philogg-font-scale") === "110", "persisted to localStorage");

  fireClick(d.getElementById("fontScaleDown"), w);
  fireClick(d.getElementById("fontScaleDown"), w);
  assert(html.style.zoom === "0.9", "the - button decreases zoom by one step");

  for (let i = 0; i < 10; i++) fireClick(d.getElementById("fontScaleDown"), w);
  assert(html.style.zoom === "0.7", "font scale clamps at the minimum (70%), got " + html.style.zoom);
  for (let i = 0; i < 20; i++) fireClick(d.getElementById("fontScaleUp"), w);
  assert(html.style.zoom === "1.6", "font scale clamps at the maximum (160%), got " + html.style.zoom);

  fireClick(d.getElementById("fontScaleReset"), w);
  assert(html.style.zoom === "1", "Reset restores 100%");

  fireKeydown(d, w, "+", { ctrlKey: true });
  assert(html.style.zoom === "1.1", "Ctrl+Plus increases font scale via keyboard");
  fireKeydown(d, w, "-", { ctrlKey: true });
  assert(html.style.zoom === "1", "Ctrl+Minus decreases font scale via keyboard, back to 100%");
});

/* ============================================================
   GROUP 72 — Ctrl+0/1/2/3(/4) tree/Log-view shortcuts + Enter
   Origin: this session (2026-08-21), FEATURE_BACKLOG.md "Shortcuts to
   switch between Tree and Filter view", REVISED twice same session per
   person-requested follow-up feedback, and again on 2026-09-05
   (person-requested): Ctrl+0 focuses the filter tree at whichever node is
   ALREADY active — a filter included, not just its root file — so arrow
   keys continue navigating from wherever the person currently is (an even
   earlier pass jumped up to the active node's root FILE instead, which
   undid exactly that); falls back to the first root file only if nothing's
   active yet. Ctrl+1-4 (jumpToViewTab/currentViewTabsList) no longer mirror
   fixed Full/Filtered/Stacked toggle buttons — they jump POSITIONALLY
   through whichever tabs the View Selector currently shows, same order:
   with a plain (non-extraction) node that's just [Context, Filtered], so
   Ctrl+3/4 are no-ops there; Ctrl+1/2 still open Full/Filtered and focus
   the entries pane for arrow-key navigation exactly as before — a new
   state.entriesView ("filter" | "highlight") decides which of
   moveSelection/moveHighlightSelection the global ArrowUp/Down handler
   calls, also updated by a plain click/dblclick in either Log view.
   Entering Stacked itself is no longer a Ctrl+3 action (there's no
   "Stacked" tab to jump to from tabs layout — it only appears once Stacked
   is already the active layout) — that's exercised with an
   extraction-capable node instead, see 72b below.
   ============================================================ */
group(72);
await withApp(async (w, d, T) => {
  section("72. Ctrl+0/1/2/3 tree/Log-view shortcuts + Enter");

  const f = await w.addFile("a.log", makeLog(0, 5), () => {});
  const filterA = w.createFilterNode(f.id, "text", "message");
  w.render();

  // Ctrl+0: focus the tree at whichever node is ALREADY active — a filter
  // stays the active node, it does NOT jump up to its root file.
  T.state.activeId = filterA.id;
  fireKeydown(d, w, "0", { ctrlKey: true });
  assert(T.state.activeId === filterA.id, "Ctrl+0 keeps the already-active FILTER active, doesn't jump up to its root file");
  assert(T.state.focusRegion === "tree", "Ctrl+0 switches focus to the tree");

  T.state.activeId = null;
  fireKeydown(d, w, "0", { ctrlKey: true });
  assert(T.state.activeId === f.id, "Ctrl+0 with no active node falls back to the first root file");

  // Ctrl+1: opens Full (Highlight) and focuses it for arrow-key navigation.
  w.applyFhView("filter");
  fireKeydown(d, w, "1", { ctrlKey: true });
  assert(T.fhActiveTab === "highlight", "Ctrl+1 opens the Full view");
  assert(T.state.focusRegion === "entries" && T.state.entriesView === "highlight", "...and focuses it (entriesView) for arrow-key navigation");

  const beforeHighlightSelect = T.state.selectedId;
  fireKeydown(d, w, "ArrowDown");
  assert(T.state.selectedId !== beforeHighlightSelect, "with entriesView \"highlight\", ArrowDown moves the Full view's own selection, not the Filtered view's");

  // Ctrl+2: opens Filtered and focuses it — arrow keys move that view instead.
  fireKeydown(d, w, "2", { ctrlKey: true });
  assert(T.fhActiveTab === "filter", "Ctrl+2 opens the Filtered view");
  assert(T.state.focusRegion === "entries" && T.state.entriesView === "filter", "...and focuses it (entriesView) for arrow-key navigation");

  // Ctrl+3: this node isn't extraction-capable, so the View Selector only
  // has 2 tabs (Context, Filtered) — position 3 doesn't exist, a silent no-op.
  const beforeCtrl3 = { tab: T.fhActiveTab, layout: T.fhLayout };
  fireKeydown(d, w, "3", { ctrlKey: true });
  assert(T.fhActiveTab === beforeCtrl3.tab && T.fhLayout === beforeCtrl3.layout, "Ctrl+3 with only 2 available tabs is a no-op");

  // Enter on an active FILTER node while the tree has focus reveals the Filtered view.
  w.applyFhView("highlight");
  T.state.activeId = filterA.id;
  T.state.focusRegion = "tree";
  fireKeydown(d, w, "Enter");
  assert(T.fhActiveTab === "filter", "Enter on an active filter node (tree focus) reveals the Filtered view");
  assert(T.state.focusRegion === "entries" && T.state.entriesView === "filter", "...and switches focus to the entries pane");

  // Enter on a FILE node (not a filter) is a no-op for the view switch.
  w.applyFhView("highlight");
  T.state.activeId = f.id;
  T.state.focusRegion = "tree";
  fireKeydown(d, w, "Enter");
  assert(T.fhActiveTab === "highlight", "Enter on a file node (not a filter) leaves the Full tab showing");
  assert(T.state.focusRegion === "tree", "...and focus stays on the tree");
});

await withApp(async (w, d, T) => {
  section("72b. Ctrl+1-4 on an extraction-capable node jump positionally (Context/Filtered/Table/Plot); once Stacked layout is active, only 1-3 exist (Stacked/Table/Plot)");

  const f = await w.addFile("a.log", makeLog(0, 5), () => {});
  const node = w.createFilterNode(f.id, "text", "message [*:int]");
  T.state.activeId = node.id;
  w.render();
  w.applyFhView("filter");

  fireKeydown(d, w, "3", { ctrlKey: true });
  assert(T.fhActiveTab === "table", "Ctrl+3 jumps to position 3 (Table), now that a 3rd tab exists");
  fireKeydown(d, w, "4", { ctrlKey: true });
  assert(T.fhActiveTab === "plot", "Ctrl+4 jumps to position 4 (Plot)");
  fireKeydown(d, w, "1", { ctrlKey: true });
  assert(T.fhActiveTab === "highlight", "Ctrl+1 jumps back to position 1 (Context)");

  // Switch to Stacked layout (a Settings choice, not a Ctrl shortcut) — from
  // here the View Selector collapses Context+Filtered into one "Stacked"
  // slot, so there are only 3 positions: Stacked, Table, Plot.
  const layoutSelect = d.querySelector("#settingsFhLayout");
  layoutSelect.value = "stacked";
  layoutSelect.dispatchEvent(new w.Event("change", { bubbles: true }));
  assert(T.fhLayout === "stacked", "sanity: now in Stacked layout");

  fireKeydown(d, w, "2", { ctrlKey: true });
  assert(T.fhActiveTab === "table", "Ctrl+2 in Stacked layout jumps to position 2 (Table)");
  fireKeydown(d, w, "3", { ctrlKey: true });
  assert(T.fhActiveTab === "plot", "Ctrl+3 in Stacked layout jumps to position 3 (Plot)");
  const before4 = T.fhActiveTab;
  fireKeydown(d, w, "4", { ctrlKey: true });
  assert(T.fhActiveTab === before4, "Ctrl+4 in Stacked layout is a no-op — only 3 positions exist");
  fireKeydown(d, w, "1", { ctrlKey: true });
  assert(T.fhLayout === "stacked" && T.fhActiveTab !== "table" && T.fhActiveTab !== "plot", "Ctrl+1 in Stacked layout jumps to position 1 (Stacked itself)");
});

/* ============================================================
   GROUP 73 — Horizontal scrollbar in the log views
   Origin: this session (2026-08-21), FEATURE_BACKLOG.md "Horizontal
   scrollbar in the Filter view — so long messages can be read in full".
   #tableBody scrolls horizontally; #tableHeader keeps its own scrollbar
   hidden and has its scrollLeft driven by #tableBody's scroll event, and
   its .row-grid's width kept in sync with the widest currently-rendered
   row (syncTableHeaderWidth, called from renderVisibleRows) since the
   header's own content (short column labels) would otherwise size much
   narrower than a long message. The actual visual overflow/scrollbar
   behavior is CSS/layout-driven (`.col-msg{min-width: max-content}` forcing
   the message column's grid track to refuse to shrink below its own
   content) and isn't independently verifiable here — jsdom has no real
   layout engine (see tests/README's "Known gaps") — so this covers the
   JS-observable parts: the overflow-x split itself (real computed style,
   not just a class) and the header sync/scroll-lockstep logic. GROUP 73b
   covers the follow-up bugfix's own JS logic (computeMaxMessageWidth/
   syncTableRowsWidth) directly.
   UPDATED 2026-09-02 (person-requested): the Context view scrolls
   horizontally too now, through its own mirror of the same pair
   (syncHighlightRowsWidth/syncHighlightHeaderWidth). This group used to
   assert the opposite — that #highlightBody stays clipped — which is dead
   code now, so it asserts the mirror instead.
   ============================================================ */
group(73);
await withApp(async (w, d, T) => {
  section("73. Horizontal scrollbar in the log views");

  const tableBody = d.getElementById("tableBody");
  const tableHeader = d.getElementById("tableHeader");
  const highlightBody = d.getElementById("highlightBody");
  const highlightHeader = d.getElementById("highlightHeader");

  assert(w.getComputedStyle(tableBody).overflowX === "auto", "Filter view's #tableBody scrolls horizontally");
  assert(w.getComputedStyle(tableHeader).overflowX === "hidden", "the header's own (synced, non-user-facing) scrollbar stays hidden");
  assert(w.getComputedStyle(highlightBody).overflowX === "auto",
    "the Context view scrolls horizontally too (person-requested — it used to clip long messages instead)");
  assert(w.getComputedStyle(highlightHeader).overflowX === "hidden", "…with its own header scrollbar hidden the same way");

  await w.addFile("a.log", makeLog(0, 5), () => {});
  w.render();

  const tableRows = d.getElementById("tableRows");
  Object.defineProperty(tableRows, "scrollWidth", { value: 1234, configurable: true });
  w.renderVisibleRows();
  const headerGrid = tableHeader.querySelector(".row-grid");
  assert(headerGrid.style.width === "1234px", "the header's row-grid width tracks the widest rendered row's natural width, got " + headerGrid.style.width);

  tableBody.scrollLeft = 42;
  tableBody.dispatchEvent(new w.Event("scroll", { bubbles: true }));
  assert(tableHeader.scrollLeft === 42, "scrolling the Filter view's body drives the header's scrollLeft to match");

  // The Context view's own copy of both halves.
  const highlightRows = d.getElementById("highlightRows");
  Object.defineProperty(highlightRows, "scrollWidth", { value: 987, configurable: true });
  w.renderHighlightVisibleRows();
  assert(highlightHeader.querySelector(".row-grid").style.width === "987px",
    "the Context header's row-grid width tracks its own widest rendered row, got " + highlightHeader.querySelector(".row-grid").style.width);
  highlightBody.scrollLeft = 17;
  highlightBody.dispatchEvent(new w.Event("scroll", { bubbles: true }));
  assert(highlightHeader.scrollLeft === 17, "scrolling the Context view's body drives its own header's scrollLeft to match");
});

/* ============================================================
   GROUP 73b — Row background/scroll-width bugfix (Filter view)
   Origin: this session (2026-08-21), person-reported follow-up to GROUP 73
   (screenshot: colored row backgrounds and the usable horizontal-scroll
   range stopped at the viewport edge instead of covering a long message's
   full width; a second report after the first fix showed only the row
   that itself held a long message grew — every other row in the same file
   stayed narrow, and the scrollbar's own range shrank back once that row
   scrolled out of the virtualized window). Root-caused to #tableRows
   giving every row a width sized from whatever the CURRENTLY RENDERED
   window happened to contain, never the full filtered list. Fixed by
   computing ONE width up front from the WIDEST message across the entire
   current view (computeMaxMessageWidth) and applying it to #tableRows
   itself (syncTableRowsWidth) — every .log-row is a plain width:auto
   block, so all of them inherit that one shared width uniformly. See
   PROJECT.md changelog for the full root-cause writeup and the CSS
   comment near applyRowGrid for the calculation itself.
   Unlike the GROUP 73 CSS overflow mechanism, this fix's actual logic is
   plain JS over an entries array — genuinely testable here, not a jsdom
   "layout blind spot" case. jsdom has no real layout engine, so
   measureMsgWidth (see its own comment, and GROUP 73c below for its
   follow-up rewrite) falls back to a deterministic per-character estimate
   there — fine for relative/threshold assertions, not for exact pixel
   values, same caveat as the character-count-based approach itself (a real
   browser's font-metric precision is what ultimately matters, verified
   separately with Playwright per the changelog entry).
   ============================================================ */
group(73);
await withApp(async (w, d, T) => {
  section("73b. Row background/scroll-width bugfix (Filter view)");

  const tableRows = d.getElementById("tableRows");
  const tableBody = d.getElementById("tableBody");
  const tableSpacer = d.getElementById("tableSpacer");

  assert(w.computeMaxMessageWidth([]) === 0, "computeMaxMessageWidth of an empty list is 0");
  assert(w.computeMaxMessageWidth([{ message: "" }, { message: null }]) === 0, "...and of a list with no message text");

  const shortMsg = "hi";
  const longMsg = "x".repeat(200);
  assert(
    w.computeMaxMessageWidth([{ message: shortMsg }, { message: longMsg }]) > w.computeMaxMessageWidth([{ message: shortMsg }]),
    "computeMaxMessageWidth grows with the widest message ANYWHERE in the list, not just the first/last entry"
  );

  // Multiline mode: the WIDEST LINE decides the width, not the total
  // (unwrapped) character count — mirrors the on/off distinction
  // rowHeightForEntry already makes for row HEIGHT (line count, not total
  // length), since white-space:nowrap collapses a literal "\n" to a single
  // space (one visual line) while white-space:pre actually breaks on it.
  const mixedMessage = "a\n" + "y".repeat(50) + "\nb";
  T.state.multilineMessages = false;
  const singleLineW = w.computeMaxMessageWidth([{ message: mixedMessage }]);
  T.state.multilineMessages = true;
  const multilineW = w.computeMaxMessageWidth([{ message: mixedMessage }]);
  T.state.multilineMessages = false;
  assert(singleLineW > multilineW, "single-line mode measures the WHOLE message; multiline mode measures only its widest individual line");

  // End-to-end: #tableRows itself gets ONE explicit width from the widest
  // message in the whole file, applied uniformly — not a per-row width.
  const longSuffix = "x".repeat(200);
  await w.addFile("mix.log", makeLog(0, 5, { suffix: i => (i === 2 ? longSuffix : "") }), () => {});
  w.render();

  assert(tableRows.style.width !== "", "a file with one long message (among otherwise-short ones) gives #tableRows an explicit width");
  const widthPx = parseFloat(tableRows.style.width);
  assert(widthPx > tableSpacer.clientWidth, "...wider than the viewport (clientWidth stub is " + tableSpacer.clientWidth + "px)");

  // Scroll to a window of rows that does NOT include the long-message row
  // (index 2) and confirm #tableRows' width is untouched — exactly the
  // person-reported regression (background/scroll range used to shrink
  // back once the long-message row scrolled out of the rendered window).
  const widthBefore = tableRows.style.width;
  tableBody.scrollTop = 999;
  w.renderVisibleRows();
  assert(tableRows.style.width === widthBefore, "…and stays exactly the same width once the long-message row scrolls out of the rendered window");

  // A file with only short messages: nothing needs more than the viewport,
  // so #tableRows must go back to filling it — no leftover inline width
  // from the previous (long-message) file. The global clientWidth stub is
  // a narrow 800px (barely wider than the default fixed columns alone,
  // 811px — see applyRowGrid/DEFAULT_COLUMN_WIDTHS), which would make even
  // a short message "overflow" here; widen #tableSpacer's stub just for
  // this assertion to a value any short message genuinely fits inside,
  // matching what a real (much wider) desktop viewport gives for free.
  Object.defineProperty(tableSpacer, "clientWidth", { value: 5000, configurable: true });
  await w.addFile("short.log", makeLog(0, 5), () => {});
  w.render();
  assert(tableRows.style.width === "", "a file with only short messages leaves #tableRows filling the view (no inline width)");

  // Belt-and-braces CSS floor (person-reported, 2026-09-05): #tableRows'
  // stretch-fill relies on JS clearing its inline width at the right moment
  // (above) — should that ever go stale (a width computed once, before the
  // panel reached its final size, never revisited), a plain CSS min-width:
  // 100% on #tableRows/#highlightRows independently guarantees rows (and so
  // their .selected box-shadow outline) can never render narrower than the
  // view, no JS timing involved. min-width always wins over a smaller
  // explicit width per the CSS box model, so this is provably a no-op for
  // the long-message case above (explicit width there is already > 100%).
  assert(w.getComputedStyle(tableRows).minWidth === "100%", "#tableRows has a CSS min-width:100% floor, independent of the JS width sync");
  assert(w.getComputedStyle(d.getElementById("highlightRows")).minWidth === "100%", "#highlightRows has the same floor");
});

/* ============================================================
   GROUP 73c — measureMsgWidth rewrite: real DOM measurement, not canvas
   Origin: this session (2026-08-21), person-reported follow-up to GROUP 73b
   (built the exact "4 differently-long messages" repro the person asked
   for — short/medium/long/multi-line-stacktrace — and scrolled all the way
   right with Playwright): #tableRows WAS sized correctly per GROUP 73b's
   own logic, but consistently wider than where the longest message's text
   actually ended — a real, visible gap past the last character, growing
   with the message's length. Root cause: GROUP 73b's measureMsgWidth used
   Canvas2D's measureText(), which measurably diverges from Blink's own CSS
   layout text renderer for an IDENTICAL font-family/size string (confirmed
   directly: an offscreen canvas and a real DOM element given the same
   700-character string and the same explicit font declaration came back
   ~1.1% apart per character — small alone, but compounding linearly with
   message length, so a genuinely long line — the exact case this feature
   exists for — could end up hundreds of pixels short of matching reality).
   Not a rounding nit: two different browser text-rendering pipelines
   (canvas glyph shaping vs. layout line-boxing) simply don't promise
   pixel-identical advance widths for the same font, even same-engine.
   Fixed by dropping canvas entirely: measureMsgWidth now reads the natural
   width of a hidden, reused DOM element carrying the SAME `.col-msg` class
   real rows use (position:absolute, shrink-to-fit, off past any visible
   area) via offsetWidth — literally the same rendering path a real row
   uses, so it cannot diverge from it. See PROJECT.md changelog for the
   measured numbers and the offsetWidth-vs-getBoundingClientRect zoom-safety
   check (offsetWidth stays in unscaled CSS px under state.fontScale's
   whole-UI zoom; getBoundingClientRect() doesn't — verified with
   Playwright, not assumed).
   jsdom has no real layout engine, so a freshly created, unstubbed
   element's offsetWidth is always 0 — same documented blind spot the
   highlight-marker tooltip positioning already works around — exercising
   measureMsgWidth's own MONO_CHAR_WIDTH_FALLBACK path exactly, deterministically.
   ============================================================ */
group(73);
await withApp(async (w, d, T) => {
  section("73c. measureMsgWidth rewrite: real DOM measurement, not canvas");

  assert(typeof w.measureMsgWidth === "function", "measureMsgWidth exists");
  assert(w.measureMsgWidth("") === 0, "measureMsgWidth of an empty string is 0");
  assert(
    w.measureMsgWidth("hello") === 5 * T.MONO_CHAR_WIDTH_FALLBACK,
    "in jsdom (no real layout engine, offsetWidth always 0 on a fresh element), measureMsgWidth falls back to exactly length * MONO_CHAR_WIDTH_FALLBACK"
  );
  assert(
    w.measureMsgWidth("a".repeat(50)) === 50 * T.MONO_CHAR_WIDTH_FALLBACK,
    "...proportionally, for a longer string"
  );

  // The measuring element is created once and reused (not a fresh element,
  // and not inserted, per call) — a perf guard: computeMaxMessageWidth
  // calls this once per render, not once per entry, specifically BECAUSE
  // a real layout-triggering measurement is too slow to do per-entry over
  // a large file; if this ever regressed into re-creating/re-inserting the
  // element every call, a huge file would reflow on every keystroke-speed
  // render.
  w.measureMsgWidth("first");
  const probesAfterFirst = d.querySelectorAll("body > div.col-msg").length;
  w.measureMsgWidth("second");
  const probesAfterSecond = d.querySelectorAll("body > div.col-msg").length;
  assert(probesAfterFirst === 1, "exactly one hidden measuring element exists after the first call, got " + probesAfterFirst);
  assert(probesAfterSecond === 1, "...and the SAME one is reused on a second call, not a new one appended, got " + probesAfterSecond);

  const probe = d.querySelector("body > div.col-msg");
  assert(w.getComputedStyle(probe).visibility === "hidden", "the measuring element is visibility:hidden (kept laid out for offsetWidth, just not painted)");
  assert(w.getComputedStyle(probe).position === "absolute", "...and taken out of flow (position:absolute) so it can't affect real layout");
});

/* ============================================================
   GROUP 74 — Double-click a filter row opens its edit dialog
   Origin: this session (2026-08-21), FEATURE_BACKLOG.md "Double-click on a
   filter opens its edit dialog". NOT a native "dblclick" listener: a tree
   row's own click handler always ends in a full render(), which rebuilds
   every #tree row from scratch (CLAUDE.md's "DOM identity across clicks"
   gotcha, previously documented for renderVisibleRows()/native dblclick —
   the same class of bug applies here to a real browser's dblclick pairing,
   just unobservable from jsdom's directly-dispatched click events). Manual
   click-id+timestamp tracking (lastTreeRowClickId/Time) sidesteps that
   entirely. Shares the same editFilterNode helper F2 and the context
   menu's "Edit filter…" action already use.
   ============================================================ */
group(74);
await withApp(async (w, d, T) => {
  section("74. Double-click a filter row opens its edit dialog");

  const f = await w.addFile("a.log", makeLog(0, 10), () => {});
  const textNode = w.createFilterNode(f.id, "text", "message 1");
  const timeNode = w.createFilterNode(f.id, "after", f.entries[3].ts);
  w.render();
  function rowFor(nodeId) { return d.querySelector('.tree-row[data-node-id="' + nodeId + '"]'); }

  fireClick(rowFor(textNode.id), w);
  assert(d.querySelector("#filterPopup").classList.contains("hidden"), "a single click alone doesn't open the edit dialog");
  fireClick(rowFor(textNode.id), w);
  assert(!d.querySelector("#filterPopup").classList.contains("hidden"), "...but a second quick click on the same row does (double-click)");
  assert(d.querySelector("#filterInput").value === "message 1", "...pre-filled with the existing value (edit mode)");
  w.closeFilterPopup();

  // A time-range ("after") node opens the OTHER dialog on double-click.
  w.render();
  fireClick(rowFor(timeNode.id), w);
  fireClick(rowFor(timeNode.id), w);
  assert(!d.querySelector("#timeRangeDialog").classList.contains("hidden"), "double-clicking a time-filter row opens the time-range dialog instead");
  w.closeTimeRangeDialog();

  // Two Ctrl+clicks (multi-select gesture) never count as a double-click.
  w.render();
  const ctrlClick = () => rowFor(textNode.id).dispatchEvent(new w.MouseEvent("click", { bubbles: true, cancelable: true, ctrlKey: true }));
  ctrlClick(); ctrlClick();
  assert(d.querySelector("#filterPopup").classList.contains("hidden"), "two Ctrl+clicks (multi-select) never open the edit dialog");

  // Two clicks spread further apart than the double-click window don't count either.
  w.render();
  fireClick(rowFor(textNode.id), w);
  await new Promise(r => setTimeout(r, 600));
  fireClick(rowFor(textNode.id), w);
  assert(d.querySelector("#filterPopup").classList.contains("hidden"), "two clicks well over 450ms apart don't count as a double-click");

  // A file row (not a filter) double-click is a harmless no-op.
  w.render();
  fireClick(rowFor(f.id), w);
  fireClick(rowFor(f.id), w);
  assert(d.querySelector("#filterPopup").classList.contains("hidden") && d.querySelector("#timeRangeDialog").classList.contains("hidden"),
    "double-clicking a FILE row opens neither dialog");
});

/* ============================================================
   GROUP 75 — Ctrl+W closes the currently open file
   Origin: this session (2026-08-21), FEATURE_BACKLOG.md "Ctrl+W closes the
   currently open file". Same close path the tree row's own ✕ button uses
   (deleteFilterNodeWithUndo via getRootFileId), so it's undo-able and works
   regardless of which node in the file's chain happens to be active.
   ============================================================ */
group(75);
await withApp(async (w, d, T) => {
  section("75. Ctrl+W closes the currently open file");

  const f = await w.addFile("a.log", makeLog(0, 5), () => {});
  const filterA = w.createFilterNode(f.id, "text", "message");
  T.state.activeId = filterA.id; // active node is a child filter, not the file itself
  w.render();

  fireKeydown(d, w, "w", { ctrlKey: true });
  assert(!T.state.nodes[f.id], "Ctrl+W removes the active node's root FILE, even though a child filter was active");
  assert(!T.state.nodes[filterA.id], "...and its filter children go with it");
  assert(T.state.rootIds.length === 0, "no files remain");

  T.state.activeId = null;
  fireKeydown(d, w, "w", { ctrlKey: true });
  assert(T.state.rootIds.length === 0, "Ctrl+W with nothing open is a harmless no-op");

  const f2 = await w.addFile("b.log", makeLog(0, 3), () => {});
  T.state.activeId = f2.id;
  w.render();
  fireKeydown(d, w, "w", { ctrlKey: true });
  assert(T.state.rootIds.length === 0, "sanity: b.log closed");
  w.undo();
  assert(T.state.nodes[f2.id], "Ctrl+W's close goes through the same undo-able deleteFilterNodeWithUndo path as the ✕ button");
});

/* ============================================================
   GROUP 76 — Settings: "Closing the last log file quits the app"
   Origin: this session (2026-08-21), FEATURE_BACKLOG.md item, default off.
   Purely a local app-behavior preference (localStorage, like the theme
   toggle), meaningful mainly under the desktop wrapper — a bare
   window.close() is enough there since the wrapper routes the page's own
   window.close() into a real window close (see docs/desktop.md);
   in an ordinary browser tab it's a no-op. window.close
   is stubbed here (and restored afterwards) rather than actually invoked,
   since a real jsdom window.close() would tear the test window down mid-run.
   ============================================================ */
group(76);
await withApp(async (w, d, T) => {
  section("76. Settings: \"Closing the last log file quits the app\" (default off)");

  const checkbox = d.getElementById("settingsQuitOnLastClose");
  assert(checkbox.checked === false, "off by default");

  const originalClose = w.close;
  let closeCalls = 0;
  w.close = () => { closeCalls++; };
  try {
    const f = await w.addFile("a.log", makeLog(0, 3), () => {});
    T.state.activeId = f.id;
    w.render();

    fireKeydown(d, w, "w", { ctrlKey: true });
    assert(closeCalls === 0, "closing the last file does nothing extra while the setting is off");
    assert(w.localStorage.getItem("philogg-quit-on-last-close") === null, "nothing persisted yet — setting untouched");

    checkbox.checked = true;
    checkbox.dispatchEvent(new w.Event("change", { bubbles: true }));
    assert(w.localStorage.getItem("philogg-quit-on-last-close") === "1", "enabling the checkbox persists it");

    const f2 = await w.addFile("b.log", makeLog(0, 3), () => {});
    const other = await w.addFile("c.log", makeLog(0, 3), () => {});
    T.state.activeId = f2.id;
    w.render();

    fireKeydown(d, w, "w", { ctrlKey: true });
    assert(closeCalls === 0, "closing one of two open files doesn't quit — one file (\"c.log\") still remains");
    assert(T.state.rootIds.length === 1, "sanity: one file remains");

    T.state.activeId = other.id;
    w.render();
    fireKeydown(d, w, "w", { ctrlKey: true });
    assert(closeCalls === 1, "closing the very last open file quits the app when the setting is on");
  } finally {
    w.close = originalClose;
  }
});

/* ============================================================
   GROUP 77 — Bugfix: sample-line pattern suggestion, two fixes for the
   same person-reported PLC log (this session, 2026-08-21, via screenshot):

   1. ";SSS" (and any other) millisecond separator, not just "," / ".".
      The log uses "10:43:18;617" (semicolon before milliseconds), which
      tripped the fractional-seconds candidate in SAMPLE_TS_CANDIDATES —
      it only matched "." or ",". The suggester fell back to the no-ms
      timestamp shape and baked the sample's own ms value (";617") into
      the pattern as literal text, so only lines sharing that exact
      millisecond kept matching. Fixed by capturing whatever separator
      character is actually present and reproducing it in tsFormat
      instead of hardcoding "," (compileDateFormat already escapes
      literal separators generically, so this was purely a suggestion-
      heuristic gap, not a compiler limit).
   2. A bare (unquoted, undelimited) thread field. Reported as STILL
      breaking after fix 1 — the real remaining cause: this log's header
      lines ("TRACE\t-\t[System]\t...") and its FIFO-data lines
      ("WARN\tAxCtrl\t[-]\t...") share one shape, %d %p <bare-word>
      [%M] %m, but the suggester only ever recognized a thread wrapped in
      quotes or parens. On the one sample line it saw, the bare word
      between level and the [System] bracket was "-", which then got
      read as fixed literal text — so it matched every header line (all
      literally "-") but not one FIFO-data line, where that same
      position holds a real, varying value ("AxCtrl", "CrashP", ...).
      Fixed by claiming a single whitespace-free token sitting directly
      between %p and an already-claimed %M bracket as %t — a narrow,
      structurally-cued case (framed by the level on one side and an
      immediate "[" on the other) rather than a blind "next word is the
      thread" guess that would misfire on ordinary free-form messages.
   ============================================================ */
group(77);
await withApp(async (w, d, T) => {
  section("77. Pattern suggestion: non-comma ms separators AND a bare thread field both round-trip instead of becoming literal text");

  const semi = w.suggestPatternFromSample("2026-08-14 10:43:18;617\tTRACE\t-\t[System]\tSafety: ES OK");
  assert(semi && semi.pattern === "%d\\t%p\\t%t\\t[%M]\\t%m%n", "the ms value is absorbed into %d and the bare \"-\" becomes %t, not literal text, got " + (semi && semi.pattern));
  assert(semi.tsFormat === "yyyy-MM-dd HH:mm:ss;SSS", "tsFormat reproduces the semicolon separator actually seen, got " + semi.tsFormat);

  // The suggested pattern/tsFormat must then actually parse LATER lines
  // with a different millisecond AND a real (non-"-") thread value — the
  // exact failure mode reported: the FIFO-data block read as one message.
  const compiled = w.compileFormatPattern(semi.pattern, semi.tsFormat);
  assert(compiled.regex, "the suggested pattern compiles");
  const header = compiled.regex.exec("2026-08-14 10:43:18;617\tTRACE\t-\t[System]\t*************** START FIFO DATA ***************");
  assert(header && header.groups.thread === "-" && header.groups.method === "System", "a second header line (thread \"-\") still matches, got " + JSON.stringify(header && header.groups));
  const fifo = compiled.regex.exec("2026-08-14 10:33:45;389\tWARN\tAxCtrl\t[-]\tFB_InitEndlessPosition Error");
  assert(fifo, "a FIFO-data line, with a DIFFERENT millisecond AND a real thread value, still matches the suggested pattern");
  assert(fifo.groups.thread === "AxCtrl" && fifo.groups.method === "-" && fifo.groups.message === "FB_InitEndlessPosition Error",
    "...and thread/method/message are extracted from their correct fields, not swallowed into a prior message, got " + JSON.stringify(fifo && fifo.groups));

  const dotOrComma = w.suggestPatternFromSample("2024-01-15 10:00:00,123 ERROR boom");
  assert(dotOrComma.tsFormat === "yyyy-MM-dd HH:mm:ss,SSS", "comma separator still round-trips as before (no regression), got " + dotOrComma.tsFormat);
  const dot = w.suggestPatternFromSample("2024-01-15 10:00:00.123 ERROR boom");
  assert(dot.tsFormat === "yyyy-MM-dd HH:mm:ss.SSS", "dot separator still round-trips too, got " + dot.tsFormat);

  const noMs = w.suggestPatternFromSample("2024-01-15 10:00:00 ERROR boom");
  assert(noMs.tsFormat === "yyyy-MM-dd HH:mm:ss", "a sample with no fractional seconds at all still falls back cleanly, got " + noMs.tsFormat);

  // No bracket at all -> no structural cue -> the bare-word rule must NOT
  // fire (would otherwise misread the first word of a free-form message
  // as a thread).
  const noBracket = w.suggestPatternFromSample("2024-01-15 10:00:00 ERROR Database connection failed");
  assert(noBracket.pattern === "%d %p %m%n", "with no bracket to frame it, a bare word after the level is left as part of the message, not misread as %t, got " + noBracket.pattern);

  // Already-quoted thread still takes priority over the new bare-word rule.
  const quoted = w.suggestPatternFromSample('2024-01-15 10:00:00 ERROR "main" [Startup] boom');
  assert(quoted.pattern === '%d %p "%t" [%M] %m%n', "a quoted thread is still claimed the old way, unaffected by the new bare-word rule, got " + quoted.pattern);
});

/* ============================================================
   GROUP 78 — Enter on a selected Filtered/Stacked row mirrors dblclick
   Origin: this session (2026-08-21), person request: with a single row
   selected in the Filtered view (or the Filtered/bottom pane of the
   Stacked view — same entriesView === "filter" rows either way), Enter
   should do what a dblclick on that row already does: revealInHighlightView
   (see its own comment — centres the Full view on the entry without
   touching activeId/levelFilter/the Filter view's own scroll position).
   Left alone (no-op) with a multi-selection active, since there's no
   single obvious target row; also left alone with focus on the tree or the
   Full/Highlight pane itself (unrelated to this request).
   ============================================================ */
group(78);
await withApp(async (w, d, T) => {
  section("78. Enter on a selected Filtered/Stacked row mirrors dblclick (revealInHighlightView)");

  const f = await w.addFile("a.log", makeLog(0, 5), () => {});
  w.render();

  // Filtered (tabs layout): Enter on the single selected row reveals the Full view.
  w.applyFhView("filter");
  const target = f.entries[2];
  w.selectEntry(target.id);
  T.state.focusRegion = "entries";
  assert(T.state.entriesView === "filter", "sanity: entriesView is \"filter\" after selecting a row in the Filtered view");
  const prevActiveId = T.state.activeId;
  fireKeydown(d, w, "Enter");
  assert(T.fhActiveTab === "highlight", "Enter on the selected Filtered row switches to the Full tab, same as a dblclick would");
  assert(T.state.selectedId === target.id, "...keeping the same entry selected");
  assert(T.state.activeId === prevActiveId, "...without touching the active filter node (revealInHighlightView's own contract)");

  // Stacked layout: Enter on the selected row in the bottom (Filtered) pane does the same thing.
  w.applyFhView("stacked");
  const target2 = f.entries[4];
  w.selectEntry(target2.id);
  T.state.focusRegion = "entries";
  fireKeydown(d, w, "Enter");
  assert(T.fhActiveTab === "highlight", "Enter on the selected row in Stacked's Filtered pane reveals the Full view the same way");
  assert(T.state.selectedId === target2.id, "...keeping that entry selected");

  // Multi-selection active: Enter is a no-op (no single obvious target row).
  w.applyFhView("filter");
  w.selectEntry(f.entries[1].id);
  T.state.logMultiSelect = new Set([f.entries[1].id, f.entries[3].id]);
  T.state.focusRegion = "entries";
  fireKeydown(d, w, "Enter");
  assert(T.fhActiveTab === "filter", "Enter with a multi-selection active leaves the Filtered tab showing (no-op)");

  // Focus elsewhere (tree): Enter's existing tree behavior is untouched, doesn't fall through to this new path.
  T.state.logMultiSelect = new Set();
  w.applyFhView("filter");
  const filterA = w.createFilterNode(f.id, "text", "message");
  T.state.activeId = filterA.id;
  T.state.focusRegion = "tree";
  fireKeydown(d, w, "Enter");
  assert(T.fhActiveTab === "filter", "Enter on the tree still runs its own (unrelated) filter-node behavior, not this new entries-pane path");
});

/* ============================================================
   GROUP 79 — Settings dialog redesign: section nav, unified card/row grid,
   Add-vs-Edit button hierarchy, boolean rows as a switch
   Origin: this session (2026-08-22), Claude-Design handoff bundle
   ("Settings Dialog und Panel-Navigation"). See PROJECT.md for the full
   design reference. IntersectionObserver-driven active-section highlighting
   on scroll isn't exercised here (jsdom has no IntersectionObserver — see
   the guard in the app itself); only the click-wiring + default state.
   ============================================================ */
group(79);
await withApp(async (w, d, T) => {
  section("79. Settings dialog redesign: section nav + unified rows + switch + button hierarchy");
  await waitForFormatConfig(T);

  fireClick(d.querySelector("#btnSettings"), w);

  // 5 sections: GROUP 114 added "Shortcuts", a later follow-up (removing the
  // header's help/license buttons) added "License" as the last section.
  const navItems = [...d.querySelectorAll("#settingsNav .settings-nav-item")];
  assert(navItems.length === 5, "the section nav lists exactly the five sections, got " + navItems.length);
  const targets = navItems.map(b => b.dataset.navTarget);
  assert(targets.includes("settingsSectionAppearance") && targets.includes("settingsSectionBehavior") &&
    targets.includes("settingsSectionFormats") && targets.includes("settingsSectionShortcuts") &&
    targets.includes("settingsSectionLicense"),
    "nav items point at Appearance/Behavior/Log Formats/Shortcuts/License, got " + JSON.stringify(targets));
  assert(targets[targets.length - 1] === "settingsSectionLicense", "License is always the last section in the list");
  targets.forEach(id => assert(d.getElementById(id), "every nav target id resolves to an actual section, missing " + id));

  const appearanceNavItem = navItems.find(b => b.dataset.navTarget === "settingsSectionAppearance");
  assert(appearanceNavItem.classList.contains("active"), "Appearance is the default active nav item on open");

  // Clicking a nav item is wired (calls scrollIntoView, guarded for
  // environments without it — see the app's own comment) and doesn't throw.
  const formatsNavItem = navItems.find(b => b.dataset.navTarget === "settingsSectionFormats");
  fireClick(formatsNavItem, w);

  // Row grid: each row group sits inside one .settings-card, using CSS grid.
  const appearanceCard = d.querySelector("#settingsSectionAppearance .settings-card");
  assert(appearanceCard, "the Appearance section's rows sit inside a .settings-card");
  const appearanceRows = [...appearanceCard.querySelectorAll(".settings-row")];
  // Theme + UI font (GROUP 111f) + Log font (this session) + Accent color
  // (hidden on Dark, no highlightPalette — see GROUP 87) + UI scale +
  // Log text size (split from the old single Font size row — see GROUP 111e).
  assert(appearanceRows.length === 6, "Theme + UI font + Log font + Accent color + UI scale + Log text size are all rows inside that one card, got " + appearanceRows.length);
  assert(w.getComputedStyle(appearanceRows[0]).display === "grid", "a settings-row lays out via CSS grid (1fr auto), got " + w.getComputedStyle(appearanceRows[0]).display);

  // Boolean row: rendered as a switch (input + adjacent track element),
  // still the same real checkbox underneath (see GROUP 76 for its behavior).
  const quitCheckbox = d.getElementById("settingsQuitOnLastClose");
  assert(quitCheckbox.closest(".settings-switch"), "the boolean checkbox is wrapped in .settings-switch");
  assert(quitCheckbox.nextElementSibling && quitCheckbox.nextElementSibling.classList.contains("settings-switch-track"),
    "...with a switch-track element right next to it for the on/off visual");

  // Button hierarchy: the filled accent (.btn-mini) button is reserved for
  // the primary action (Save) — list-row actions (Edit/Reset) are outline,
  // and the "Add…" affordance is a dashed outline, distinct from both.
  assert(d.querySelectorAll("#formatList .btn-mini, #formatRuleList .btn-mini").length === 0,
    "no filled accent button inside the format/rule list rows themselves");
  assert(d.querySelector("#formatList .btn-mini-outline"), "the Default format row's Edit button is outline-styled");
  assert(d.querySelector("#btnAddFormat").className === "btn-mini-dashed" && d.querySelector("#btnAddFormatRule").className === "btn-mini-dashed",
    "both Add buttons use the dashed style, distinct from Edit's outline and Save's filled accent");
  assert(d.querySelector("#formatEditSave").className === "btn-mini" && d.querySelector("#formatRuleEditSave").className === "btn-mini",
    "Save stays the one filled accent button in each inline panel");
});

/* ============================================================
   GROUP 80 — Collapsible sidebar / detail panel
   Origin: this session (2026-08-22), Claude-Design handoff bundle
   ("Settings Dialog und Panel-Navigation", part 1b). Sidebar collapses to a
   40px rail (marker chain for the active node's ancestry, or root files with
   nothing active); hovering it while collapsed peeks the full tree as an
   overlay (identical markup to the expanded state, no separate rendering
   path — see toggleSidebarCollapsed's comment); clicking the toggle while
   peeking pins it open (exits .collapsed entirely). Detail panel collapses
   to its 34px header, which still shows level/time/first-message-line
   instead of going empty. Both: Ctrl+B/Ctrl+J, resizer double-click,
   localStorage-persisted collapsed flag (display-preference tier, same as
   theme/font-scale — see THEME_STORAGE_KEY). EXTENDED 2026-08-22
   (person-requested follow-up): both resizers (#sidebarResizer/
   #detailResizer) are now hidden outright while their panel is collapsed,
   not just non-functional — a collapsed panel isn't manually resizable
   (sidebar = fixed 40px rail, detail panel = fixed 34px header), so a
   visible drag handle would be dead UI. Toggled directly in JS from
   toggleSidebarCollapsed/toggleDetailCollapsed rather than a CSS selector
   off the panel's own .collapsed class — #detailResizer in particular
   PRECEDES #detailPanel in the DOM, so no descendant/sibling-combinator
   selector keyed off #detailPanel.collapsed could ever reach it (a stale
   CSS rule tried exactly that and silently never matched — removed).
   ============================================================ */
group(80);
await withApp(async (w, d, T) => {
  section("80. Collapsible sidebar / detail panel");

  const sidebarEl = d.querySelector("#sidebar");
  const detailPanel = d.querySelector("#detailPanel");
  const sidebarNormalContent = d.querySelector("#sidebarNormalContent");
  const sidebarRail = d.querySelector("#sidebarRail");
  const detailBody = d.querySelector("#detailBody");
  const sidebarResizerEl = d.querySelector("#sidebarResizer");
  const detailResizerEl = d.querySelector("#detailResizer");

  assert(!sidebarEl.classList.contains("collapsed") && !detailPanel.classList.contains("collapsed"), "both panels start expanded");
  assert(isVisible(sidebarNormalContent, w) && !isVisible(sidebarRail, w), "expanded: normal tree content shown, rail hidden");

  // --- Sidebar collapse/expand ---
  w.toggleSidebarCollapsed();
  assert(sidebarEl.classList.contains("collapsed"), "toggleSidebarCollapsed() collapses the sidebar");
  assert(sidebarEl.style.width === "40px", "collapsed width is set to the 40px rail, got " + sidebarEl.style.width);
  assert(w.localStorage.getItem("philogg-sidebar-collapsed") === "1", "collapsed flag persisted to localStorage");
  assert(!isVisible(sidebarNormalContent, w) && isVisible(sidebarRail, w), "collapsed (not hovering): rail shown, normal content hidden");
  // A collapsed sidebar has a fixed 40px rail width, not a manually
  // resizable one, so its own drag handle would be dead UI if left
  // visible — hidden outright rather than just non-functional (person-
  // requested follow-up, this session).
  assert(!isVisible(sidebarResizerEl, w), "collapsed sidebar hides its own drag-resize handle entirely");

  w.toggleSidebarCollapsed();
  assert(!sidebarEl.classList.contains("collapsed"), "toggling again expands the sidebar");
  assert(sidebarEl.style.width !== "40px", "width is restored away from the 40px rail value, got " + sidebarEl.style.width);
  assert(w.localStorage.getItem("philogg-sidebar-collapsed") === "0", "expanded flag persisted too");
  assert(isVisible(sidebarResizerEl, w), "expanding the sidebar brings its drag handle back");

  // --- Hover-peek: collapsed + mouseenter shows the exact expanded content
  //     as an overlay (no separate peek-only markup/rendering) ---
  w.toggleSidebarCollapsed(true);
  sidebarEl.dispatchEvent(new w.MouseEvent("mouseenter", { bubbles: false }));
  assert(sidebarEl.classList.contains("peeking"), "hovering a collapsed sidebar enters peek state");
  assert(isVisible(sidebarNormalContent, w), "...revealing the SAME normal-content element used when expanded, not a separate rendering");
  sidebarEl.dispatchEvent(new w.MouseEvent("mouseleave", { bubbles: false }));
  assert(!sidebarEl.classList.contains("peeking") && isVisible(sidebarRail, w), "leaving reverts to the plain rail");

  // Clicking the toggle while peeking pins it open (same toggle function,
  // not a separate "pinned" state — see toggleSidebarCollapsed).
  sidebarEl.dispatchEvent(new w.MouseEvent("mouseenter", { bubbles: false }));
  fireClick(d.querySelector("#sidebarToggle"), w);
  assert(!sidebarEl.classList.contains("collapsed") && !sidebarEl.classList.contains("peeking"), "clicking the toggle while peeking pins the sidebar fully open");

  // --- Rail markers: active node's ancestor chain, clickable, doesn't
  //     itself expand the sidebar ---
  const f = await w.addFile("a.log", makeLog(0, 5), () => {});
  const filterNode = w.createFilterNode(f.id, "text", "message");
  T.state.activeId = filterNode.id;
  w.render();
  w.toggleSidebarCollapsed(true);
  const markers = [...d.querySelectorAll("#sidebarRail .sidebar-rail-marker")];
  assert(markers.length === 2, "rail shows one marker per ancestor (file + the active filter), got " + markers.length);
  assert(markers[markers.length - 1].classList.contains("active"), "the active node's own marker carries .active");
  fireClick(markers[0], w); // the file marker
  assert(T.state.activeId === f.id, "clicking a rail marker sets it active");
  assert(sidebarEl.classList.contains("collapsed"), "...without expanding the sidebar back out");

  // --- Keyboard shortcut + resizer double-click ---
  w.toggleSidebarCollapsed(false);
  fireKeydown(d, w, "b", { ctrlKey: true });
  assert(sidebarEl.classList.contains("collapsed"), "Ctrl+B toggles the sidebar collapse");
  d.querySelector("#sidebarResizer").dispatchEvent(new w.MouseEvent("dblclick", { bubbles: true }));
  assert(!sidebarEl.classList.contains("collapsed"), "double-clicking the sidebar resizer toggles it back open");

  // Plain "b" (no modifier) still runs the existing bookmark shortcut, not
  // the sidebar toggle — Ctrl+B must not have hijacked it.
  w.selectEntry(f.entries[0].id);
  const bookmarksBefore = T.state.bookmarks.size;
  fireKeydown(d, w, "b");
  assert(T.state.bookmarks.size === bookmarksBefore + 1, "plain 'b' with a row selected still toggles a bookmark");

  // --- Detail panel collapse/expand ---
  assert(!detailPanel.classList.contains("collapsed"), "sanity: detail panel starts expanded");
  w.toggleDetailCollapsed();
  assert(detailPanel.classList.contains("collapsed"), "toggleDetailCollapsed() collapses the panel");
  assert(detailPanel.style.height === "34px", "collapsed height matches the 34px header, got " + detailPanel.style.height);
  assert(!isVisible(detailBody, w), "the message body is hidden while collapsed");
  assert(w.localStorage.getItem("philogg-detail-collapsed") === "1", "collapsed flag persisted");
  // Same reasoning as the sidebar resizer above (person-requested follow-up,
  // this session): #detailResizer PRECEDES #detailPanel in the DOM, so a
  // stale CSS rule keyed off #detailPanel.collapsed #detailResizer never
  // actually matched (removed) — hiding it is done in JS instead, from
  // toggleDetailCollapsed directly.
  assert(!isVisible(detailResizerEl, w), "collapsed detail panel hides its own drag-resize handle entirely");

  // Collapsed meta line: level + time + first message line, not the full
  // thread/location/method field set (no room for those in 34px).
  const detailMeta = d.querySelector("#detailMeta");
  assert(detailMeta.querySelector(".detail-collapsed-msg") && !detailMeta.querySelector(".detail-thread"),
    "collapsed header shows the truncated first message line instead of thread/location/method");

  w.toggleDetailCollapsed(false);
  assert(!detailPanel.classList.contains("collapsed") && isVisible(detailBody, w), "expanding restores the body");
  assert(detailMeta.querySelector(".detail-thread") && !detailMeta.querySelector(".detail-collapsed-msg"),
    "...and the full field set is back in the meta line");
  assert(isVisible(detailResizerEl, w), "expanding the detail panel brings its drag handle back");

  fireKeydown(d, w, "j", { ctrlKey: true });
  assert(detailPanel.classList.contains("collapsed"), "Ctrl+J toggles the detail panel collapse");
  d.querySelector("#detailResizer").dispatchEvent(new w.MouseEvent("dblclick", { bubbles: true }));
  assert(!detailPanel.classList.contains("collapsed"), "double-clicking the detail resizer toggles it back open");

  // --- Persisted flag is honored on (re-)init, same path real boot uses ---
  w.localStorage.setItem("philogg-sidebar-collapsed", "1");
  w.localStorage.setItem("philogg-detail-collapsed", "1");
  w.initSidebarCollapsed();
  w.initDetailCollapsed();
  assert(sidebarEl.classList.contains("collapsed") && detailPanel.classList.contains("collapsed"),
    "initSidebarCollapsed/initDetailCollapsed re-apply a persisted collapsed flag, same as at boot");
});

/* ============================================================
   GROUP 85 — Configurable themes: Catppuccin flavors + custom JSON
   import/export
   Origin: this session (2026-08-22). Replaces the Light/Dark button pair
   (#settingsThemeLight/#settingsThemeDark, see GROUP 3/70h/70h2's updated
   text) with a #settingsThemeSelect dropdown listing six built-in themes
   (dark, light, four Catppuccin flavors — https://catppuccin.com/palette/)
   plus any user-imported custom ones (localStorage philogg-custom-themes).
   ============================================================ */
group(85);
await withApp(async (w, d, T) => {
  section("85a. Built-in theme dropdown includes the four Catppuccin flavors, and picking one applies its CSS vars");
  fireClick(d.querySelector("#btnSettings"), w);
  const select = d.querySelector("#settingsThemeSelect");
  const optionValues = [...select.options].map(o => o.value);
  assert(T.BUILTIN_THEMES.every(t => optionValues.includes(t.id)),
    "every BUILTIN_THEMES id has a matching <option>, got " + JSON.stringify(optionValues));
  ["catppuccin-latte", "catppuccin-frappe", "catppuccin-macchiato", "catppuccin-mocha"].forEach(id => {
    assert(optionValues.includes(id), "Catppuccin flavor " + id + " is offered");
  });

  select.value = "catppuccin-mocha";
  select.dispatchEvent(new w.Event("change", { bubbles: true }));
  assert(d.documentElement.getAttribute("data-theme") === "catppuccin-mocha", "picking Catppuccin Mocha sets data-theme");
  const cs = w.getComputedStyle(d.documentElement);
  // --bg-app = Base per the style-guide remap (GROUP 88) — the main
  // content pane is the brightest of the "background pane" tier now,
  // not Crust (the darkest), which is what the app's own pre-existing
  // Dark/Light hierarchy would have suggested — see PROJECT.md "Theming".
  assert(cs.getPropertyValue("--bg-app").trim() === "#1e1e2e", "Mocha's --bg-app CSS var resolves via the [data-theme] block to Base, got " + cs.getPropertyValue("--bg-app"));
  assert(cs.getPropertyValue("--bg-panel").trim() === "#181825", "Mocha's --bg-panel resolves to Mantle (darker than --bg-app/Base, per the style-guide remap), got " + cs.getPropertyValue("--bg-panel"));
  assert(cs.getPropertyValue("--accent").trim() === "#94e2d5", "Mocha's --accent resolves too, got " + cs.getPropertyValue("--accent"));
  assert(w.localStorage.getItem("philogg-theme") === "catppuccin-mocha", "theme choice persisted to localStorage");
  // Style guide: "Selection Background" = Overlay 2 @ 20-30% opacity —
  // Mocha overrides --selection-bg to reuse --level-debug (already =
  // Overlay 2, see that CSS block), NOT the accent-tinted default every
  // non-Catppuccin theme keeps (Dark's own --selection-bg stays var(--accent-soft)).
  const selectionBg = cs.getPropertyValue("--selection-bg").replace(/\s+/g, "");
  assert(selectionBg === "color-mix(insrgb,var(--level-debug)25%,transparent)",
    "Mocha's --selection-bg is the Overlay-2-based color-mix formula, got " + cs.getPropertyValue("--selection-bg"));

  select.value = "catppuccin-latte";
  select.dispatchEvent(new w.Event("change", { bubbles: true }));
  const csLatte = w.getComputedStyle(d.documentElement);
  // Declared as var(--bg-app) (Latte maps --bg-app to Base, #eff1f5, per
  // the style-guide remap — GROUP 88) — per the Catppuccin style guide,
  // "On Accent" text = Base, so --level-*-on/--accent-on reference that
  // var directly rather than a hardcoded near-white. jsdom's
  // getComputedStyle doesn't resolve nested var() the way a real browser
  // does (see tests/README.md "Known gaps"), so this checks the declared
  // value, not the resolved color; Group 87's/88's Playwright-verified
  // screenshots confirm the real rendered result.
  assert(csLatte.getPropertyValue("--level-error-on").trim() === "var(--bg-app)",
    "Latte (a light-background flavor) points --level-error-on at its own Base color (--bg-app) instead of a hardcoded near-white, got " + csLatte.getPropertyValue("--level-error-on"));
});

await withApp(async (w, d, T) => {
  section("85b. Importing a custom theme JSON: validation, storage, activation, dropdown + list rendering");
  fireClick(d.querySelector("#btnSettings"), w);

  assert(d.querySelector("#customThemeList .filter-library-empty"), "custom theme list starts empty");

  // Not valid JSON at all.
  w.importThemeJson("{not json");
  assert(T.customThemes.length === 0, "malformed JSON is rejected, nothing added");

  // Valid JSON but missing the format tag.
  w.importThemeJson(JSON.stringify({ name: "No tag", colors: {} }));
  assert(T.customThemes.length === 0, "a JSON file without the philogg-theme format tag is rejected");

  // Valid format tag but missing required color keys.
  w.importThemeJson(JSON.stringify({ format: "philogg-theme", version: 1, name: "Incomplete", colors: { "bg-app": "#111111" } }));
  assert(T.customThemes.length === 0, "a theme file missing required color keys is rejected");

  // A full, valid theme file — build it from the template generator itself,
  // proving the round trip (template out -> tweak -> import back in) works.
  const template = JSON.parse(w.buildThemeTemplateJson());
  assert(template.format === "philogg-theme" && typeof template.colors === "object", "buildThemeTemplateJson seeds a valid, self-consistent template");
  assert(T.THEME_COLOR_KEYS.every(k => typeof template.colors[k] === "string" && template.colors[k].length > 0),
    "the template includes every required color key with a non-empty value");
  template.name = "My Purple Night";
  template.colors["bg-app"] = "#120018";
  template.colors["accent"] = "#bb33ff";
  template.activeTextLight = true;
  w.importThemeJson(JSON.stringify(template));

  assert(T.customThemes.length === 1, "a valid theme file is accepted and added to customThemes");
  const imported = T.customThemes[0];
  assert(imported.name === "My Purple Night", "the imported theme's name is preserved");
  assert(imported.colors["bg-app"] === "#120018" && imported.colors["accent"] === "#bb33ff", "imported colors are preserved");
  assert(JSON.parse(w.localStorage.getItem("philogg-custom-themes"))[0].name === "My Purple Night", "custom themes persist to localStorage");

  assert(d.documentElement.getAttribute("data-theme") === imported.id, "importing a theme switches to it immediately");
  const cs = w.getComputedStyle(d.documentElement);
  assert(cs.getPropertyValue("--bg-app").trim() === "#120018", "the custom theme's colors are applied as inline CSS vars, got " + cs.getPropertyValue("--bg-app"));
  assert(cs.getPropertyValue("--level-error-on").trim() === "#fff", "activeTextLight:true applies white active-button text");

  const select = d.querySelector("#settingsThemeSelect");
  assert([...select.options].some(o => o.value === imported.id && o.textContent === "My Purple Night"),
    "the imported theme appears as an option in the dropdown");
  assert(select.value === imported.id, "the dropdown reflects the newly-active custom theme");

  const listRow = d.querySelector("#customThemeList .filter-library-row");
  assert(listRow && listRow.textContent.includes("My Purple Night"), "the imported theme is listed in the Custom themes card");

  // Switching away and back via inline-style clearing: a built-in theme
  // picked afterwards must not leak the custom theme's inline overrides.
  select.value = "dark";
  select.dispatchEvent(new w.Event("change", { bubbles: true }));
  const csDark = w.getComputedStyle(d.documentElement);
  assert(csDark.getPropertyValue("--bg-app").trim() === "#10131a", "switching back to Dark clears the custom theme's inline var overrides, got " + csDark.getPropertyValue("--bg-app"));

  // Deleting a custom theme: removes it everywhere, and falls back to dark
  // if it was the active theme.
  select.value = imported.id;
  select.dispatchEvent(new w.Event("change", { bubbles: true }));
  assert(d.documentElement.getAttribute("data-theme") === imported.id, "sanity: custom theme active again before deleting it");
  d.querySelector("#customThemeList .filter-library-row-del").dispatchEvent(new w.MouseEvent("click", { bubbles: true, cancelable: true }));
  assert(T.customThemes.length === 0, "deleting the custom theme removes it from customThemes");
  assert(JSON.parse(w.localStorage.getItem("philogg-custom-themes")).length === 0, "...and from localStorage");
  assert(d.documentElement.getAttribute("data-theme") === "dark", "deleting the ACTIVE custom theme falls back to dark");
  assert(d.querySelector("#customThemeList .filter-library-empty"), "the list shows the empty state again");
});

await withApp(async (w, d, T) => {
  section("85c. A stale/deleted custom theme id in localStorage falls back to dark on boot instead of leaving data-theme dangling");
  w.localStorage.setItem("philogg-theme", "custom:does-not-exist");
  w.initTheme();
  assert(d.documentElement.getAttribute("data-theme") === "dark", "resolveThemeId falls back to dark for an unknown theme id, got " + d.documentElement.getAttribute("data-theme"));
});

/* ============================================================
   GROUP 86 — Theme consistency audit: no more hardcoded UI colors, and a
   theme-aware "Theme" mode for the highlight-color picker
   Origin: this session (2026-08-22), person-requested follow-up ("Prüfe
   noch mal auf der Website, welche Farbe für was verwendet wird und ob Du
   das konsequent umgesetzt hast"). An audit of the stylesheet found ~18
   buttons/badges/rows still hardcoding the DARK theme's own hex values
   (scrollbar thumb, toolbar button hover borders, the brand mark, Save/
   active-chip text, breadcrumb/level-pill/level-badge/log-row-hover tints)
   instead of the CSS vars every other rule already used — fixed via new
   --accent-on/--border-hover vars and color-mix(var(--x), transparent) for
   the alpha-tinted ones, so every one of those now tracks whichever theme
   is active instead of only ever matching Dark. Separately, the per-filter-
   node highlight-color picker (#colorPickerPopup, unrelated to app theming
   before this session) gained a "Theme" mode: its curated preset row can
   now show the ACTIVE theme's own highlightPalette (the 14 named
   Catppuccin accent colors per flavor) instead of the theme-independent
   generic HIGHLIGHT_PRESETS, so a chosen highlight color is guaranteed to
   belong to the current theme when that mode is on.
   ============================================================ */
group(86);
await withApp(async (w, d, T) => {
  section("86a. Stylesheet audit: the specific hardcoded hex values found in the audit are gone from the button/badge/row rules that used to hardcode them");
  const css = d.querySelector("style").textContent;
  // Each of these literals used to appear in a rule OUTSIDE the :root/
  // [data-theme] variable-definition blocks — i.e. hardcoded into a
  // component rule instead of using var(). They may still legitimately
  // appear INSIDE a :root[data-theme=...] block itself (that's the var's
  // own definition, not a violation) — this check targets the specific
  // component selectors the audit found, not the raw strings globally.
  const violations = [
    { selector: "::-webkit-scrollbar-thumb", bad: "#2a3142" },
    { selector: ".brand-mark", bad: "#2f8f8c" },
    { selector: ".brand-mark", bad: "#0b1016" },
    { selector: ".toolbar-badge", bad: "#08201f" },
    { selector: ".crumb.current", bad: "rgba(79,199,195,.35)" },
    { selector: ".level-btn.lvl-error", bad: "rgba(241,101,101,.35)" },
    { selector: ".lvl-error .level-badge", bad: "rgba(241,101,101,.28)" },
    { selector: ".log-row.lvl-error:hover", bad: "rgba(241,101,101,.20)" },
    { selector: ".token-chip", bad: "rgba(79,199,195,.35)" },
  ];
  violations.forEach(v => {
    const ruleMatch = css.match(new RegExp(v.selector.replace(/[.:]/g, "\\$&") + "\\{[^}]*\\}"));
    assert(ruleMatch && !ruleMatch[0].includes(v.bad), v.selector + " no longer hardcodes " + v.bad + ", got " + (ruleMatch ? ruleMatch[0] : "(rule not found)"));
  });
  assert(css.includes("--accent-on:"), "a themeable --accent-on var exists for text-on-accent surfaces");
  assert(css.includes("--border-hover:"), "a themeable --border-hover var exists for hover-state borders");
  assert(css.includes("color-mix(in srgb"), "the previously-hardcoded alpha-tinted rules now use color-mix() against a themed var");
});

await withApp(async (w, d, T) => {
  section("86b. Highlight-color picker: Free (default) vs Theme mode");
  const f = await w.addFile("a.log", makeLog(0, 5), () => {});
  const node = w.createFilterNode(f.id, "text", "msg");
  w.render();

  assert(T.colorPickerMode === "free", "sanity: Free is the default picker mode, unchanged prior behavior");
  const swatch = d.querySelector('[data-node-id="' + node.id + '"] .tree-swatch');
  fireClick(swatch, w);
  assert(isVisible(d.querySelector("#cpWheelWrap"), w), "Free mode: the hue wheel is visible");
  let presetTitles = [...d.querySelectorAll(".cp-preset")].map(b => b.title);
  assert(JSON.stringify(presetTitles) === JSON.stringify(T.HIGHLIGHT_PRESETS), "Free mode: presets are the generic HIGHLIGHT_PRESETS, got " + JSON.stringify(presetTitles));
  w.closeColorPicker();

  // Switch to a Catppuccin flavor, then to Theme mode.
  w.setTheme("catppuccin-mocha");
  fireClick(swatch, w);
  fireClick(d.querySelector("#cpModeTheme"), w);
  assert(T.colorPickerMode === "theme", "clicking Theme switches the mode");
  assert(w.localStorage.getItem("philogg-cp-mode") === "theme", "the mode choice persists to localStorage");
  assert(!isVisible(d.querySelector("#cpWheelWrap"), w), "Theme mode: the hue wheel is hidden");
  const mochaTheme = T.BUILTIN_THEMES.find(t => t.id === "catppuccin-mocha");
  presetTitles = [...d.querySelectorAll(".cp-preset")].map(b => b.title);
  assert(JSON.stringify(presetTitles) === JSON.stringify(mochaTheme.highlightPalette), "Theme mode: presets are Catppuccin Mocha's own highlightPalette (14 named accent colors), got " + presetTitles.length + " colors");

  // Picking one of the theme swatches sets the node's highlightColor and
  // closes the popup, same interaction as a Free-mode preset click.
  const firstSwatch = d.querySelector(".cp-preset");
  const pickedColor = firstSwatch.title;
  fireClick(firstSwatch, w);
  assert(T.state.nodes[node.id].highlightColor === pickedColor, "clicking a theme swatch sets the node's highlightColor to that swatch's color");
  assert(d.querySelector("#colorPickerPopup").classList.contains("hidden"), "picking a swatch closes the popup");

  // A theme with no highlightPalette (Dark) falls back to the generic set
  // while still in Theme mode — never an empty preset row.
  w.setTheme("dark");
  fireClick(swatch, w);
  presetTitles = [...d.querySelectorAll(".cp-preset")].map(b => b.title);
  assert(JSON.stringify(presetTitles) === JSON.stringify(T.HIGHLIGHT_PRESETS), "Theme mode on Dark (no highlightPalette) falls back to the generic HIGHLIGHT_PRESETS, got " + presetTitles.length + " colors");

  // Switching back to Free restores the wheel and generic presets, and
  // also persists.
  fireClick(d.querySelector("#cpModeFree"), w);
  assert(T.colorPickerMode === "free" && w.localStorage.getItem("philogg-cp-mode") === "free", "clicking Free switches back and persists");
  assert(isVisible(d.querySelector("#cpWheelWrap"), w), "Free mode: the hue wheel is visible again");
});

await withApp(async (w, d, T) => {
  section("86c. Highlight-color picker mode is restored on init, same as the theme choice itself");
  w.localStorage.setItem("philogg-cp-mode", "theme");
  w.setColorPickerMode(w.localStorage.getItem("philogg-cp-mode"));
  assert(T.colorPickerMode === "theme", "setColorPickerMode re-applies a persisted mode, same pattern initTheme() uses for the theme itself");
  assert(d.querySelector("#cpModeTheme").classList.contains("active") && !d.querySelector("#cpModeFree").classList.contains("active"),
    "the Theme button reflects the restored mode");
});

/* ============================================================
   GROUP 87 — Accent color: re-pick the app's OWN accent (buttons, the
   breadcrumb, the minimap's range highlight) from the active theme's
   own palette
   Origin: this session (2026-08-22), same-day clarification of the 86
   request — "Highlightfarbe" there meant the app's accent/selection color
   itself ("Highlightfarbe auf den Buttons oder die Markierung auf der
   Minimap für die Zeitabschnitte"), not the per-filter-node highlight
   color Group 86 covers (a different, unrelated feature that stays as-is).
   ============================================================ */
group(87);
await withApp(async (w, d, T) => {
  section("87a. Accent-color row: hidden for a theme with no highlightPalette, shown with swatches for one that has it");
  fireClick(d.querySelector("#btnSettings"), w);
  const row = d.querySelector("#settingsAccentRow");
  const picker = d.querySelector("#settingsAccentPicker");

  assert(!isVisible(row, w), "Dark (no highlightPalette) hides the Accent color row");

  const select = d.querySelector("#settingsThemeSelect");
  select.value = "catppuccin-mocha";
  select.dispatchEvent(new w.Event("change", { bubbles: true }));
  assert(isVisible(row, w), "Catppuccin Mocha (has a highlightPalette) shows the row");
  const swatches = [...picker.querySelectorAll(".accent-swatch:not(.accent-swatch-reset)")];
  const mochaPalette = T.BUILTIN_THEMES.find(t => t.id === "catppuccin-mocha").highlightPalette;
  assert(swatches.length === mochaPalette.length && swatches.every((s, i) => s.title === mochaPalette[i]),
    "the swatches are exactly Mocha's own highlightPalette, in order, got " + swatches.length + " of " + mochaPalette.length);
  assert(picker.querySelector(".accent-swatch-reset.active"), "with no override chosen yet, the reset/'theme default' swatch is the active one");

  select.value = "light";
  select.dispatchEvent(new w.Event("change", { bubbles: true }));
  assert(!isVisible(row, w), "Light (no highlightPalette either) hides the row again");
});

await withApp(async (w, d, T) => {
  section("87b. Picking an accent swatch recolors --accent/-strong/-soft/-on together, persists PER THEME, and survives switching away and back");
  fireClick(d.querySelector("#btnSettings"), w);
  const select = d.querySelector("#settingsThemeSelect");
  select.value = "catppuccin-mocha";
  select.dispatchEvent(new w.Event("change", { bubbles: true }));

  const csBefore = w.getComputedStyle(d.documentElement);
  const defaultAccent = csBefore.getPropertyValue("--accent").trim();
  assert(defaultAccent === "#94e2d5", "sanity: Mocha's default accent (Teal) is active before picking, got " + defaultAccent);

  // Mauve (#cba6f7) is in Mocha's highlightPalette but clearly NOT the
  // default accent — a real re-pick, not a no-op.
  const mauveSwatch = [...d.querySelectorAll("#settingsAccentPicker .accent-swatch")].find(s => s.title === "#cba6f7");
  fireClick(mauveSwatch, w);

  const cs = w.getComputedStyle(d.documentElement);
  assert(cs.getPropertyValue("--accent").trim() === "#cba6f7", "picking Mauve sets --accent to it, got " + cs.getPropertyValue("--accent"));
  assert(cs.getPropertyValue("--accent-strong").trim() !== "#89dceb" && cs.getPropertyValue("--accent-strong").trim() !== "#cba6f7",
    "--accent-strong is recomputed too (not left at Mocha's old Sky default, and not identical to --accent either), got " + cs.getPropertyValue("--accent-strong"));
  assert(cs.getPropertyValue("--accent-soft").trim().startsWith("rgba(203,166,247,"), "--accent-soft is recomputed from the new accent's own RGB, got " + cs.getPropertyValue("--accent-soft"));
  assert(T.accentChoices["catppuccin-mocha"] === "#cba6f7", "the pick is recorded in accentChoices for Mocha specifically");
  assert(JSON.parse(w.localStorage.getItem("philogg-accent-choice"))["catppuccin-mocha"] === "#cba6f7", "...and persisted to localStorage");
  // renderAccentPicker() rebuilds the swatch row on every applyTheme() call
  // (same "new DOM nodes, not the same element" pattern as renderVisibleRows
  // — see PROJECT.md's jsdom gotcha), so re-query rather than reuse the
  // now-stale mauveSwatch reference from before the click.
  const mauveSwatchAfter = [...d.querySelectorAll("#settingsAccentPicker .accent-swatch")].find(s => s.title === "#cba6f7");
  assert(mauveSwatchAfter.classList.contains("active"), "the picked swatch shows as active");

  // Switch to a DIFFERENT theme: that theme's own default applies, Mocha's
  // pick is untouched (per-theme, not global).
  select.value = "catppuccin-latte";
  select.dispatchEvent(new w.Event("change", { bubbles: true }));
  assert(w.getComputedStyle(d.documentElement).getPropertyValue("--accent").trim() === "#209fb5", "Latte shows its OWN default accent, unaffected by Mocha's pick");

  // Switch back to Mocha: the pick survives.
  select.value = "catppuccin-mocha";
  select.dispatchEvent(new w.Event("change", { bubbles: true }));
  assert(w.getComputedStyle(d.documentElement).getPropertyValue("--accent").trim() === "#cba6f7", "switching back to Mocha restores the picked Mauve accent");

  // Reset (the ↺ swatch) clears the override and restores the theme's own default.
  fireClick(d.querySelector("#settingsAccentPicker .accent-swatch-reset"), w);
  assert(w.getComputedStyle(d.documentElement).getPropertyValue("--accent").trim() === "#94e2d5", "the reset swatch restores Mocha's default Teal accent");
  assert(!("catppuccin-mocha" in T.accentChoices), "...and clears the stored override for Mocha");
});

await withApp(async (w, d, T) => {
  section("87c. A dark, low-luminance accent pick flips --accent-on to white (contrast safety net)");
  w.setTheme("catppuccin-latte");
  // Latte's Red (#d20f39) is in its highlightPalette and dark/saturated
  // enough that the default near-black --accent-on would be unreadable.
  w.setAccentChoice("catppuccin-latte", "#d20f39");
  const cs = w.getComputedStyle(d.documentElement);
  assert(cs.getPropertyValue("--accent").trim() === "#d20f39", "sanity: the dark Red accent is active");
  assert(cs.getPropertyValue("--accent-on").trim() === "#fff", "a low-luminance accent pick flips --accent-on to white instead of staying near-black, got " + cs.getPropertyValue("--accent-on"));
});

/* ============================================================
   GROUP 88 — Catppuccin background hierarchy remapped to match the
   official style guide's "Background Pane"/"Secondary Panes" roles
   Origin: this session (2026-08-22), person-directed after a style-guide
   compliance audit flagged the ORIGINAL mapping (kept for consistency
   with this app's own pre-existing Dark/Light hierarchy — main pane
   darkest, panel brighter) as inverted relative to the guide's intent
   (main pane = Base, a brighter tone; secondary/chrome panes = the
   darker Crust/Mantle). Asked, and told to remap instead of leaving it —
   see PROJECT.md "Theming" -> "Catppuccin style-guide compliance" for
   the full token-role table (--bg-app=Base, --bg-panel=Mantle,
   --bg-elevated=Surface0, --bg-elevated-2=Surface1, --border-soft=
   Surface2, --border=Overlay0 — same role mapping for all four flavors,
   including Latte, where Base happens to be the brightest token instead
   of a dark-flavor middle tone).
   ============================================================ */
group(88);
await withApp(async (w, d, T) => {
  section("88. Background/border hierarchy: --bg-app (main pane) resolves to Base, brighter than --bg-panel (Mantle) — same role mapping across all four flavors, including inverted-brightness Latte");
  const mochaExpected = { "bg-app": "#1e1e2e", "bg-panel": "#181825", "bg-elevated": "#313244", "bg-elevated-2": "#45475a", "border-soft": "#585b70", "border": "#6c7086" };
  const macchiatoExpected = { "bg-app": "#24273a", "bg-panel": "#1e2030", "bg-elevated": "#363a4f", "bg-elevated-2": "#494d64", "border-soft": "#5b6078", "border": "#6e738d" };
  const frappeExpected = { "bg-app": "#303446", "bg-panel": "#292c3c", "bg-elevated": "#414559", "bg-elevated-2": "#51576d", "border-soft": "#626880", "border": "#737994" };
  const latteExpected = { "bg-app": "#eff1f5", "bg-panel": "#e6e9ef", "bg-elevated": "#ccd0da", "bg-elevated-2": "#bcc0cc", "border-soft": "#acb0be", "border": "#9ca0b0" };

  [
    ["catppuccin-mocha", mochaExpected],
    ["catppuccin-macchiato", macchiatoExpected],
    ["catppuccin-frappe", frappeExpected],
    ["catppuccin-latte", latteExpected],
  ].forEach(([themeId, expected]) => {
    w.setTheme(themeId);
    const cs = w.getComputedStyle(d.documentElement);
    Object.entries(expected).forEach(([key, hex]) => {
      assert(cs.getPropertyValue("--" + key).trim() === hex, themeId + "'s --" + key + " is " + hex + " per the guide's role mapping, got " + cs.getPropertyValue("--" + key));
    });
  });

  // "On Accent" text = Base = --bg-app in this remap, for every flavor
  // uniformly (previously --bg-elevated for the dark flavors / --bg-panel
  // for Latte, back when those vars held Base — see 85a's own comment).
  ["catppuccin-mocha", "catppuccin-macchiato", "catppuccin-frappe", "catppuccin-latte"].forEach(themeId => {
    w.setTheme(themeId);
    const cs = w.getComputedStyle(d.documentElement);
    assert(cs.getPropertyValue("--accent-on").trim() === "var(--bg-app)", themeId + "'s --accent-on points at --bg-app (Base), got " + cs.getPropertyValue("--accent-on"));
  });
});

/* ============================================================
   GROUP 81 — Wildcard placeholder value conditions
   Origin: this session (2026-08-22), person-requested (FEATURE_BACKLOG.md
   item 5, implemented differently than originally scoped there — a numeric
   condition folded INTO the existing [*:...] wildcard token instead of
   a separate filter type, and working through the existing filter/extract
   paths only, per the person's explicit instructions). Syntax:
   [*:float>=10] (single condition) or [*:int<20,>10] (","-separated
   conditions AND-ed together). A same-day follow-up (person asked "hältst
   du den [Syntax] für sinnvoll... und ich glaube es würde Sinn machen, auch
   absolut mit reinzunehmen") swapped the separator from the originally
   shipped ";" to "," (more conventional) and added an absolute-value
   variant: a "|" prefix on the operator compares |value| instead of value,
   e.g. [*:float|>=10] matches both 10 and -15. Conditions are parsed by
   compileExtractPattern onto each column as `.conditions: [{op, value,
   abs?}]` (float/int only — a condition on time/word/hex makes the whole
   pattern invalid, same "Invalid pattern" feedback path as a malformed
   regex) and checked post-match by the shared wildcardMatch() primitive,
   reused by extraction (getEntries' "extract" branch), a plain "text"
   filter carrying wildcard tokens (the "Add filter" path), and the filter
   popup's live-match count/pattern preview — so all four surfaces agree on
   what a conditioned placeholder matches. No new filter-node field: the
   condition lives inside the existing `value` pattern string, so every
   persistence carrier already threads it through untouched (CLAUDE.md's
   "Known gotchas" note doesn't apply here).
   ============================================================ */
group(81);
await withApp(async (w, d, T) => {
  section("81. Wildcard placeholder value conditions ([*:float>=10] etc.)");
  // message 0 score=0 .. message 19 score=19
  const log = makeLog(0, 20, { suffix: i => "score=" + i });
  const f = await w.addFile("a.log", log, () => {});
  w.render();
  T.state.activeId = f.id;

  /* ---------- compileExtractPattern: parsing ---------- */
  const spec1 = w.compileExtractPattern("score=[*:int>=10]");
  assert(spec1 && spec1.columns.length === 1, "single-condition pattern compiles");
  assert(JSON.stringify(spec1.columns[0].conditions) === JSON.stringify([{ op: ">=", value: 10 }]),
    "parses a single >= condition, got " + JSON.stringify(spec1 && spec1.columns[0].conditions));

  const spec2 = w.compileExtractPattern("score=[*:int<15,>=10]");
  assert(spec2 && spec2.columns[0].conditions && spec2.columns[0].conditions.length === 2,
    "parses two ','-separated conditions, got " + JSON.stringify(spec2 && spec2.columns[0].conditions));
  assert(spec2.columns[0].conditions[0].op === "<" && spec2.columns[0].conditions[0].value === 15, "first condition parsed in order");
  assert(spec2.columns[0].conditions[1].op === ">=" && spec2.columns[0].conditions[1].value === 10, "second condition parsed in order");
  assert(!spec2.columns[0].conditions[0].abs && !spec2.columns[0].conditions[1].abs, "plain conditions carry no .abs flag");

  const specPlain = w.compileExtractPattern("score=[*:int]");
  assert(specPlain.columns[0].conditions === undefined, "a bare placeholder (no condition) still has no .conditions field — backward compatible");

  assert(w.compileExtractPattern("id=[*:word>=10]") === null, "a condition on a non-numeric type (word) makes the whole pattern invalid");
  assert(w.compileExtractPattern("t=[*:time>=10]") === null, "same rejection for time");
  assert(w.compileExtractPattern("h=[*:hex>=10]") === null, "same rejection for hex");

  /* ---------- absolute-value conditions: a "|" prefix on the operator ---------- */
  const specAbs = w.compileExtractPattern("d=[*:int|>=10]");
  assert(specAbs && specAbs.columns[0].conditions.length === 1 && specAbs.columns[0].conditions[0].abs === true,
    "a '|' prefix on the operator sets .abs on the condition, got " + JSON.stringify(specAbs && specAbs.columns[0].conditions));
  assert(specAbs.columns[0].conditions[0].op === ">=" && specAbs.columns[0].conditions[0].value === 10, "the operator/value themselves parse the same regardless of the abs prefix");

  const specAbsMixed = w.compileExtractPattern("d=[*:int|>10,<=100]");
  assert(specAbsMixed.columns[0].conditions[0].abs === true && !specAbsMixed.columns[0].conditions[1].abs,
    "abs applies per-condition — a mix of abs and plain conditions in one placeholder parses correctly, got " + JSON.stringify(specAbsMixed.columns[0].conditions));

  /* ---------- extraction: only rows satisfying the condition are kept ---------- */
  const geNode = w.createFilterNode(f.id, "text", "score=[*:int>=10]");
  assert(w.getEntries(geNode.id).length === 10, "extract >=10 keeps rows 10..19, got " + w.getEntries(geNode.id).length);

  const rangeNode = w.createFilterNode(f.id, "text", "score=[*:int<15,>=10]");
  const rangeEntries = w.getEntries(rangeNode.id);
  assert(rangeEntries.length === 5, "combined </>= condition keeps only rows 10..14, got " + rangeEntries.length);
  assert(rangeEntries.every(e => { const v = +e.message.match(/score=(\d+)/)[1]; return v >= 10 && v < 15; }),
    "sanity: every kept row's score is actually in [10,15)");

  /* ---------- absolute-value matching against real signed data ---------- */
  const deltaLog = [-20, -5, 0, 5, 20]
    .map((v, i) => `2024-01-15 10:00:0${i},000\tINFO\t"main"\tC:\\src\\Foo.cs\tline ${i}\t[DoWork]\t"delta=${v}"`)
    .join("\n") + "\n";
  const fd = await w.addFile("d.log", deltaLog, () => {});
  const absNode = w.createFilterNode(fd.id, "text", "delta=[*:int|>=10]");
  const absEntries = w.getEntries(absNode.id);
  assert(absEntries.length === 2, "|value|>=10 matches both -20 and 20 (not the three values inside [-10,10]), got " + absEntries.length);
  assert(absEntries.every(e => Math.abs(+e.message.match(/delta=(-?\d+)/)[1]) >= 10), "sanity: every kept row's |delta| is actually >= 10");
  const nonAbsNode = w.createFilterNode(fd.id, "text", "delta=[*:int>=10]");
  assert(w.getEntries(nonAbsNode.id).length === 1, "the same threshold WITHOUT the abs prefix only matches +20 (plain >=10), got " + w.getEntries(nonAbsNode.id).length);

  /* ---------- a plain "text" filter carrying a conditioned wildcard token (the "Add filter" path) respects it too ---------- */
  const textNode = w.createFilterNode(f.id, "text", "score=[*:int>=10]");
  assert(w.getEntries(textNode.id).length === 10, "a plain text filter with a conditioned wildcard token matches the same 10 rows");

  /* ---------- table rendering: header badge + every rendered row honors the condition ---------- */
  T.state.activeId = rangeNode.id;
  w.render();
  w.applyFhView("table");
  const headerType = d.querySelector('#extractHead th[data-col="0"] .extract-col-type').textContent;
  assert(headerType.includes("int") && headerType.includes("<15") && headerType.includes("≥10"),
    "extraction table header shows the condition next to the type, got " + JSON.stringify(headerType));
  assert(T.extractRowsData.length === 5 && T.extractRowsData.every(r => { const v = +r.values[0]; return v >= 10 && v < 15; }),
    "every row actually rendered into the table satisfies the condition");

  /* ---------- post-creation pattern view chip shows the condition too ---------- */
  const chipText = d.querySelector("#extractPatternView .pattern-chip").textContent;
  assert(chipText.includes("int") && chipText.includes("<15") && chipText.includes("≥10"),
    "the pattern-view chip above the table shows the condition alongside the type, got " + JSON.stringify(chipText));

  /* ---------- table header visualizes an abs condition with a leading "|" ---------- */
  T.state.activeId = absNode.id;
  w.render();
  w.applyFhView("table");
  const absHeaderType = d.querySelector('#extractHead th[data-col="0"] .extract-col-type').textContent;
  assert(absHeaderType.includes("|≥10"), "an abs condition's header badge is prefixed with '|', got " + JSON.stringify(absHeaderType));

  /* ---------- filter popup: live-match count reflects the condition ---------- */
  T.state.activeId = f.id;
  w.render();
  w.openFilterPopup();
  const filterInput = d.querySelector("#filterInput");
  filterInput.value = "score=[*:int>=15]";
  fireInput(filterInput, w);
  await new Promise(r => setTimeout(r, 200));
  assert(d.querySelector("#filterLiveMatch").textContent.includes("5 of 20"),
    "live-match count only counts rows satisfying the condition (15..19), got " + d.querySelector("#filterLiveMatch").textContent);

  /* ---------- pattern preview: the sample match is one where the condition actually holds, and shows a visible condition badge ---------- */
  const preview = d.querySelector("#filterPatternPreview");
  const span = preview.querySelector(".preview-value-span");
  assert(span && span.textContent === "15",
    "the preview picks the first entry satisfying the CONDITION (score=15), not just the first structural regex match (score=0), got " + (span && span.textContent));
  const condBadge = preview.querySelector(".preview-value-cond");
  assert(condBadge && condBadge.textContent === "≥15", "the preview shows a visible badge with the condition, got " + (condBadge && condBadge.textContent));

  // An unsatisfiable condition (no row has score >= 1000) shows the
  // "no matching sample" state, same as a pattern that structurally never matches.
  filterInput.value = "score=[*:int>=1000]";
  fireInput(filterInput, w);
  await new Promise(r => setTimeout(r, 200));
  assert(preview.classList.contains("preview-empty") && preview.textContent.includes("No matching sample"),
    "an unsatisfiable condition falls back to the 'no matching sample' preview state, not a structural-only match");
  w.closeFilterPopup();

  /* ---------- pattern preview against signed data: abs badge + a NEGATIVE sample ---------- */
  T.state.activeId = fd.id;
  w.render();
  w.openFilterPopup();
  const filterInput2 = d.querySelector("#filterInput");
  filterInput2.value = "delta=[*:int|>=10]";
  fireInput(filterInput2, w);
  await new Promise(r => setTimeout(r, 200));
  const absSpan = preview.querySelector(".preview-value-span");
  assert(absSpan && absSpan.textContent === "-20",
    "the preview's first sample for an abs condition can be a NEGATIVE value (-20, the first entry in log order satisfying |delta|>=10), got " + (absSpan && absSpan.textContent));
  const absCondBadge = preview.querySelector(".preview-value-cond");
  assert(absCondBadge && absCondBadge.textContent === "|≥10", "the preview's condition badge is prefixed with '|' for an abs condition, got " + (absCondBadge && absCondBadge.textContent));
  w.closeFilterPopup();
});

/* ============================================================
   GROUP 90 — "Main window visual consistency fix" (this session,
   2026-08-22): the toolbar/view-bar button system never got the same
   treatment the Settings dialog's .btn-mini system did — every button-like
   control hand-tuned its own padding/line-height to coincidentally match
   its neighbors (three rounds of now-removed "height-parity bugfix"
   comments; see Group 26/29b's updated assertions for the resulting
   shared-28px-height behavior this replaced them with), and the three
   panel resizers (#sidebarResizer/#fhSplitResizer/#detailResizer) were
   fully transparent at rest, reading as a stray dark seam rather than an
   intentional divider. This group covers what Group 26/29b don't: the
   resizers' now-permanent grip affordance, the --border/--border-soft
   token mismatch at the sidebar/minimap seam, and the #btnOpen/#btnSession
   rule merge. Asserted via raw stylesheet text (same pattern as Group
   86a's audit) rather than computed style — jsdom's getComputedStyle
   doesn't resolve ::after pseudo-element styles, so these are checked as
   cascaded CSS text instead of computed pixels, same blind spot documented
   in "Testing approach".
   ============================================================ */
group(90);
await withApp(async (w, d) => {
  section("90. Main window visual consistency fix: resizer grip affordance, sidebar/minimap border token");
  const css = d.querySelector("style").textContent;

  // --- Problem 2: resizers get a permanent (non-transparent) grip, not just an on-hover reveal ---
  ["#sidebarResizer", "#fhSplitResizer", "#detailResizer"].forEach(sel => {
    const ruleMatch = css.match(new RegExp(sel + "::after\\{[^}]*\\}"));
    assert(ruleMatch, sel + "::after rule exists");
    assert(ruleMatch && ruleMatch[0].includes("background:var(--border)"),
      sel + "::after has a permanent var(--border) grip background at rest, not transparent, got " + (ruleMatch && ruleMatch[0]));
    assert(ruleMatch && !ruleMatch[0].includes("background:transparent"),
      sel + "::after no longer starts fully transparent (was the 'stray dark seam' bug)");
    // Hover/drag brightening to --accent is pre-existing behavior, unchanged by this session.
    assert(css.includes(sel + ":hover::after, " + sel + ".dragging::after{ background:var(--accent); }"),
      sel + " still brightens to var(--accent) on hover/drag");
  });

  // --- Problem 2: sidebar/minimap seam now agrees on the same border token ---
  const minimapRule = css.match(/#timelineMinimap\{[^}]*\}/);
  assert(minimapRule && minimapRule[0].includes("border-bottom:1px solid var(--border)") && !minimapRule[0].includes("border-bottom:1px solid var(--border-soft)"),
    "#timelineMinimap's border-bottom now uses --border (matching #sidebar's own border-right token at the same seam), not --border-soft, got " + (minimapRule && minimapRule[0]));
  const sidebarRule = css.match(/#sidebar\{[^}]*\}/);
  assert(sidebarRule && sidebarRule[0].includes("border-right:1px solid var(--border)"),
    "sanity: #sidebar's own border-right is still var(--border)");
});

/* ============================================================
   GROUP 91 — Entry Detail gets the sidebar's hover-peek behavior
   (person-requested, this session, 2026-08-22, extended same-day
   follow-up after person-reported screenshot feedback): the detail panel
   peeks open on hover while collapsed, same mechanism as the sidebar
   (Group 80) but expanding upward instead of rightward. Both panels' peek
   size is content-sized (width/height:max-content) capped at 50% of the
   application (max-width:50vw / max-height:50vh) instead of the
   sidebar's old fixed 270px.

   Follow-up fix (same session): the first cut anchored only #detailBody
   above the still-truncated 34px header, so the peek showed the message
   floating ABOVE a header that still read like the collapsed state — not
   what "same visual as expanded" means. Fixed by wrapping
   #detailPanelHeader + #detailBody in a new #detailPanelInner (mirroring
   #sidebarNormalContent, which already wraps the sidebar's header+scroll
   as one peekable unit) and anchoring THAT as the overlay
   (bottom:0 of the collapsed 34px #detailPanel, no `top`, so it grows
   upward) — header on top with the full field set, message below it,
   pixel-identical structure to the expanded state, just floating.
   updateDetailPanel() now branches on `isDetailCollapsed() &&
   !isDetailPeeking()`, not just isDetailCollapsed(), so the header shows
   the full level/time/thread/location/method fields while peeking instead
   of the collapsed one-line summary.

   Also follow-up (same feedback): the single combined "Open collapsed
   views on hover" setting became two independent ones —
   #settingsHoverExpandSidebar / #settingsHoverExpandDetail
   (hoverExpandSidebar/hoverExpandDetail,
   philogg-hover-expand-sidebar/-detail in localStorage) — so hovering one
   panel can be toggled without affecting the other. Both default ON.

   Icon-swap-to-pin-while-peeking is asserted via the raw SVG markup (a
   "<circle" only appears in ICON_PIN, not any chevron) since the icon
   constants aren't exposed on the bridge (top-level const, see withApp's
   own comment). max-width/max-height capping is asserted via raw
   stylesheet text, same reasoning as Group 90 (jsdom has no real layout
   engine to measure resolved pixel sizes against).
   ============================================================ */
group(91);
await withApp(async (w, d, T) => {
  section("91. Entry Detail hover-peek (matching the sidebar's expanded look) + content-sized/50%-capped peek + per-panel hover settings");

  const sidebarEl = d.querySelector("#sidebar");
  const detailPanel = d.querySelector("#detailPanel");
  const detailPanelInner = d.querySelector("#detailPanelInner");
  const detailBody = d.querySelector("#detailBody");
  const detailToggleBtn = d.querySelector("#detailToggle");
  const detailMeta = d.querySelector("#detailMeta");
  const detailResizerEl = d.querySelector("#detailResizer");
  const sidebarCb = d.querySelector("#settingsHoverExpandSidebar");
  const detailCb = d.querySelector("#settingsHoverExpandDetail");

  // --- Both default to on ---
  assert(sidebarCb.checked === true && detailCb.checked === true, "both hover-expand settings default to ON");

  // A selected entry so the header meta line has real content to check.
  const f = await w.addFile("a.log", makeLog(0, 5), () => {});
  T.state.activeId = f.id;
  w.selectEntry(f.entries[0].id);
  w.render();

  // --- Detail panel peeks on hover while collapsed, matching the
  //     EXPANDED look: header shows the full field set (not the truncated
  //     one-liner), message sits below it, no drag handle ---
  w.toggleDetailCollapsed(true);
  assert(!isVisible(detailBody, w), "collapsed, not hovering: body hidden");
  assert(detailMeta.querySelector(".detail-collapsed-msg") && !detailMeta.querySelector(".detail-thread"),
    "collapsed, not hovering: header still shows the truncated summary");
  detailPanel.dispatchEvent(new w.MouseEvent("mouseenter", { bubbles: false }));
  assert(detailPanel.classList.contains("peeking"), "hovering a collapsed detail panel enters peek state");
  assert(isVisible(detailBody, w), "...revealing the SAME body element used when expanded");
  assert(detailMeta.querySelector(".detail-thread") && !detailMeta.querySelector(".detail-collapsed-msg"),
    "...and the header now shows the full field set, exactly like expanded — not the collapsed summary");
  assert(detailToggleBtn.innerHTML.includes("<circle"), "toggle icon swaps to the pin icon while peeking");
  assert(!isVisible(detailResizerEl, w), "no drag handle while peeking (still logically collapsed)");
  detailPanel.dispatchEvent(new w.MouseEvent("mouseleave", { bubbles: false }));
  assert(!detailPanel.classList.contains("peeking") && !isVisible(detailBody, w), "leaving collapses the body again");
  assert(detailMeta.querySelector(".detail-collapsed-msg") && !detailMeta.querySelector(".detail-thread"),
    "...and the header reverts to the truncated summary");
  assert(!detailToggleBtn.innerHTML.includes("<circle"), "toggle icon reverts to a chevron once peeking ends");

  // Clicking the toggle while peeking pins it open (same as the sidebar) —
  // the toggle button sits in #detailPanelHeader, the same place it always
  // does, not somewhere new for the peek state.
  detailPanel.dispatchEvent(new w.MouseEvent("mouseenter", { bubbles: false }));
  fireClick(detailToggleBtn, w);
  assert(!detailPanel.classList.contains("collapsed") && !detailPanel.classList.contains("peeking"),
    "clicking the toggle while peeking pins the detail panel fully open");
  assert(detailMeta.querySelector(".detail-thread"), "...and the full field set stays shown, now because it's genuinely expanded");

  // --- Content-sized, capped at 50% of the application (CSS text audit,
  //     same technique as Group 90 — jsdom can't measure real pixel sizes).
  //     The detail panel's overlay is #detailPanelInner (header+body
  //     together), not #detailBody alone. ---
  const css = d.querySelector("style").textContent;
  const sidebarPeekRule = css.match(/#sidebar\.collapsed\.peeking #sidebarNormalContent\{[^}]*\}/);
  assert(sidebarPeekRule && sidebarPeekRule[0].includes("width:max-content") && sidebarPeekRule[0].includes("max-width:50vw"),
    "sidebar peek overlay is sized to content, capped at 50% of the app's width, got " + (sidebarPeekRule && sidebarPeekRule[0]));
  assert(sidebarPeekRule && !sidebarPeekRule[0].includes("width:270px"),
    "...no longer the old fixed 270px");
  const detailPeekRule = css.match(/#detailPanel\.collapsed\.peeking #detailPanelInner\{[^}]*\}/);
  assert(detailPeekRule && detailPeekRule[0].includes("max-height:50vh"),
    "detail panel peek overlay (the whole header+body wrapper) is capped at 50% of the app's height, got " + (detailPeekRule && detailPeekRule[0]));
  assert(detailPeekRule && detailPeekRule[0].includes("bottom:0") && !detailPeekRule[0].includes("top:0"),
    "...anchored flush to the collapsed panel's bottom edge with no top set, so it grows upward from there");
  assert(!css.match(/#detailPanel\.collapsed\.peeking #detailBody\{[^}]*\}/),
    "the old #detailBody-only peek rule is gone — #detailPanelInner replaces it");

  // --- Regression guard (person-reported via screenshot, same session):
  //     #detailPanel is shown/hidden via an INLINE style.display "flex"/
  //     "none" set from renderMainView/renderTable (unrelated to this
  //     feature — hasFiles/no-files toggling), which overrides any CSS
  //     `display` on #detailPanel but leaves `flex-direction` alone. When
  //     #detailPanelInner's introduction dropped `flex-direction:column`
  //     from #detailPanel's own CSS, that inline "flex" fell back to
  //     row (flex-direction's initial value) whenever a file was loaded,
  //     turning #detailPanelInner into a ROW flex item that shrinks to its
  //     content width — visually: the Entry Detail bar stopping partway
  //     across the window instead of reaching the right edge, in EVERY
  //     state (pinned, collapsed, peeking), not just while peeking.
  //     jsdom's getComputedStyle doesn't resolve real flex cross-axis
  //     stretch sizing (no layout engine — see "Testing approach" in
  //     PROJECT.md), so this can't be asserted via a rendered width the
  //     way the peek rules above are; verified instead via a real
  //     Playwright screenshot this session, and guarded here the same way
  //     Group 90's CSS-text audits guard their own pure-CSS fixes. ---
  const detailPanelRule = css.match(/#detailPanel\{[^}]*\}/);
  assert(detailPanelRule && detailPanelRule[0].includes("flex-direction:column"),
    "#detailPanel keeps its own flex-direction:column — without it, the inline style.display=\"flex\" set from renderMainView/renderTable falls back to row and #detailPanelInner shrinks to content width, got " + (detailPanelRule && detailPanelRule[0]));

  // --- Second regression guard, same root cause, same person-reported
  //     screenshot round (a follow-up screenshot after the width fix
  //     above): #detailPanel's rule declares `min-height:80px` (a floor
  //     for the manual drag-resizer) THEN `min-height:0` later in the same
  //     rule — last declaration of the same property wins, so the actual
  //     effective min-height was always 0, the 80px never really applied.
  //     Moving `min-height:0` onto #detailPanelInner during the same
  //     #detailPanelInner refactor left `min-height:80px` as the only
  //     min-height left on #detailPanel — and min-height always clamps the
  //     used height upward regardless of whether the 34px it's clamping
  //     comes from this stylesheet or the collapsed-state inline style set
  //     by toggleDetailCollapsed, so the collapsed panel silently rendered
  //     at 80px, leaving a real ~46px empty gap below the header instead
  //     of the header being the panel's bottom edge. Text order matters
  //     here (CSS cascade = last declaration of the same property, at
  //     equal specificity, wins) — checking substring order, not just
  //     presence. ---
  assert(detailPanelRule && /min-height:80px[\s\S]*min-height:0\b/.test(detailPanelRule[0]),
    "#detailPanel's min-height:0 comes AFTER min-height:80px in the same rule (so it's the one that actually wins) — without it the 80px floor clamps the collapsed 34px height, leaving an empty gap below the header, got " + (detailPanelRule && detailPanelRule[0]));

  // --- Each panel's setting independently gates only that panel's hover ---
  detailCb.checked = false;
  detailCb.dispatchEvent(new w.Event("change", { bubbles: true }));
  assert(w.localStorage.getItem("philogg-hover-expand-detail") === "0", "unchecking the detail setting persists it as off");
  assert(w.localStorage.getItem("philogg-hover-expand-sidebar") !== "0", "...without touching the sidebar's own setting");

  w.toggleSidebarCollapsed(true);
  sidebarEl.dispatchEvent(new w.MouseEvent("mouseenter", { bubbles: false }));
  assert(sidebarEl.classList.contains("peeking"), "sidebar hover still peeks — its own setting is untouched");
  w.toggleDetailCollapsed(true);
  detailPanel.dispatchEvent(new w.MouseEvent("mouseenter", { bubbles: false }));
  assert(!detailPanel.classList.contains("peeking"), "detail panel hover no longer peeks while ONLY its own setting is off");

  // Manual click-to-expand is unaffected by either setting.
  fireClick(d.querySelector("#sidebarToggle"), w);
  assert(!sidebarEl.classList.contains("collapsed"), "sidebar still expands manually via its toggle button");
  fireClick(detailToggleBtn, w);
  assert(!detailPanel.classList.contains("collapsed"), "detail panel still expands manually via its toggle button with its own hover disabled");

  // Toggling a panel to peeking, THEN turning its own setting off, drops it
  // out of peek immediately instead of leaving it stuck open.
  detailCb.checked = true;
  detailCb.dispatchEvent(new w.Event("change", { bubbles: true }));
  w.toggleDetailCollapsed(true);
  detailPanel.dispatchEvent(new w.MouseEvent("mouseenter", { bubbles: false }));
  assert(detailPanel.classList.contains("peeking"), "sanity: detail panel peeks again once its setting is back on");
  detailCb.checked = false;
  detailCb.dispatchEvent(new w.Event("change", { bubbles: true }));
  assert(!detailPanel.classList.contains("peeking"), "turning the detail setting off mid-peek exits peek state immediately");

  // --- Persisted flags honored on (re-)init, same path real boot uses,
  //     independently per panel ---
  w.localStorage.setItem("philogg-hover-expand-sidebar", "0");
  w.localStorage.setItem("philogg-hover-expand-detail", "1");
  w.initHoverExpandSettings();
  assert(sidebarCb.checked === false && detailCb.checked === true,
    "initHoverExpandSettings re-applies persisted flags independently per panel, same as at boot");
  w.toggleSidebarCollapsed(true);
  sidebarEl.dispatchEvent(new w.MouseEvent("mouseenter", { bubbles: false }));
  assert(!sidebarEl.classList.contains("peeking"), "...sidebar's re-applied off flag actually gates its hover handler");
  w.toggleDetailCollapsed(true);
  detailPanel.dispatchEvent(new w.MouseEvent("mouseenter", { bubbles: false }));
  assert(detailPanel.classList.contains("peeking"), "...while detail's re-applied on flag keeps its own hover working");

  w.localStorage.setItem("philogg-hover-expand-sidebar", "1");
  w.initHoverExpandSettings();
  assert(sidebarCb.checked === true, "...and a persisted on flag");
  sidebarEl.dispatchEvent(new w.MouseEvent("mouseenter", { bubbles: false }));
  assert(sidebarEl.classList.contains("peeking"), "...re-enabling the sidebar's hover behavior too");
});

/* ============================================================
   GROUP 93 — Text-filter match highlighting (this session, 2026-08-23,
   person-requested alternative implementation of FEATURE_BACKLOG.md #13's
   "why is this row here" popup idea — that entry itself is left untouched).
   Marks the substring an active "text" filter node actually matched, right
   inside the Filter view's rows and/or the entry-detail panel. The master
   on/off is a view-bar toggle button, #btnTextMatchHighlight (same
   plain-persistent-toggle shape as #btnPinBookmarks/#btnMultilineMsg,
   person-requested move out of Settings same-day follow-up). Settings ->
   Behavior keeps #settingsTextMatchHighlightScope ("last"/"any", default
   "last") and the two independent "where" toggles,
   #settingsTextMatchHighlightRows/-Detail (both default ON) — a same-day
   follow-up explicitly asked for these rows to stay visible/editable
   regardless of the master button's state (a standing preference the button
   just flips, not a gate on configuring it).
   ============================================================ */
group(93);
await withApp(async (w, d, T) => {
  section("93. Text-filter match highlighting");

  const btn = d.querySelector(".toggle-textmatch");
  const scopeSelect = d.querySelector("#settingsTextMatchHighlightScope");
  const rowsCb = d.querySelector("#settingsTextMatchHighlightRows");
  const detailCb = d.querySelector("#settingsTextMatchHighlightDetail");

  // --- Defaults ---
  assert(btn.classList.contains("active") && T.textMatchHighlightEnabled === true, "master view-bar button defaults ON");
  assert(scopeSelect.value === "last" && T.textMatchHighlightScope === "last", "settings scope defaults to 'last'");
  assert(rowsCb.checked === true && T.textMatchHighlightInRows === true, "'show in rows' defaults ON");
  assert(detailCb.checked === true && T.textMatchHighlightInDetail === true, "'show in entry detail' defaults ON");
  assert(isVisible(scopeSelect, w) && isVisible(rowsCb, w) && isVisible(detailCb, w), "all three settings controls are visible");

  // --- Clicking the master button off does NOT hide/disable the Settings
  //     controls — they stay a fully editable standing preference, only the
  //     highlighting itself (checked separately below) is suppressed ---
  fireClick(btn, w);
  assert(!T.textMatchHighlightEnabled && !btn.classList.contains("active"), "clicking the button turns the master off");
  assert(w.localStorage.getItem("philogg-text-match-highlight-enabled") === "0", "master state persisted as off");
  assert(isVisible(scopeSelect, w) && !scopeSelect.disabled, "scope select stays visible and enabled while the master button is off");
  assert(isVisible(rowsCb, w) && !rowsCb.disabled && isVisible(detailCb, w) && !detailCb.disabled,
    "both 'where' toggles stay visible and enabled too — no dependency of Settings on the button's state");
  scopeSelect.value = "any";
  scopeSelect.dispatchEvent(new w.Event("change", { bubbles: true }));
  assert(T.textMatchHighlightScope === "any", "the scope preference is still changeable while the master button is off");
  scopeSelect.value = "last";
  scopeSelect.dispatchEvent(new w.Event("change", { bubbles: true }));
  fireClick(btn, w);
  assert(T.textMatchHighlightEnabled && btn.classList.contains("active"), "clicking it again turns the master back on");

  // file -> nodeA (text "alpha", matches everything) -> nodeB (text "1",
  // scoped to the message column — a column-less filter searches the whole
  // raw line, see textFilterMatches, and the raw line's date/hour always
  // contains a "1", which would make this scenario trivially match every
  // row; matches messages containing "1": msg 1 and 10-19 = 11 of 20, same
  // shape as GROUP 2's substring assertion).
  const f = await w.addFile("app.log", makeLog(0, 20, { msgPrefix: "alpha" }), () => {});
  const nodeA = w.createFilterNode(f.id, "text", "alpha", false, null, false, ["message"]);
  const nodeB = w.createFilterNode(nodeA.id, "text", "1", false, null, false, ["message"]);

  // --- "last" scope, active = nodeB (a text filter): only nodeB's match
  //     ("1") is marked, not nodeA's ("alpha") ---
  T.state.activeId = nodeB.id;
  w.render();
  let msgEl = d.querySelector("#tableRows .log-row .col-msg");
  assert(msgEl.innerHTML.includes('<mark class="text-match-mark">1</mark>'), "'last' scope marks the active node's own match");
  assert(!msgEl.innerHTML.includes(">alpha<") && !/<mark[^>]*>alpha<\/mark>/.test(msgEl.innerHTML),
    "'last' scope does NOT mark the ancestor's match, only the active node's");

  // --- "last" scope, active = nodeA itself (also a text filter): nodeA's
  //     own match ("alpha") is marked ---
  T.state.activeId = nodeA.id;
  w.render();
  msgEl = d.querySelector("#tableRows .log-row .col-msg");
  assert(/<mark class="text-match-mark">alpha<\/mark>/i.test(msgEl.innerHTML), "'last' scope on nodeA marks nodeA's own match");

  // --- "any" scope, active = nodeB: BOTH ancestor chain matches are marked ---
  scopeSelect.value = "any";
  scopeSelect.dispatchEvent(new w.Event("change", { bubbles: true }));
  assert(w.localStorage.getItem("philogg-text-match-highlight-scope") === "any", "scope choice persisted");
  T.state.activeId = nodeB.id;
  w.render();
  msgEl = d.querySelector("#tableRows .log-row .col-msg");
  assert(/<mark class="text-match-mark">alpha<\/mark>/i.test(msgEl.innerHTML) && msgEl.innerHTML.includes('<mark class="text-match-mark">1</mark>'),
    "'any' scope marks matches from every text-filter node in the chain, not just the active one");

  // --- "last" scope with the active node NOT a text filter: no highlight at
  //     all, even though its parent (nodeB) is a text filter — no fallback
  //     to a text-filter ancestor, per the explicit design decision ---
  scopeSelect.value = "last";
  scopeSelect.dispatchEvent(new w.Event("change", { bubbles: true }));
  const afterNode = w.createFilterNode(nodeB.id, "after", f.entries[0].ts);
  T.state.activeId = afterNode.id;
  w.render();
  msgEl = d.querySelector("#tableRows .log-row .col-msg");
  assert(!/<mark/.test(msgEl.innerHTML), "'last' scope shows no highlight when the active node itself isn't a text filter (no ancestor fallback)");
  assert(w.getTextMatchHighlightNodes().length === 0, "getTextMatchHighlightNodes() returns nothing for a non-text active node in 'last' scope");

  // --- Column-scoped text filter: a "thread"-restricted filter marks the
  //     Thread column, not the Message column (per the "highlight in the
  //     matching column" design decision) ---
  const threadNode = w.createFilterNode(f.id, "text", "main", false, null, false, ["thread"]);
  T.state.activeId = threadNode.id;
  w.render();
  const row = d.querySelector("#tableRows .log-row");
  assert(/<mark class="text-match-mark">main<\/mark>/i.test(row.querySelector(".col-thread").innerHTML), "a thread-scoped filter marks the Thread column");
  assert(!/<mark/.test(row.querySelector(".col-msg").innerHTML), "...and does NOT mark the Message column, which the filter isn't scoped to");

  // --- "Show in rows" OFF suppresses row marks; "show in entry detail" is
  //     independent and keeps working ---
  T.state.activeId = nodeB.id;
  w.render();
  rowsCb.checked = false;
  rowsCb.dispatchEvent(new w.Event("change", { bubbles: true }));
  assert(w.localStorage.getItem("philogg-text-match-highlight-rows") === "0", "'show in rows' persisted off");
  msgEl = d.querySelector("#tableRows .log-row .col-msg");
  assert(!/<mark/.test(msgEl.innerHTML), "turning off 'show in rows' removes row marks immediately");

  T.state.selectedId = f.entries[1].id; // message "alpha 1" — contains nodeB's "1" match
  w.updateDetailPanel();
  const detailMsgEl = d.querySelector("#detailMessage");
  assert(/<mark class="text-match-mark">1<\/mark>/.test(detailMsgEl.innerHTML), "entry-detail message still marks matches while row-highlighting is off (independent toggle)");

  detailCb.checked = false;
  detailCb.dispatchEvent(new w.Event("change", { bubbles: true }));
  assert(w.localStorage.getItem("philogg-text-match-highlight-detail") === "0", "'show in entry detail' persisted off");
  w.updateDetailPanel();
  assert(!/<mark/.test(d.querySelector("#detailMessage").innerHTML), "turning off 'show in entry detail' removes detail-panel marks immediately");
  assert(d.querySelector("#detailMessage").textContent.length > 0, "detail message text itself is still shown (falls back to plain textContent, not emptied)");

  // --- The master button (not the settings rows) is what actually gates
  //     everything: turning it off suppresses matches even with scope="any"
  //     and both 'where' toggles back on ---
  rowsCb.checked = true;
  rowsCb.dispatchEvent(new w.Event("change", { bubbles: true }));
  detailCb.checked = true;
  detailCb.dispatchEvent(new w.Event("change", { bubbles: true }));
  fireClick(btn, w);
  msgEl = d.querySelector("#tableRows .log-row .col-msg");
  assert(!/<mark/.test(msgEl.innerHTML), "master button off suppresses row marks regardless of the 'where' toggles");
  w.updateDetailPanel();
  assert(!/<mark/.test(d.querySelector("#detailMessage").innerHTML), "...and detail-panel marks too");
  fireClick(btn, w); // back on for the rest of the group

  // --- Wildcard/value-token text filters are matched too, numeric
  //     conditions and all (findMatchRanges/textFilterMatchSpec directly,
  //     same primitives the row/detail rendering above uses) ---
  const wcNode = w.createFilterNode(f.id, "text", "alpha [*:int>=10]");
  const spec = w.textFilterMatchSpec(wcNode);
  assert(spec && spec.wildcardRegex, "a wildcard/value-token text filter compiles a wildcardRegex match spec");
  const rangesHit = w.findMatchRanges("alpha 15", spec);
  assert(rangesHit.length === 1 && rangesHit[0][0] === 0 && rangesHit[0][1] === "alpha 15".length,
    "wildcard match range covers the full matched span for a value that satisfies the numeric condition");
  const rangesMiss = w.findMatchRanges("alpha 5", spec);
  assert(rangesMiss.length === 0, "wildcard match finds no range when the numeric condition ([*:int>=10]) isn't satisfied");

  // --- initTextMatchHighlightSettings re-applies persisted flags on
  //     (re-)init, same path real boot uses ---
  w.localStorage.setItem("philogg-text-match-highlight-enabled", "0");
  w.localStorage.setItem("philogg-text-match-highlight-scope", "any");
  w.localStorage.setItem("philogg-text-match-highlight-rows", "1");
  w.localStorage.setItem("philogg-text-match-highlight-detail", "1");
  w.initTextMatchHighlightSettings();
  assert(!T.textMatchHighlightEnabled && !btn.classList.contains("active"), "initTextMatchHighlightSettings re-applies the persisted master state to the button");
  assert(T.textMatchHighlightScope === "any" && scopeSelect.value === "any", "...and re-applies the persisted scope");
  assert(rowsCb.checked === true && detailCb.checked === true, "...and re-applies both persisted 'where' toggles");
});

/* ============================================================
   GROUP 94 — Level bar writes into the filter tree (FEATURE_BACKLOG.md #10)
   Origin: this session (2026-08-23), person-requested design: two modes
   picked in Settings -> Behavior (#settingsLevelFilterTreeMode), default
   "auto" — the level bar upserts a single filterType:"level" node (value =
   array of active level names) at the current tree position instead of the
   old tree-independent state.levelFilter Set. "explicit" keeps the original
   Set-based quick-filter (still exercised by Groups 4/13/33/52/61a/b/d/e,
   all pinned to "explicit" mode now that it's no longer the default) plus a
   new #btnApplyLevelToTree ("Add to tree") button, shown only in that mode,
   that pushes the current selection into the tree on demand.
   ============================================================ */
group(94);
await withApp(async (w, d, T) => {
  section("94. Level bar writes into the filter tree");

  // 20 entries, ERROR at every 5th index (makeLog's default level rule) — 4
  // ERROR / 16 INFO, same fixture shape Group 61e already uses.
  const f = await w.addFile("a.log", makeLog(0, 20), () => {});
  T.state.activeId = f.id;
  w.render();

  const select = d.querySelector("#settingsLevelFilterTreeMode");
  const applyBtn = d.querySelector("#btnApplyLevelToTree");
  const findLevelBtn = lvl => [...d.querySelectorAll("#levelBar .level-btn")].find(b => b.textContent.includes(lvl));

  /* ---------- Defaults: "auto" mode, Apply button hidden ---------- */
  assert(T.levelFilterTreeMode === "auto", "level-filter-tree mode defaults to auto");
  assert(select.value === "auto", "settings dropdown reflects the auto default");
  assert(!isVisible(applyBtn, w), "#btnApplyLevelToTree stays hidden in auto mode — the level bar already writes into the tree");

  /* ---------- Auto mode: clicking a level creates a "level" node under the active node ---------- */
  fireClick(findLevelBtn("ERROR"), w);
  assert(f.children.length === 1, "auto mode: clicking ERROR creates exactly one child node under the active file");
  const levelNode = T.state.nodes[f.children[0]];
  assert(levelNode.filterType === "level" && JSON.stringify(levelNode.value) === JSON.stringify(["ERROR"]),
    "the new node is a filterType:\"level\" node with value [\"ERROR\"]");
  assert(T.state.activeId === levelNode.id, "the new level node becomes the active node");
  assert(levelNode.name === "ERROR", "node name is the joined level list");
  const row = d.querySelector('.tree-row[data-node-id="' + levelNode.id + '"]');
  assert(w.typeTagFor(levelNode) === "LVL", "typeTagFor still reports LVL for a level node (the separate .tree-type-tag badge itself is gone — see Group 132, the type shows once, at the icon's own position, per the Settings -> Behavior indicator mode)");
  assert(row.querySelector(".tree-label").textContent === "ERROR", "tree row label shows the level list");
  assert(w.getEntries(levelNode.id).length === 4, "getEntries' new \"level\" dispatch branch filters correctly, got " + w.getEntries(levelNode.id).length);
  assert(T.currentViewEntries.length === 4, "Filtered view narrows to the 4 ERROR entries");

  /* ---------- Clicking a second level while the level node is active updates it IN PLACE (no duplicate node) ---------- */
  fireClick(findLevelBtn("INFO"), w);
  assert(f.children.length === 1 && T.state.activeId === levelNode.id, "still exactly one node — the same node was edited, not duplicated");
  assert(JSON.stringify(T.state.nodes[levelNode.id].value) === JSON.stringify(["ERROR", "INFO"]),
    "second click adds INFO to the same node's value, in canonical LEVELS order");
  assert(w.getEntries(levelNode.id).length === 20, "sanity: ERROR+INFO covers every entry in this fixture");

  /* ---------- Toggling levels back off shrinks the node; the LAST one deletes it (undoably) ---------- */
  fireClick(findLevelBtn("ERROR"), w);
  assert(JSON.stringify(T.state.nodes[levelNode.id].value) === JSON.stringify(["INFO"]), "removing ERROR leaves just INFO on the same node");
  const undoLenBefore = T.undoStack.length;
  fireClick(findLevelBtn("INFO"), w);
  assert(!T.state.nodes[levelNode.id], "removing the last active level deletes the node entirely");
  assert(f.children.length === 0, "the file has no children left");
  assert(T.state.activeId === f.id, "active node reverts to the parent (deleteNode's own behavior)");
  assert(T.undoStack.length === undoLenBefore + 1 && T.undoStack[T.undoStack.length - 1].kind === "delete",
    "the auto-delete goes through deleteFilterNodeWithUndo — a real, undoable action");
  w.undo();
  assert(T.state.nodes[levelNode.id] && JSON.stringify(T.state.nodes[levelNode.id].value) === JSON.stringify(["INFO"]),
    "undo restores the node with its pre-delete value, same id");
  assert(f.children.includes(levelNode.id), "...and re-attached under the file");
  // Clean up for the sections below.
  w.deleteFilterNodeWithUndo(levelNode.id);
  T.state.activeId = f.id;
  w.render();

  /* ---------- Explicit mode: level bar reverts to the classic Set, plus the Apply button ---------- */
  select.value = "explicit";
  select.dispatchEvent(new w.Event("change", { bubbles: true }));
  assert(T.levelFilterTreeMode === "explicit", "settings dropdown switches the mode");
  assert(w.localStorage.getItem("philogg-level-filter-tree-mode") === "explicit", "mode choice persisted");
  assert(isVisible(applyBtn, w), "#btnApplyLevelToTree becomes visible in explicit mode");
  assert(applyBtn.disabled, "...but stays disabled while nothing is selected on the level bar");
  // FEATURE_BACKLOG.md #37 regression guard: #btnApplyLevelToTree must join
  // the SAME float:left pinned-top-left flow as #fhTabs/#levelBar/the other
  // toolbar-icon-btns in #viewBar (see the layout mechanism guard in GROUP
  // "view bar" above). It's toggled via display:none/"" rather than
  // removed/re-added, so an unfloated button here drops below the #levelBar
  // float as a normal-flow block, shoving #breadcrumb's wrap start down
  // with it the moment Manual mode reveals it — exactly the reported
  // "extra button shifts the filter chain" bug.
  assert(w.getComputedStyle(applyBtn).float === "left", "#btnApplyLevelToTree floats left, same pinned-top-left mechanism as #fhTabs/#levelBar, so revealing it doesn't shift #breadcrumb");

  fireClick(findLevelBtn("ERROR"), w);
  assert(T.state.levelFilter.has("ERROR"), "explicit mode: clicking a level toggles the classic state.levelFilter Set");
  assert(f.children.length === 0, "...and does NOT touch the filter tree");
  assert(!applyBtn.disabled, "Apply button enables once a level is selected");

  fireClick(applyBtn, w);
  assert(f.children.length === 1, "Apply button pushes the current selection into the tree as a node");
  const appliedNode = T.state.nodes[f.children[0]];
  assert(appliedNode.filterType === "level" && JSON.stringify(appliedNode.value) === JSON.stringify(["ERROR"]),
    "the applied node carries the current level-bar selection");
  assert(T.state.activeId === appliedNode.id, "the applied node becomes active");

  fireClick(applyBtn, w); // active node IS the level node already — must update in place, not duplicate
  assert(f.children.length === 1, "re-clicking Apply on an already-applied selection updates the existing node instead of creating a second one");

  /* ---------- Switching mode clears the (now stale/invisible) global quick-filter ---------- */
  select.value = "auto";
  select.dispatchEvent(new w.Event("change", { bubbles: true }));
  assert(T.state.levelFilter.size === 0, "switching mode clears state.levelFilter so it can't silently bleed into the other mode");
  assert(!isVisible(applyBtn, w), "Apply button hides again in auto mode");

  /* ---------- Persistence: a "level" node's filterType/value round-trip through the generic value field ---------- */
  // f still has the one level node from the explicit-mode Apply above
  // (mode switches never touch the tree itself, only the level bar's
  // client-side behavior) — serialize it and materialize it under a second,
  // unrelated file, mirroring how the session cache persists/restores a
  // filter tree (see serializeFilterTreeForCache/materializeCachedFilters).
  const g = await w.addFile("b.log", makeLog(0, 5), () => {});
  const { roots } = w.serializeFilterTreeForCache(f);
  assert(roots.length === 1 && roots[0].filterType === "level" && JSON.stringify(roots[0].value) === JSON.stringify(["ERROR"]),
    "serializeFilterTreeForCache carries a level node's filterType/value through the existing generic `value` field — no special-casing needed");
  w.materializeCachedFilters(g, roots);
  assert(g.children.length === 1, "materializeCachedFilters recreates the level node under the new file (FILTER_TYPES includes \"level\", or this would be silently dropped)");
  const restored = T.state.nodes[g.children[0]];
  assert(restored.filterType === "level" && JSON.stringify(restored.value) === JSON.stringify(["ERROR"]),
    "restored level node's filterType/value round-trip correctly");
  assert(w.getEntries(restored.id).length === g.entries.filter(e => e.level === "ERROR").length,
    "restored level node evaluates correctly through getEntries' \"level\" dispatch branch");
});

/* ============================================================
   GROUP 95 — "level" filter node tree-row label colored by log level(s),
   each word its own solid color (no gradient)
   Origin: this session (2026-08-23), person-requested follow-up to Group
   94's level-tree-node feature: "schreibe die Einträge im Files & Filter
   Tree in der Farbe des Log Levels. auch kombiniert wenn mehrere Level an
   sind." First cut used a background-clip:text gradient for a combined
   node; same-day follow-up ("ohne Farbgradient, jedes Wort in der eigenen
   Farbe") replaced that with one <span> per level name, each in that
   level's own solid theme color, comma-separated exactly like the node's
   plain-text name.
   ============================================================ */
group(95);
await withApp(async (w, d, T) => {
  section("95. \"level\" filter node tree-row label: each level word its own solid color");

  const f = await w.addFile("a.log", makeLog(0, 20), () => {});
  T.state.activeId = f.id;
  w.render();

  /* ---------- Single level: one colored word, no gradient/clip styling anywhere ---------- */
  const errorNode = w.createFilterNode(f.id, "level", ["ERROR"]);
  w.render();
  let label = d.querySelector('.tree-row[data-node-id="' + errorNode.id + '"] .tree-label');
  let words = [...label.querySelectorAll("span")];
  assert(words.length === 1 && words[0].textContent === "ERROR" && words[0].style.color === "var(--level-error)",
    "a single-level node's label has one span, colored in that level's own color");
  assert(!label.style.color && !label.style.backgroundImage, "no color/gradient on the label element itself — coloring lives on the per-word span");

  /* ---------- Combined levels: each word its own color, comma-separated, no gradient ---------- */
  const comboNode = w.createFilterNode(f.id, "level", ["ERROR", "INFO"]);
  w.render();
  label = d.querySelector('.tree-row[data-node-id="' + comboNode.id + '"] .tree-label');
  words = [...label.querySelectorAll("span")];
  assert(words.length === 2 && words[0].textContent === "ERROR" && words[0].style.color === "var(--level-error)"
    && words[1].textContent === "INFO" && words[1].style.color === "var(--level-info)",
    "combined levels render as two separately-colored words, ERROR red / INFO blue, no blended gradient between them");
  assert(label.textContent === "ERROR, INFO", "the words plus separator read exactly like the node's plain-text name");
  assert(!label.style.backgroundImage && !label.style.webkitBackgroundClip, "no gradient/background-clip styling used anywhere for the combined case");

  // Word order follows the node's own value array order (canonical LEVELS
  // order in practice, since that's what applyLevelSelectionToTree always
  // writes) — not click/creation order.
  const reorderedNode = w.createFilterNode(f.id, "level", ["WARN", "DEBUG"]);
  w.render();
  label = d.querySelector('.tree-row[data-node-id="' + reorderedNode.id + '"] .tree-label');
  words = [...label.querySelectorAll("span")];
  assert(words[0].textContent === "WARN" && words[0].style.color === "var(--level-warn)"
    && words[1].textContent === "DEBUG" && words[1].style.color === "var(--level-debug)",
    "word/color order follows the node's value array order");

  /* ---------- A non-"level" filter node gets no span/color styling at all ---------- */
  const textNode = w.createFilterNode(f.id, "text", "message 1");
  w.render();
  label = d.querySelector('.tree-row[data-node-id="' + textNode.id + '"] .tree-label');
  assert(label.querySelectorAll("span").length === 0 && label.textContent === "“message 1”",
    "a plain text filter node's label is untouched — plain text, no spans");
});

/* ============================================================
   GROUP 96 — Rename / label filter nodes (FEATURE_BACKLOG.md #12)
   Origin: this session (2026-08-23, person-requested, F2 repurposed as the
   rename shortcut, Edit moved to Ctrl+E — see GROUP 18/32/46's updated F2
   references). A node.label overrides node.name for DISPLAY only (tree row,
   breadcrumb, child-nav flyout, context menu header, link dialog, ...);
   node.name itself is untouched, still what Edit/Save-to-file/library
   default to. Covers the inline F2/Enter/Escape rename UI, the context
   menu's "Rename…" item, undo/redo (reuses withFieldEditUndo, same as the
   invert toggle), the "level" node label-coloring interaction (GROUP 95 —
   a custom label must override the per-word coloring), and every
   persistence carrier CLAUDE.md's "Known gotchas" list calls out
   (cloneSubtree, snapshotSubtree/restoreSubtree,
   serializeFilterBranch/importFilterJson,
   serializeFilterTreeForCache/materializeCachedFilters).
   ============================================================ */
group(96);
await withApp(async (w, d, T) => {
  section("96. Rename / label filter nodes");
  const f = await w.addFile("a.log", makeLog(0, 20), () => {});
  w.render();
  const node = w.createFilterNode(f.id, "text", "message 1");
  T.state.activeId = node.id;
  w.render();
  const rowFor = id => d.querySelector('.tree-row[data-node-id="' + id + '"]');

  /* ---------- nodeDisplayName: falls back to node.name, prefers node.label ---------- */
  assert(w.nodeDisplayName(node) === node.name, "no label yet — nodeDisplayName falls back to node.name");
  assert(rowFor(node.id).querySelector(".tree-label").textContent === node.name, "tree row shows the raw auto-derived name before any rename");

  /* ---------- F2 starts an inline rename: label swaps for a text input ---------- */
  fireKeydown(d, w, "F2");
  let row = rowFor(node.id);
  let input = row.querySelector(".tree-rename-input");
  assert(input, "F2 replaces the row's .tree-label content with a .tree-rename-input");
  assert(input.value === "", "input starts empty — no label set yet");
  assert(input.placeholder === node.name, "input's placeholder shows the raw value as a hint while renaming");
  assert(!d.querySelector("#filterPopup") || d.querySelector("#filterPopup").classList.contains("hidden"),
    "F2 does NOT open the Edit popup anymore (that moved to Ctrl+E, see GROUP 18)");

  /* ---------- Enter commits the rename, undoably ---------- */
  const undoLenBeforeRename = T.undoStack.length;
  input.value = "Step 1: baseline";
  input.dispatchEvent(new w.KeyboardEvent("keydown", { key: "Enter", bubbles: true, cancelable: true }));
  assert(node.label === "Step 1: baseline", "Enter commits the typed value into node.label, got " + JSON.stringify(node.label));
  assert(node.value === "message 1" && node.name === "“message 1”", "the filter's actual value/name are untouched by a rename");
  assert(T.undoStack.length === undoLenBeforeRename + 1 && T.undoStack[T.undoStack.length - 1].kind === "edit",
    "rename pushes a real, undoable \"edit\" action — same mechanism as invert/value-edit");
  row = rowFor(node.id);
  assert(!row.querySelector(".tree-rename-input"), "input is gone after commit — back to a plain label");
  assert(row.querySelector(".tree-label").textContent === "Step 1: baseline", "tree row now shows the custom label instead of the raw value");
  assert(row.querySelector(".tree-label").title.includes("Step 1: baseline") && row.querySelector(".tree-label").title.includes(node.name),
    "row title shows BOTH the label and the raw value in brackets, for discoverability");
  assert(w.nodeDisplayName(node) === "Step 1: baseline", "nodeDisplayName now prefers the label");

  /* ---------- Undo/redo ---------- */
  w.undo();
  assert(!node.label, "undo clears the label back to unset");
  assert(rowFor(node.id).querySelector(".tree-label").textContent === node.name, "tree row reverts to the raw value after undo");
  w.redo();
  assert(node.label === "Step 1: baseline", "redo re-applies the rename");

  /* ---------- Re-opening rename prefills the CURRENT label, not empty ---------- */
  fireKeydown(d, w, "F2");
  input = rowFor(node.id).querySelector(".tree-rename-input");
  assert(input.value === "Step 1: baseline", "input prefills with the node's current label");

  /* ---------- Escape cancels without touching the label or the undo stack ---------- */
  const undoLenBeforeEscape = T.undoStack.length;
  input.value = "abandoned edit";
  input.dispatchEvent(new w.KeyboardEvent("keydown", { key: "Escape", bubbles: true, cancelable: true }));
  assert(!rowFor(node.id).querySelector(".tree-rename-input"), "Escape closes the rename input");
  assert(node.label === "Step 1: baseline", "Escape leaves the label exactly as it was — the typed text is discarded");
  assert(T.undoStack.length === undoLenBeforeEscape, "Escape does not push an undo action");

  /* ---------- Committing an empty value clears the label (reverts to the raw name) ---------- */
  fireKeydown(d, w, "F2");
  input = rowFor(node.id).querySelector(".tree-rename-input");
  input.value = "   "; // whitespace-only — trimmed to empty
  input.dispatchEvent(new w.KeyboardEvent("keydown", { key: "Enter", bubbles: true, cancelable: true }));
  assert(!node.label, "committing a blank/whitespace-only value clears node.label entirely");
  assert(rowFor(node.id).querySelector(".tree-label").textContent === node.name, "tree row shows the raw value again");

  /* ---------- Re-committing the SAME label is a no-op (no undo spam) ---------- */
  w.renameFilterNodeWithUndo(node.id, "repeat me");
  const undoLenAfterFirst = T.undoStack.length;
  w.renameFilterNodeWithUndo(node.id, "repeat me");
  assert(T.undoStack.length === undoLenAfterFirst, "renaming to the label it already has pushes no new undo action");

  /* ---------- Context menu offers "Rename…" (unconditionally, unlike "Edit filter…") ---------- */
  fireContextMenu(rowFor(node.id), w);
  let items = [...d.querySelectorAll("#treeContextMenu [data-action]")];
  assert(items.some(n => n.dataset.action === "rename" && n.textContent.includes("Rename")), "context menu offers \"Rename…\" for a text filter");
  const linkNode = w.createFilterNode(f.id, "after", f.entries[5].ts); // stand-in "not text/extract" type
  linkNode.filterType = "and"; // and/or nodes get no "Edit filter…" item at all — Rename should still be offered
  w.render();
  fireContextMenu(rowFor(linkNode.id), w);
  items = [...d.querySelectorAll("#treeContextMenu [data-action]")];
  assert(items.some(n => n.dataset.action === "rename"), "\"Rename…\" is offered even for a filterType with no \"Edit filter…\" item");
  assert(!items.some(n => n.dataset.action === "edit"), "sanity: this filterType indeed has no \"Edit filter…\" item");
  w.closeTreeContextMenu();
  w.deleteFilterNodeWithUndo(linkNode.id);

  fireContextMenu(rowFor(node.id), w);
  fireClick([...d.querySelectorAll("#treeContextMenu [data-action]")].find(n => n.dataset.action === "rename"), w);
  assert(rowFor(node.id).querySelector(".tree-rename-input"), "context menu's \"Rename…\" action starts the same inline rename as F2");
  rowFor(node.id).querySelector(".tree-rename-input").dispatchEvent(new w.KeyboardEvent("keydown", { key: "Escape", bubbles: true, cancelable: true }));
  w.renameFilterNodeWithUndo(node.id, ""); // clean up back to no label for the sections below
  T.resetUndoRedo();

  /* ---------- Interaction with GROUP 95: a label overrides "level" node per-word coloring ---------- */
  const levelNode = w.createFilterNode(f.id, "level", ["ERROR", "INFO"]);
  w.render();
  let levelLabel = rowFor(levelNode.id).querySelector(".tree-label");
  assert(levelLabel.querySelectorAll("span").length === 2, "sanity: an unlabeled \"level\" node still gets GROUP 95's per-word colored spans");
  w.renameFilterNodeWithUndo(levelNode.id, "Problems");
  w.render();
  levelLabel = rowFor(levelNode.id).querySelector(".tree-label");
  assert(levelLabel.querySelectorAll("span").length === 0 && levelLabel.textContent === "Problems",
    "once labeled, the per-word coloring is gone — plain text label like every other filter type");
  w.renameFilterNodeWithUndo(levelNode.id, "");
  w.render();
  assert(rowFor(levelNode.id).querySelector(".tree-label").querySelectorAll("span").length === 2,
    "clearing the label brings the per-word coloring back");
  w.deleteFilterNodeWithUndo(levelNode.id);

  /* ---------- Persistence carriers (CLAUDE.md "Known gotchas") ---------- */
  w.renameFilterNodeWithUndo(node.id, "Step 1: baseline");

  // cloneSubtree (Ctrl+C/Ctrl+V under the hood)
  const clone = w.cloneSubtree(node.id, f.id);
  assert(clone.label === "Step 1: baseline", "cloneSubtree carries the label over to the copy");

  // snapshotSubtree / restoreSubtree (delete + undo)
  const undoLenBeforeDelete = T.undoStack.length;
  w.deleteFilterNodeWithUndo(node.id);
  assert(T.undoStack.length === undoLenBeforeDelete + 1, "sanity: delete pushed an undo action");
  w.undo();
  assert(T.state.nodes[node.id].label === "Step 1: baseline", "snapshotSubtree/restoreSubtree round-trip the label through a delete+undo");

  // serializeFilterBranch / importFilterJson (Save filter.../Load filter... JSON files)
  const branch = w.serializeFilterBranch(node.id);
  assert(branch.roots[0].label === "Step 1: baseline", "serializeFilterBranch includes the label in the saved JSON shape");
  const h = await w.addFile("c.log", makeLog(0, 5), () => {});
  // loadFilterTargetId is a top-level `let` importFilterJson reads — reach it
  // via the shared lexical scope, same technique GROUP 10/32 use.
  const setLoadTarget = d.createElement("script");
  setLoadTarget.textContent = `loadFilterTargetId = ${JSON.stringify(h.id)};`;
  d.body.appendChild(setLoadTarget);
  const importJson = JSON.stringify({ format: "philogg-filters", version: 2, activeRef: branch.activeRef, roots: branch.roots });
  w.importFilterJson(importJson);
  const importedNode = h.children.map(id => T.state.nodes[id]).find(n => n.label === "Step 1: baseline");
  assert(importedNode, "importFilterJson recreates the node with its label intact");

  // serializeFilterTreeForCache / materializeCachedFilters (session cache)
  const { roots: cacheRoots } = w.serializeFilterTreeForCache(f);
  const cacheNodeOut = cacheRoots.find(r => r.label === "Step 1: baseline");
  assert(cacheNodeOut, "serializeFilterTreeForCache includes the label");
  const k = await w.addFile("d.log", makeLog(0, 5), () => {});
  w.materializeCachedFilters(k, [cacheNodeOut]);
  const materializedNode = T.state.nodes[k.children[0]];
  assert(materializedNode.label === "Step 1: baseline", "materializeCachedFilters restores the label from the session cache");
});

/* ============================================================
   GROUP 97 — Live tail follow on the Highlight/Full view too
   Origin: this session, FEATURE_BACKLOG.md #25 ("Optional tail auto-follow
   for the Highlight view — currently deliberately static while the Filter
   view follows tailed entries") plus a person-requested extension: any
   scroll/jump that lands back near the bottom of a tailed view (not just a
   click on the floating "Newest" button) should re-engage follow the same
   way the button does. state.tailFollow is one shared flag now driving BOTH
   #tableBody (Filtered) and #highlightBody (Highlight/Full) — see
   onTailChange/renderHighlightView's pendingHighlightScroll and the two
   scroll listeners' maybeReengageTailFollow call.
   jsdom has no real layout engine, so scrollHeight isn't naturally non-zero
   the way it would be in a browser — each scenario below stubs it directly
   on the relevant body element (same pattern Group 73 already uses for
   #tableRows.scrollWidth) so "distance from bottom" math has something real
   to compare against.
   ============================================================ */
group(97);
await withApp(async (w, d, T) => {
  section("97a. Tail growth auto-follows the Highlight/Full view too, not just Filtered");

  function fakeHandle(initialText) {
    let text = initialText;
    return {
      _setText(t) { text = t; },
      async getFile() {
        const blob = new w.Blob([text]);
        blob.slice = (start) => {
          const sliced = text.slice(start);
          const b = new w.Blob([sliced]);
          b.text = async () => sliced;
          return b;
        };
        Object.defineProperty(blob, "size", { get: () => text.length, configurable: true });
        return blob;
      },
    };
  }

  const initial = makeLog(0, 3);
  const handle = fakeHandle(initial);
  const f = await w.addFile("live.log", initial, () => {});
  f.tail = { handle, offset: initial.length, pending: "", failed: false, busy: false };
  w.render();
  assert(T.state.tailFollow === true, "follow starts engaged (default state)");

  const tableBody = d.getElementById("tableBody");
  const highlightBody = d.getElementById("highlightBody");
  const tailJumpBtn = d.getElementById("tailJumpBtn");
  const tailJumpBtnHighlight = d.getElementById("tailJumpBtnHighlight");
  Object.defineProperty(tableBody, "scrollHeight", { value: 3000, configurable: true });
  Object.defineProperty(highlightBody, "scrollHeight", { value: 3000, configurable: true });

  const appended = `2024-01-15 10:00:03,000\tINFO\t"main"\tFoo.cs\tline 3\t[DoWork]\t"new entry"\n`;
  handle._setText(initial + appended);
  await w.tailTick();
  assert(T.currentHighlightViewEntries.length === 4, "the Highlight/Full view's own entry list grew from the tail update too");
  assert(tableBody.scrollTop === 3000, "Filtered view still follows tail growth to the bottom (no regression)");
  assert(highlightBody.scrollTop === 3000, "Highlight/Full view NOW also follows tail growth to the bottom");
  assert(isVisible(tailJumpBtn, w) === false && isVisible(tailJumpBtnHighlight, w) === false,
    "both jump buttons stay hidden while follow is engaged");

  section("97b. Scrolling away from the bottom disengages follow — in either view, one shared flag");

  await new Promise(r => setTimeout(r, 200)); // clear the programmatic-scroll grace window
  highlightBody.scrollTop = 0;
  highlightBody.dispatchEvent(new w.Event("scroll", { bubbles: true }));
  assert(T.state.tailFollow === false, "scrolling away from the bottom in the Highlight view disengages follow");
  assert(isVisible(tailJumpBtnHighlight, w) === true, "the Highlight view's own jump button appears");
  assert(isVisible(tailJumpBtn, w) === true,
    "the Filtered view's jump button appears too — tailFollow is one shared flag, not per-view");

  section("97c. Scrolling/jumping back near the bottom re-engages follow — same effect as the jump button");

  highlightBody.scrollTop = 3000; // e.g. a native "jump to last line" shortcut landing at the end
  highlightBody.dispatchEvent(new w.Event("scroll", { bubbles: true }));
  assert(T.state.tailFollow === true, "scrolling/jumping back to the bottom re-engages follow, without needing the button click");
  assert(isVisible(tailJumpBtnHighlight, w) === false, "the jump button hides again once follow re-engages");

  section("97d. Same disengage/re-engage-on-scroll behavior for the pre-existing Filtered view");

  await new Promise(r => setTimeout(r, 200));
  tableBody.scrollTop = 0;
  tableBody.dispatchEvent(new w.Event("scroll", { bubbles: true }));
  assert(T.state.tailFollow === false, "scrolling away from the bottom in the Filtered view disengages follow");
  tableBody.scrollTop = 3000;
  tableBody.dispatchEvent(new w.Event("scroll", { bubbles: true }));
  assert(T.state.tailFollow === true, "scrolling back to the bottom in the Filtered view re-engages follow too");

  section("97e. Clicking a row in the Highlight view disengages follow, same as the Filtered view");

  w.selectHighlightEntry(f.entries[0].id);
  assert(T.state.tailFollow === false, "selecting a row in the Highlight view stops follow from yanking the view away from it");

  section("97f. #tailJumpBtnHighlight re-engages follow and jumps to the newest entry, mirroring #tailJumpBtn");

  highlightBody.scrollTop = 0;
  tailJumpBtnHighlight.dispatchEvent(new w.MouseEvent("click", { bubbles: true, cancelable: true }));
  assert(T.state.tailFollow === true, "clicking the Highlight view's jump button re-engages follow");
  assert(highlightBody.scrollTop === 3000, "...and jumps straight to the newest entry");
  assert(tableBody.scrollTop === 3000, "...and the Filtered view is brought along too (one shared follow state)");
});

await withApp(async (w, d, T) => {
  section("103. Re-clicking the already-active filter in the tree (after a dblclick jumped to Context) still reveals the Filtered view");

  const f = await w.addFile("a.log", makeLog(0, 20), () => {});
  const nodeA = w.createFilterNode(f.id, "text", "message 1");
  T.state.activeId = nodeA.id;
  w.render();

  const rowFor = id => [...d.querySelectorAll(".tree-row")].find(r => r.dataset.nodeId === id);

  assert(T.fhActiveTab === "filter", "sanity: selecting the filter starts out on the Filtered tab");
  w.applyFhView("highlight");
  assert(T.fhActiveTab === "highlight", "sanity: jumped to Full (e.g. via double-click on a Filtered row)");

  // activeId is already nodeA — clicking its own tree row again does NOT
  // change state.activeId, so render()'s activeId-changed check
  // (lastActiveIdForReveal) alone would never fire. Regression for the bug
  // where clicking an already-selected filter left the user stuck on Full.
  fireClick(rowFor(nodeA.id), w);
  assert(T.state.activeId === nodeA.id, "sanity: activeId unchanged — same filter clicked again");
  assert(T.fhActiveTab === "filter", "re-clicking the already-active filter still jumps Full -> Filtered");

  /* ---------- Stacked: re-clicking the same filter does NOT change fhLayout ---------- */
  w.applyFhView("stacked");
  fireClick(rowFor(nodeA.id), w);
  assert(T.fhLayout === "stacked", "Stacked stays unchanged when re-clicking the already-active filter");
});

/* ============================================================
   GROUP 98 — Settings "Behavior" section split into subsections
   (FEATURE_BACKLOG.md #30). Appearance/Log Formats already grouped their
   rows into more than one .settings-card (see GROUP 79); Behavior was the
   one section still a single flat card of 9 unrelated rows. Split into:
   a standalone general row, "Hover-to-expand panels" (4 rows), "Filter
   tree" (1 row), and "Text-match highlighting" (3 rows) — same markup
   pattern (.settings-subsection-title + .settings-card) already used by
   Appearance's "Custom themes" and Log Formats' "Filename rules". Pure
   markup regrouping: no ids changed, so every other group's
   #settingsHoverExpandSidebar/#settingsLevelFilterTreeMode/etc. selectors
   still resolve — this group only asserts the new grouping itself.

   Updated this session (FEATURE_BACKLOG.md #8): a new "Timeline minimap"
   subsection (1 row, #settingsHideMinimapFullRangeInFullView) was inserted
   between "Hover-to-expand panels" and "Filter tree" — same markup pattern,
   pushing every subsequent subsection/card index down by one.
   ============================================================ */
group(98);
await withApp(async (w, d, T) => {
  section("98. Settings Behavior section: subsection split");
  await waitForFormatConfig(T);

  fireClick(d.querySelector("#btnSettings"), w);
  const behaviorSection = d.getElementById("settingsSectionBehavior");
  assert(behaviorSection, "the Behavior section exists");

  const subsectionTitles = [...behaviorSection.querySelectorAll(".settings-subsection-title")].map(el => el.textContent);
  assert(subsectionTitles.length === 5,
    "Behavior now has 5 subsection titles (general row stays un-headed, like Appearance's own first card), got " + JSON.stringify(subsectionTitles));
  assert(subsectionTitles[0].startsWith("Hover-to-expand panels"), "first subsection is the hover-to-expand group, got " + subsectionTitles[0]);
  assert(subsectionTitles[1].startsWith("Context view"), "second subsection is the context-view group, got " + subsectionTitles[1]);
  assert(subsectionTitles[2].startsWith("Timeline minimap"), "third subsection is the timeline-minimap group, got " + subsectionTitles[2]);
  assert(subsectionTitles[3].startsWith("Filter tree"), "fourth subsection is the filter-tree group, got " + subsectionTitles[3]);
  assert(subsectionTitles[4].startsWith("Text-match highlighting"), "fifth subsection is the text-match-highlighting group, got " + subsectionTitles[4]);

  const cards = [...behaviorSection.querySelectorAll(".settings-card")];
  assert(cards.length === 6, "Behavior is split into 6 cards (general + 5 subsections), got " + cards.length);

  const cardOf = id => d.getElementById(id).closest(".settings-card");
  assert(cardOf("settingsQuitOnLastClose") === cards[0], "the quit-on-close row sits alone in the first, un-headed card");
  [ "settingsHoverExpandSidebar", "settingsHoverExpandDetail" ]
    .forEach(id => assert(cardOf(id) === cards[1], "#" + id + " sits in the hover-to-expand card"));
  assert(cardOf("settingsContextInitialExpansion") === cards[2], "the context-view initial-expansion row sits in its own context-view card");
  assert(cardOf("settingsHideMinimapFullRangeInFullView") === cards[3], "the minimap-full-range-toggle row sits in its own timeline-minimap card");
  assert(cardOf("settingsLevelFilterTreeMode") === cards[4], "the level-bar-tree-mode row sits in its own filter-tree card");
  [ "settingsTextMatchHighlightScope", "settingsTextMatchHighlightRows", "settingsTextMatchHighlightDetail" ]
    .forEach(id => assert(cardOf(id) === cards[5], "#" + id + " sits in the text-match-highlighting card"));

  // Every row's control is still reachable/functional after the regrouping
  // (behavior itself is covered by GROUPs 91/92/93/94 — this just confirms
  // the move didn't detach anything from the live DOM/listeners).
  const quitCb = d.getElementById("settingsQuitOnLastClose");
  const before = quitCb.checked;
  fireClick(quitCb, w);
  assert(quitCb.checked === !before, "the relocated quit-on-close switch still toggles");
  fireClick(quitCb, w); // restore
});

/* ============================================================
   GROUP 99 — Ctrl+0/Alt+Arrow tree peek+nav, Alt+Enter extraction, and the
   temporary anchor (FEATURE_BACKLOG.md #18, person-requested; a prior
   in-session design built a centered/keyboard-navigable breadcrumb flyout
   popup for this instead — reverted after trying it live, replaced with
   this simpler "forward Alt+Arrow straight to the existing Files & Filters
   tree" approach; the breadcrumb hover flyout itself is UNCHANGED from
   before this session, see GROUP 92). Alt rather than Ctrl for the arrow
   nav — same-day person-requested follow-up — since Ctrl+Arrow is standard
   OS/app behavior for jumps within a document and should stay free for
   that.

   Two independent peek mechanisms, same-day person-refined so each closes
   the way it should rather than one rule for both:
   - Ctrl+0 keeps its existing "focus the tree" behavior, and ADDITIONALLY
     force-peeks the panel open (setSidebarForcedPeek, sidebarForcedPeek
     flag) if it's collapsed. Stays open until focus genuinely LEAVES the
     panel — picking a filter (Enter while the tree has focus), switching
     Full/Filtered/Stacked view (applyFhView, Ctrl+1/2/3 or a tab click), or
     clicking outside the sidebar — deliberately NOT tied to releasing Ctrl
     itself (Ctrl+0's own keystroke releases Ctrl immediately after).
   - Alt, held down (with or without an arrow), peeks a collapsed panel open
     for exactly as long as it's held (sidebarAltPeek flag, dedicated
     keydown/keyup listeners) — a plain toggle, so a quick tap-and-release
     just glances at the tree without navigating anything. Alt+Arrow ALSO
     forwards straight to moveTreeSelection WITHOUT touching
     state.focusRegion — the Log view stays "focused" for plain arrow keys.
     Alt+Enter's own dialog (see below) can open while Alt is down;
     releasing Alt then defers closing the peek until the dialog itself
     closes (maybeCloseSidebarAltPeek, checked from both Alt's keyup and
     closeFilterPopup).
   - Alt+Enter opens "Filter for this message" for the selected row directly
     (openFilterForEntryColumn, shared with the right-click menu item).
   - The temporary anchor (state.tempAnchor): switching the active filter —
     via a tree row click OR Alt+Arrow tree nav, the only two ways to do
     that now — while the selected row doesn't match the new filter shows it
     at its would-be position instead of losing it, per
     #settingsTempAnchorMode (Off/Persistent/Fade, its fade-duration row
     only shown for Fade).
   ============================================================ */
group(99);
await withApp(async (w, d, T) => {
  section("99. Ctrl+0/Alt+Arrow tree peek+nav, Alt+Enter, temporary anchor");

  // messages: "message 0 keep", "message 1 skip", "message 2 keep", ...
  const f = await w.addFile("app.log", makeLog(0, 5, { suffix: i => (i % 2 === 0 ? "keep" : "skip") }), () => {});
  const keepFilter = w.createFilterNode(f.id, "text", "keep"); // matches entries 0,2,4
  const skipFilter = w.createFilterNode(f.id, "text", "skip"); // matches entries 1,3
  w.render();

  const sidebarEl = d.querySelector("#sidebar");
  const highlightRow = i => d.querySelectorAll("#highlightRows .log-row")[i];

  // --- Ctrl+0: unchanged while expanded, force-peeks once collapsed, and
  //     that peek persists until focus genuinely leaves the panel (picking
  //     a filter, switching view, or clicking outside) — NOT tied to
  //     releasing Ctrl itself ---
  T.state.activeId = keepFilter.id;
  w.render();
  fireKeydown(d, w, "0", { ctrlKey: true });
  assert(T.state.focusRegion === "tree", "Ctrl+0 still moves focus to the tree, exactly as before");
  assert(!sidebarEl.classList.contains("peeking") && T.sidebarForcedPeek === false,
    "...and does nothing extra while the panel is already expanded");

  w.toggleSidebarCollapsed(true);
  fireKeydown(d, w, "0", { ctrlKey: true });
  assert(sidebarEl.classList.contains("peeking") && T.sidebarForcedPeek === true,
    "Ctrl+0 force-peeks the panel open once it's collapsed");
  fireKeyup(d, w, "Control");
  assert(T.sidebarForcedPeek === true && sidebarEl.classList.contains("peeking"),
    "releasing Ctrl right after Ctrl+0 does NOT close the peek — only leaving the panel's focus does");

  fireKeydown(d, w, "1", { ctrlKey: true }); // Ctrl+1 -> Full view, via applyFhView
  assert(T.sidebarForcedPeek === false, "switching to the Full view (Ctrl+1) clears the forced peek");
  assert(!sidebarEl.classList.contains("peeking"), "...and the panel collapses back to its rail");

  w.toggleSidebarCollapsed(true);
  fireKeydown(d, w, "0", { ctrlKey: true });
  fireClick(d.body, w);
  assert(T.sidebarForcedPeek === false, "a click outside the sidebar also clears the forced peek");

  w.toggleSidebarCollapsed(true);
  fireKeydown(d, w, "0", { ctrlKey: true });
  T.state.focusRegion = "tree";
  fireKeydown(d, w, "Enter"); // picking the active filter node while the tree has focus
  assert(T.sidebarForcedPeek === false, "picking a filter (Enter while the tree has focus) also clears the forced peek");

  // --- Alt (held down) peeks a collapsed panel open for as long as it's
  //     held — a plain toggle, independent of navigation — and Alt+Arrow
  //     forwards to tree navigation WITHOUT taking focus away from the
  //     current Log view ---
  T.state.focusRegion = "entries";
  w.toggleSidebarCollapsed(true); // re-collapse
  assert(T.sidebarAltPeek === false, "sanity: no Alt peek yet");

  fireKeydown(d, w, "Alt"); // holding Alt down — a real browser fires this before any Alt+<key> combo
  assert(T.sidebarAltPeek === true && sidebarEl.classList.contains("peeking"),
    "holding Alt alone peeks a collapsed panel open, even without an arrow press");
  fireKeyup(d, w, "Alt");
  assert(T.sidebarAltPeek === false && !sidebarEl.classList.contains("peeking"),
    "releasing Alt closes it back up again, since it was collapsed before the peek");

  fireKeydown(d, w, "Alt");
  fireKeydown(d, w, "ArrowDown", { altKey: true });
  assert(T.sidebarAltPeek === true, "sanity: Alt peek still on during Alt+ArrowDown");
  assert(T.state.focusRegion === "entries",
    "...but Alt+Arrow does NOT switch focus into the tree — it stays wherever it was");
  assert(T.state.activeId === skipFilter.id, "...while still moving the tree selection itself (keepFilter -> skipFilter)");

  fireKeydown(d, w, "ArrowUp", { altKey: true });
  assert(T.state.activeId === keepFilter.id, "Alt+ArrowUp moves it back");
  assert(T.state.focusRegion === "entries", "focus still hasn't moved");

  fireKeyup(d, w, "Alt");
  assert(T.sidebarAltPeek === false && !sidebarEl.classList.contains("peeking"),
    "releasing Alt after navigating with it closes the panel back up");

  // --- Alt+Enter's own dialog can open while Alt is down — releasing Alt
  //     right after typing that chord must not close the panel out from
  //     under the still-open dialog; only actually closing the dialog does ---
  w.applyFhView("highlight");
  T.state.entriesView = "highlight";
  fireClick(highlightRow(0), w);
  fireKeydown(d, w, "Alt");
  fireKeydown(d, w, "Enter", { altKey: true });
  assert(!d.querySelector("#filterPopup").classList.contains("hidden"), "sanity: Alt+Enter opened the dialog");
  assert(T.sidebarAltPeek === true, "sanity: Alt held it peeked open");
  fireKeyup(d, w, "Alt");
  assert(T.sidebarAltPeek === true && sidebarEl.classList.contains("peeking"),
    "releasing Alt while the Alt+Enter dialog is still open does NOT close the panel");
  w.closeFilterPopup();
  d.querySelector("#filterInput").blur();
  assert(T.sidebarAltPeek === false && !sidebarEl.classList.contains("peeking"),
    "...but closing the dialog afterward does, since Alt was already released");

  w.toggleSidebarCollapsed(false); // re-expand for the rest of this group

  // --- Alt+Enter opens "Filter for this message" for the selected row,
  //     in both Full and Filtered view ---
  w.applyFhView("highlight");
  T.state.entriesView = "highlight";
  fireClick(highlightRow(0), w); // "message 0 keep"
  fireKeydown(d, w, "Enter", { altKey: true });
  assert(!d.querySelector("#filterPopup").classList.contains("hidden"), "Alt+Enter opens the filter popup from the Full view");
  assert(d.querySelector("#filterInput").value === "message [*:int] keep", "prefilled with the message column's numeric-wildcard pattern");
  assert(d.querySelector('.column-chip[data-col="message"]').classList.contains("active"), "message column pre-selected (no mouse event to resolve one from)");
  w.closeFilterPopup();
  d.querySelector("#filterInput").blur(); // openFilterPopup() focuses it; left focused would swallow every keydown below as "typing" (inInput guard)

  T.state.activeId = keepFilter.id;
  T.state.entriesView = "filter";
  w.render();
  fireClick(d.querySelectorAll("#tableRows .log-row")[0], w); // "message 0 keep" in the Filtered view
  fireKeydown(d, w, "Enter", { altKey: true });
  assert(!d.querySelector("#filterPopup").classList.contains("hidden"), "Alt+Enter also works from the Filtered view");
  w.closeFilterPopup();
  d.querySelector("#filterInput").blur();

  // Regression: plain Enter (no Alt) in the Filtered view still does its
  // existing job (reveal Highlight view on the row) instead of Alt+Enter's.
  T.state.entriesView = "filter";
  w.render();
  fireClick(d.querySelectorAll("#tableRows .log-row")[0], w);
  fireKeydown(d, w, "Enter");
  assert(T.state.entriesView === "highlight", "plain Enter on a Filtered row still reveals the Highlight view, unaffected by the new Alt+Enter branch");

  // --- Temporary anchor: switching the active filter — via a tree row
  //     click OR Alt+Arrow tree nav — while the selected row doesn't
  //     match the new filter ---
  // The Context view shows the ACTIVE node's own result with everything else
  // collapsed into gaps (see buildContextView), so "message 1 skip" only has a
  // row of its own while a node that admits it is active — stand on the file
  // node, where nothing is filtered out at all, to pick it.
  T.state.activeId = f.id;
  w.render();
  w.applyFhView("highlight");
  T.state.entriesView = "highlight";
  fireClick(highlightRow(1), w); // "message 1 skip" — not a member of keepFilter
  const skip1Id = T.state.selectedId;
  assert(!!skip1Id, "sanity: clicking a Full-view row selects it");

  // Persistent mode explicitly, so this part of the group tests the anchor
  // mechanic itself rather than the (now Fade-by-default) mode's own timeout.
  const modeSelectEarly = d.querySelector("#settingsTempAnchorMode");
  modeSelectEarly.value = "persistent";
  modeSelectEarly.dispatchEvent(new w.Event("change", { bubbles: true }));

  T.state.activeId = skipFilter.id; // start somewhere that DOES match
  w.render();
  fireClick(d.querySelector('.tree-row[data-node-id="' + keepFilter.id + '"]'), w);
  assert(T.state.activeId === keepFilter.id, "clicking the tree row switches the active node as usual");
  assert(T.state.tempAnchor && T.state.tempAnchor.entryId === skip1Id && T.state.tempAnchor.nodeId === keepFilter.id,
    "...and anchors the still-selected row at its would-be position, since 'keep' doesn't match it");

  let anchorRow = d.querySelector("#tableRows .log-row.temp-anchor-row");
  assert(anchorRow && anchorRow.dataset.entryId === skip1Id, "Persistent mode draws the temp anchor row in the Filtered table");
  const rows = [...d.querySelectorAll("#tableRows .log-row")].map(r => r.dataset.entryId);
  assert(rows.indexOf(anchorRow.dataset.entryId) === 1,
    "the anchor sits between 'keep 0' and 'keep 2' chronologically (would-be position), got index " + rows.indexOf(anchorRow.dataset.entryId));

  fireClick(d.querySelector('.tree-row[data-node-id="' + skipFilter.id + '"]'), w);
  assert(T.state.tempAnchor === null, "clicking into a filter that DOES match the selected row clears the anchor");

  // Same mechanic via Alt+Arrow tree navigation, not just a mouse click.
  T.state.activeId = skipFilter.id;
  T.state.selectedId = skip1Id;
  T.state.tempAnchor = null;
  w.render();
  fireKeydown(d, w, "ArrowUp", { altKey: true }); // skipFilter -> keepFilter (flattened tree order)
  assert(T.state.activeId === keepFilter.id, "sanity: Alt+ArrowUp moved onto keepFilter");
  assert(T.state.tempAnchor && T.state.tempAnchor.entryId === skip1Id && T.state.tempAnchor.nodeId === keepFilter.id,
    "Alt+Arrow tree navigation applies the SAME anchor mechanic as a tree row click");

  // --- Fade-duration row visibility: only shown for the Fade mode ---
  const modeSelect = modeSelectEarly;
  assert(d.querySelector("#settingsTempAnchorFadeRow").style.display === "none",
    "the fade-duration row is hidden while mode is Persistent");

  // --- Off mode: never drawn, but Up/Down still respect its position ---
  modeSelect.value = "off";
  modeSelect.dispatchEvent(new w.Event("change", { bubbles: true }));
  assert(T.tempAnchorMode === "off", "mode setting persisted");
  assert(d.querySelector("#settingsTempAnchorFadeRow").style.display === "none", "...and the fade-duration row stays hidden for Off too");

  T.state.activeId = skipFilter.id;
  T.state.selectedId = skip1Id;
  T.state.tempAnchor = null;
  w.render();
  fireClick(d.querySelector('.tree-row[data-node-id="' + keepFilter.id + '"]'), w);
  assert(d.querySelector("#tableRows .log-row.temp-anchor-row") === null, "Off mode never draws the anchor row");
  assert(T.state.tempAnchor && T.state.tempAnchor.entryId === skip1Id, "...but the anchor position is still remembered");

  // A tree click leaves focusRegion as "entries" (Group 108b below), so
  // plain row Up/Down already works here without any extra step.
  fireKeydown(d, w, "ArrowDown"); // plain, no ctrl — ordinary row nav
  const keep2Id = d.querySelectorAll("#tableRows .log-row")[1].dataset.entryId;
  assert(T.state.selectedId === keep2Id, "Down from an off-mode (undrawn) anchor moves to the next REAL row after its position");

  T.state.tempAnchor = { entryId: skip1Id, nodeId: keepFilter.id, faded: false };
  T.state.selectedId = skip1Id;
  w.render();
  fireKeydown(d, w, "ArrowUp");
  const keep0Id = d.querySelectorAll("#tableRows .log-row")[0].dataset.entryId;
  assert(T.state.selectedId === keep0Id, "Up from the same anchor moves to the real row BEFORE its position");

  // --- Fade mode: shown right after the switch, then removed once the
  //     configured duration elapses — no jarring full re-render/scroll jump ---
  w.applyTempAnchorFadeSeconds(0.5); // the stepper's own minimum
  assert(d.querySelector("#tempAnchorFadeValue").textContent === "0.5s", "the fade-duration stepper shows the value without a % suffix, unlike Font Size");
  modeSelect.value = "fade";
  modeSelect.dispatchEvent(new w.Event("change", { bubbles: true }));
  assert(d.querySelector("#settingsTempAnchorFadeRow").style.display !== "none", "the fade-duration row is shown once mode is Fade");

  T.state.activeId = skipFilter.id;
  T.state.selectedId = skip1Id;
  T.state.tempAnchor = null;
  w.render();
  fireClick(d.querySelector('.tree-row[data-node-id="' + keepFilter.id + '"]'), w);
  assert(!!d.querySelector("#tableRows .log-row.temp-anchor-row"), "Fade mode draws the anchor row right after the switch");
  const fadeTableBody = d.querySelector("#tableBody");
  fadeTableBody.scrollTop = 5; // arbitrary non-zero value
  const entriesLengthBeforeFade = T.currentViewEntries.length;
  await waitFor(() => d.querySelector("#tableRows .log-row.temp-anchor-row") === null);
  assert(d.querySelector("#tableRows .log-row.temp-anchor-row") === null, "...and removes it once the fade duration elapses");
  assert(T.state.tempAnchor && T.state.tempAnchor.faded === true, "the position stays remembered (faded flag) after the fade completes");
  assert(T.currentViewEntries.length === entriesLengthBeforeFade - 1,
    "the faded anchor is dropped from the in-memory list too, kept in sync with the DOM removal");
  assert(fadeTableBody.scrollTop === 5,
    "the fade completing does NOT trigger a full re-render/scroll-anchor recompute that could jump the view — only that one row's own height collapses");
});

/* ============================================================
   GROUP 100 — Middle-click a filter node to delete it
   Origin: this session (2026-08-25), FEATURE_BACKLOG #17: middle-click a
   tree row or a breadcrumb chip deletes that node the same way its ✕
   button / context-menu "Remove" would, undoably (deleteFilterNodeWithUndo).
   ============================================================ */
group(100);
await withApp(async (w, d, T) => {
  section("100. Middle-click a filter node (tree row / breadcrumb chip) deletes it");

  const f = await w.addFile("app.log", makeLog(0, 5), () => {});
  const filt = w.createFilterNode(f.id, "text", "message");
  T.state.activeId = filt.id;
  w.render();

  const undoLenBefore = T.undoStack.length;
  const row = d.querySelector('.tree-row[data-node-id="' + filt.id + '"]');
  row.dispatchEvent(new w.MouseEvent("auxclick", { bubbles: true, cancelable: true, button: 1 }));
  assert(!T.state.nodes[filt.id], "middle-clicking a tree row deletes that filter node");
  assert(f.children.length === 0, "...removed from its parent's children");
  assert(T.undoStack.length === undoLenBefore + 1 && T.undoStack[T.undoStack.length - 1].kind === "delete",
    "the middle-click delete goes through deleteFilterNodeWithUndo — a real, undoable action");
  w.undo();
  assert(T.state.nodes[filt.id], "undo restores the middle-click-deleted node");
  w.render();

  // A non-primary/non-middle button (right-click, handled separately by the
  // context menu) must NOT also trigger this delete path via auxclick.
  const rowAgain = d.querySelector('.tree-row[data-node-id="' + filt.id + '"]');
  rowAgain.dispatchEvent(new w.MouseEvent("auxclick", { bubbles: true, cancelable: true, button: 2 }));
  assert(!!T.state.nodes[filt.id], "auxclick with a non-middle button does not delete the node");

  // Breadcrumb chip: same behavior, reachable from the chain display too.
  T.state.activeId = filt.id;
  w.render();
  const crumb = [...d.querySelectorAll("#breadcrumb .crumb")].find(c => c.classList.contains("current"));
  crumb.dispatchEvent(new w.MouseEvent("auxclick", { bubbles: true, cancelable: true, button: 1 }));
  assert(!T.state.nodes[filt.id], "middle-clicking the active breadcrumb chip deletes that filter node too");
  assert(f.children.length === 0, "...removed from its parent's children");
});

/* ============================================================
   GROUP 101 — Bugfix: "Newest" jump button gated on liveness, not just
   handle existence (FEATURE_BACKLOG #9)
   Origin: this session (2026-08-25), person-reported correction to this
   same session's own earlier (wrong) fix: `activeTailedRoot()` used to
   treat ANY file with a `node.tail` object (i.e. opened via a real
   FileSystemFileHandle — showOpenFilePicker/drag-drop both hand one over,
   the common case) as "trailing" forever, even long after it stopped
   growing — node.tail is never deleted once set. That made #9's "hide for
   static files" a no-op for practically every real file. Fixed by routing
   activeTailedRoot() through the same isTailLive()/TAIL_LIVE_MS staleness
   window Group 63a already established for the tree row's live dot, and
   having tailTick()'s own liveness-only pass (no bytes read, just time
   passing) call updateTailJumpBtn() too, not just renderTree() — otherwise
   the button would only catch up to a staleness flip on some unrelated
   next render.
   ============================================================ */
group(101);
await withApp(async (w, d, T) => {
  section("101. \"Newest\" jump buttons hide once a tailed file goes stale, and stay hidden for a handle that never grew");

  function fakeHandle(initialText) {
    let text = initialText;
    return {
      _setText(t) { text = t; },
      async getFile() {
        const blob = new w.Blob([text]);
        blob.slice = (start) => {
          const sliced = text.slice(start);
          const b = new w.Blob([sliced]);
          b.text = async () => sliced;
          return b;
        };
        Object.defineProperty(blob, "size", { get: () => text.length, configurable: true });
        return blob;
      },
    };
  }

  const initial = makeLog(0, 3);
  const handle = fakeHandle(initial);
  const f = await w.addFile("live.log", initial, () => {});
  f.tail = { handle, offset: initial.length, pending: "", failed: false, busy: false, errorCount: 0, lastGrowth: Date.now() };
  T.state.tailFollow = false; // disengaged, the precondition for either jump button to be visible at all
  w.render();

  const tailJumpBtn = d.getElementById("tailJumpBtn");
  const tailJumpBtnHighlight = d.getElementById("tailJumpBtnHighlight");
  assert(isVisible(tailJumpBtn, w) === true, "sanity: a freshly-grown, unfollowed tailed file shows the jump button");

  // Backdate lastGrowth past the staleness window, same technique Group 63a
  // uses — no real timers needed.
  f.tail.lastGrowth = Date.now() - 60000;
  assert(w.isTailLive(f.tail) === false, "sanity: isTailLive itself reports stale");
  await w.tailTick(); // no byte growth this tick — only time passed
  assert(isVisible(tailJumpBtn, w) === false, "the Filtered view's jump button hides once the file has gone stale, with no other render triggering it");
  assert(isVisible(tailJumpBtnHighlight, w) === false, "same for the Highlight/Full view's own button");

  // A genuinely new write resurrects liveness, and with it the button
  // (still unfollowed).
  const appended = `2024-01-15 10:00:03,000\tINFO\t"main"\tFoo.cs\tline 3\t[DoWork]\t"back again"\n`;
  handle._setText(initial + appended);
  await w.tailTick();
  assert(isVisible(tailJumpBtn, w) === true, "a real write makes the file live again, and the button reappears");

  // A handle-bearing file that has NEVER grown since being opened (no
  // lastGrowth stamped yet) still counts as live — isTailLive treats a null
  // lastGrowth as "just opened, presumed live", matching the tree dot's own
  // existing behavior — so the button is available from the start, not
  // just after a first observed write.
  const g = await w.addFile("fresh.log", makeLog(0, 2), () => {});
  g.tail = { handle: fakeHandle(makeLog(0, 2)), offset: 0, pending: "", failed: false, busy: false, errorCount: 0 };
  T.state.activeId = g.id;
  T.state.tailFollow = false;
  w.render();
  assert(isVisible(d.getElementById("tailJumpBtn"), w) === true, "a just-opened tailed file (no lastGrowth yet) still counts as live, not static");

  // A plain static file (no node.tail at all — e.g. the legacy <input
  // type=file> fallback path) never shows either button, follow or not.
  const h = await w.addFile("static.log", makeLog(0, 2), () => {});
  T.state.activeId = h.id;
  w.render();
  assert(isVisible(d.getElementById("tailJumpBtn"), w) === false, "a file with no node.tail at all never shows the jump button");
});

/* ============================================================
   GROUP 102 — Bugfix: #btnApplyLevelToTree shifts the filter chain
   (FEATURE_BACKLOG.md #37)
   Origin: this session (2026-08-25), bug report with screenshots: switching
   Settings -> Behavior's level-filter-tree mode to "explicit" (Manual)
   reveals #btnApplyLevelToTree ("Add to tree") in #viewBar, and the active
   filter chain (#breadcrumb) visibly shifts/wraps differently than in
   "auto" mode where the button stays hidden. Root cause: every other
   button pinned to #viewBar's top-left float line (#fhTabs,
   #btnPinBookmarks, #btnMultilineMsg, #btnColumns,
   #btnTextMatchHighlight, #levelBar — see the "Unified view bar" CSS
   comment) carries float:left plus the shared 14px/0px margin, but
   #btnApplyLevelToTree never got that rule. Toggled via display:none/""
   rather than added/removed from the DOM, so once visible it sat as an
   unfloated normal-flow block sibling of the #levelBar float and dropped
   below it, pushing #breadcrumb's line-wrap start down too. Fix: give
   #btnApplyLevelToTree the same float:left + margin as its siblings, so it
   just extends the SAME dynamic top-left line no matter how many buttons
   end up on it — scales to future buttons in that row without further
   layout work.
   ============================================================ */
group(102);
await withApp(async (w, d, T) => {
  section("102. #btnApplyLevelToTree joins the pinned top-left float flow");

  const f = await w.addFile("a.log", makeLog(0, 10), () => {});
  T.state.activeId = f.id;
  w.render();

  const select = d.querySelector("#settingsLevelFilterTreeMode");
  select.value = "explicit";
  select.dispatchEvent(new w.Event("change", { bubbles: true }));
  const applyBtn = d.querySelector("#btnApplyLevelToTree");
  assert(isVisible(applyBtn, w), "sanity: explicit mode reveals #btnApplyLevelToTree");

  const cs = w.getComputedStyle;
  assert(cs(applyBtn).float === "left", "#btnApplyLevelToTree floats left, joining #fhTabs/#levelBar's pinned top-left line");
  assert(cs(applyBtn).marginRight === "14px" && cs(applyBtn).marginBottom === "0px",
    "...with the SAME 14px/0px margin as its sibling toolbar-icon-btns, so it doesn't sit any differently on the line");
});

/* ============================================================
   GROUP 104 — Notes: general-purpose per-entry notes (FEATURE_BACKLOG.md
   "Bookmarks rework", this session). Covers: Alt+N add/edit; the log-row
   context menu's "Add note"/"Edit note"; double-click an existing note-row
   to edit; a note renders as its own sub-row below its entry (own class,
   no level marker) and in the Entry Detail panel; the Show/Hide Notes
   toggle; state.notes persists through buildCacheMeta (same ordinal-anchor
   scheme as bookmarks, but a fully separate array/store).
   ============================================================ */
group(104);
await withApp(async (w, d, T) => {
  section("104. Notes: add/edit via Alt+N and context menu, rendering, toggle, persistence");
  const f = await w.addFile("a.log", makeLog(0, 5), () => {});
  T.state.activeId = f.id;
  w.render();

  // Alt+N on a selected entry with no note yet -> opens empty, Add-mode dialog
  w.selectEntry(f.entries[1].id);
  fireKeydown(d, w, "n", { altKey: true });
  assert(!d.querySelector("#noteDialog").classList.contains("hidden"), "Alt+N opens the note dialog");
  assert(d.querySelector("#noteDialogTitle").textContent === "Add note", "empty note -> dialog titled 'Add note'");
  assert(d.querySelector("#noteDialogInput").value === "", "dialog starts empty for a new note");
  d.querySelector("#noteDialogInput").value = "line one\nline two";
  fireClick(d.querySelector("#noteDialogSave"), w);
  assert(d.querySelector("#noteDialog").classList.contains("hidden"), "Save closes the dialog");
  assert(T.state.notes.get(f.entries[1].id) === "line one\nline two", "note text saved to state.notes, newlines preserved");

  // Alt+N again on the SAME entry -> now prefilled, Edit-mode dialog (no separate F2 binding)
  fireKeydown(d, w, "n", { altKey: true });
  assert(d.querySelector("#noteDialogTitle").textContent === "Edit note", "existing note -> dialog titled 'Edit note'");
  assert(d.querySelector("#noteDialogInput").value === "line one\nline two", "dialog prefilled with the existing note text");
  fireClick(d.querySelector("#noteDialogCancel"), w);
  assert(T.state.notes.get(f.entries[1].id) === "line one\nline two", "Cancel leaves the note untouched");

  // Context menu: "Add note"/"Edit note" label swap, same pattern as the bookmark item
  w.openContextMenu({ clientX: 10, clientY: 10 }, f.entries[2]);
  assert(d.querySelector("#ctxNoteLabel").textContent === "Add note", "context menu offers 'Add note' for an entry with none");
  fireClick(d.querySelector("#ctxNote"), w);
  d.querySelector("#noteDialogInput").value = "via context menu";
  fireClick(d.querySelector("#noteDialogSave"), w);
  assert(T.state.notes.get(f.entries[2].id) === "via context menu", "context-menu 'Add note' opens the same editor and saves");
  w.openContextMenu({ clientX: 10, clientY: 10 }, f.entries[2]);
  assert(d.querySelector("#ctxNoteLabel").textContent === "Edit note", "context menu now offers 'Edit note' for the same entry");
  w.closeContextMenu();

  // Deleting a note via the dialog's Delete button
  w.openNoteEditor(f.entries[2].id);
  assert(!d.querySelector("#noteDialogDelete").style.display.includes("none"), "Delete button shown when editing an existing note");
  fireClick(d.querySelector("#noteDialogDelete"), w);
  assert(!T.state.notes.has(f.entries[2].id), "Delete button removes the note");

  // Rendering: a note-row appears below its entry's row when Show Notes is on (default off)
  assert(T.state.showNotes === false, "sanity: notes hidden by default");
  const btnNotes = d.querySelector(".toggle-notes");
  assert(!btnNotes.classList.contains("active"), "Show/Hide Notes button starts inactive");
  fireClick(btnNotes, w);
  assert(T.state.showNotes === true, "clicking #btnNotes turns notes on");
  assert(btnNotes.classList.contains("active"), "#btnNotes reflects the active state");
  let noteRow = [...d.querySelectorAll("#tableRows .note-row")].find(r => r.dataset.entryId === f.entries[1].id);
  assert(noteRow && noteRow.textContent === "line one\nline two", "note-row renders below its entry with the full note text");
  assert(!noteRow.className.includes("row-grid") && !noteRow.querySelector(".col-bar"), "note-row is a plain block, not part of .row-grid, no level marker");

  // Toggling Show/Hide Notes off hides the note-rows again
  fireClick(btnNotes, w);
  assert(T.state.showNotes === false, "clicking #btnNotes again turns notes off");
  assert(d.querySelectorAll("#tableRows .note-row").length === 0, "no note-rows rendered while Show Notes is off");
  fireClick(btnNotes, w); // back on for the rest of this group

  // Double-click an existing note-row opens it for editing
  noteRow = [...d.querySelectorAll("#tableRows .note-row")].find(r => r.dataset.entryId === f.entries[1].id);
  noteRow.dispatchEvent(new w.MouseEvent("dblclick", { bubbles: true, cancelable: true }));
  assert(!d.querySelector("#noteDialog").classList.contains("hidden"), "double-clicking a note-row opens the note editor");
  assert(d.querySelector("#noteDialogInput").value === "line one\nline two", "...prefilled with that row's note");
  w.closeNoteDialog();

  // Entry Detail panel shows the full note text for the selected entry
  w.selectEntry(f.entries[1].id);
  assert(d.querySelector("#detailNote").style.display !== "none" && d.querySelector("#detailNote").textContent === "line one\nline two",
    "Entry Detail panel shows the selected entry's full note");
  w.selectEntry(f.entries[0].id);
  assert(d.querySelector("#detailNote").style.display === "none", "Entry Detail panel hides the note block for an entry with none");

  // Persistence: buildCacheMeta stores notes as { file, ordinal, text }, separately from bookmarks
  const meta = w.buildCacheMeta();
  assert(Array.isArray(meta.notes) && meta.notes.length === 1 && meta.notes[0].ordinal === 1 && meta.notes[0].text === "line one\nline two",
    "buildCacheMeta persists state.notes as ordinal-anchored records, independent of state.bookmarks");
  assert(meta.settings.showNotes === true, "buildCacheMeta persists the Show/Hide Notes toggle");
});

/* ============================================================
   GROUP 105 — Bugfix: Note dialog keyboard shortcuts. Person-requested
   binding (see PROJECT.md): Enter alone saves+closes, Shift+Enter inserts a
   newline (left to native textarea behavior), Delete with an empty textarea
   deletes the note, Escape cancels without saving.
   ============================================================ */
group(105);
await withApp(async (w, d, T) => {
  section("105. Note dialog: Enter saves, Shift+Enter newlines, Delete-when-empty deletes, Escape cancels");
  const f = await w.addFile("a.log", makeLog(0, 5), () => {});
  T.state.activeId = f.id;
  w.render();

  // Enter alone saves and closes
  w.openNoteEditor(f.entries[0].id);
  const input = d.querySelector("#noteDialogInput");
  input.value = "typed note";
  fireKeydown(input, w, "Enter");
  assert(d.querySelector("#noteDialog").classList.contains("hidden"), "Enter alone closes the dialog");
  assert(T.state.notes.get(f.entries[0].id) === "typed note", "Enter alone saves the note text");

  // Shift+Enter does NOT save/close — it's left to native textarea behavior (newline insertion)
  w.openNoteEditor(f.entries[1].id);
  const input2 = d.querySelector("#noteDialogInput");
  input2.value = "line one";
  fireKeydown(input2, w, "Enter", { shiftKey: true });
  assert(!d.querySelector("#noteDialog").classList.contains("hidden"), "Shift+Enter leaves the dialog open");
  assert(!T.state.notes.has(f.entries[1].id), "Shift+Enter does not save the note");
  w.closeNoteDialog();

  // Delete with an empty textarea deletes the note and closes
  w.openNoteEditor(f.entries[0].id); // already has "typed note" from above
  const input3 = d.querySelector("#noteDialogInput");
  assert(input3.value === "typed note", "sanity: editing the note saved earlier");
  input3.value = "";
  fireKeydown(input3, w, "Delete");
  assert(d.querySelector("#noteDialog").classList.contains("hidden"), "Delete on an empty textarea closes the dialog");
  assert(!T.state.notes.has(f.entries[0].id), "Delete on an empty textarea deletes the note");

  // Delete with non-empty textarea content is NOT intercepted (normal in-field character deletion)
  w.openNoteEditor(f.entries[2].id);
  const input4 = d.querySelector("#noteDialogInput");
  input4.value = "some text";
  fireKeydown(input4, w, "Delete");
  assert(!d.querySelector("#noteDialog").classList.contains("hidden"), "Delete with non-empty textarea does not close the dialog");
  assert(!T.state.notes.has(f.entries[2].id), "Delete with non-empty textarea does not delete the note");
  w.closeNoteDialog();

  // Escape cancels without saving
  w.openNoteEditor(f.entries[3].id);
  const input5 = d.querySelector("#noteDialogInput");
  input5.value = "should not be saved";
  fireKeydown(input5, w, "Escape");
  assert(d.querySelector("#noteDialog").classList.contains("hidden"), "Escape closes the dialog");
  assert(!T.state.notes.has(f.entries[3].id), "Escape does not save the note");
});

/* ============================================================
   GROUP 106 — Person-reported follow-ups to the Bookmarks rework (this
   session): (A) a new purely-visual, full-height bookmark-icon column on
   the left of the row (col-bookmark-icon), restoring visual recognition of
   a bookmarked entry that the removed .row-bookmark-dot used to provide
   (person-reported regression: without it, a bookmarked row was
   indistinguishable from any other unless the Bookmarks node itself had a
   color); (B) the color-mark gutter (.hl-markers) now sizes itself
   (--color-mark-w CSS var) to the TRUE max number of simultaneous
   colored-filter matches any one row reaches across the whole file, cached
   as maxSimultaneousColorCount and recomputed alongside highlightColorMap
   rather than per row; (C) toggleBookmark/syncBookmarksFilterNode now
   recompute highlightColorMap (and the gutter width) themselves, so a
   bookmark add/remove updates the Bookmarks node's own color-mark
   immediately, with no view switch needed; (D) a note-row belonging to a
   temp-anchor row that fades out (scheduleTempAnchorFade) is now removed in
   the same step as the fading row itself, instead of being left orphaned.
   ============================================================ */
group(106);
await withApp(async (w, d, T) => {
  section("106a. New bookmark-icon column (left gutter, full height, accent-colored, both row renderers)");
  const f = await w.addFile("a.log", makeLog(0, 5), () => {});
  T.state.activeId = f.id;
  w.render();

  const e0 = f.entries[0], e1 = f.entries[1];
  const iconInFiltered = () => d.querySelector('#tableRows [data-entry-id="' + e0.id + '"] .col-bookmark-icon');
  const iconInFull = () => d.querySelector('#highlightRows [data-entry-id="' + e0.id + '"] .col-bookmark-icon');

  assert(!iconInFiltered() && !iconInFull(), "no bookmark icon rendered for a non-bookmarked entry, in either view");

  w.toggleBookmark(e0.id);
  assert(!!iconInFiltered(), "bookmark icon appears in the Filtered/Full-shared row renderer (renderVisibleRows) exactly when state.bookmarks.has(id)");
  assert(!!iconInFull(), "...and in the Full view's own renderer (renderHighlightVisibleRows) too");
  assert(iconInFiltered().querySelector("svg"), "the icon column actually renders an icon glyph, not just an empty marker span");
  assert(!d.querySelector('#tableRows [data-entry-id="' + e1.id + '"] .col-bookmark-icon'),
    "an entry that isn't bookmarked still gets no icon, even with a bookmark elsewhere in the file");

  w.toggleBookmark(e0.id); // revert
  assert(!iconInFiltered() && !iconInFull(), "unbookmarking removes the icon from both views immediately");

  // Uses the theme's accent/highlight token, not a hardcoded color — verified
  // against the stylesheet text itself (jsdom has no real CSS cascade/paint
  // engine to resolve var() through getComputedStyle reliably, same blind
  // spot documented in tests/README.md's "Known gaps").
  assert(/\.col-bookmark-icon\{[^}]*color:var\(--accent\)/.test(html),
    "the bookmark icon column is styled with color:var(--accent) — the same token used elsewhere for selection/highlight accents — not a hardcoded color");
});

await withApp(async (w, d, T) => {
  section("106b. Color-mark column: dynamic width for the true max simultaneous-color count");
  const f = await w.addFile("a.log", makeLog(0, 20), () => {});
  T.state.activeId = f.id;
  w.render();

  const gutterW = () => parseInt(d.documentElement.style.getPropertyValue("--color-mark-w"), 10);
  assert(gutterW() === 3, "baseline: no colored filters at all -> gutter width is the single-mark default (3px)");

  // "message" matches all 20 entries; "message 1" matches 11 of them
  // (message1, message10-19) — every one of those 11 rows now has TWO
  // simultaneous color marks, the rest still have one.
  const wide = w.createFilterNode(f.id, "text", "message");
  w.setHighlightColor(wide.id, "#ff0000");
  assert(gutterW() === 3, "coloring a filter that matches every row alone (max simultaneous count 1) keeps the single-mark width");

  const narrow = w.createFilterNode(f.id, "text", "message 1");
  w.setHighlightColor(narrow.id, "#00ff00");
  assert(gutterW() === 7, "two overlapping colored filters -> max simultaneous count 2 -> gutter widens to fit both marks (2*3 + 1 gap = 7px)");
  assert(T.highlightColorMap.get(f.entries[1].id).length === 2, "sanity: entry actually carries both colors in highlightColorMap");

  // A third, narrower filter overlapping the same subset raises the true max further
  const narrowest = w.createFilterNode(f.id, "text", "message 10");
  w.setHighlightColor(narrowest.id, "#0000ff");
  assert(gutterW() === 11, "a third overlapping colored filter raises the cached max to 3 -> gutter widens again (3*3 + 2 gaps = 11px) — rescales live as filters are colored, not just once at load");

  // Removing the color that created the highest overlap shrinks the gutter back down
  w.setHighlightColor(narrowest.id, null);
  w.setHighlightColor(narrow.id, null);
  assert(gutterW() === 3, "uncoloring back down to a single colored filter shrinks the gutter back to the single-mark default");
});

await withApp(async (w, d, T) => {
  section("106c. Bugfix: bookmark add/remove updates the Bookmarks node's own color-mark immediately, no view switch needed");
  const f = await w.addFile("a.log", makeLog(0, 5), () => {});
  T.state.activeId = f.id;
  w.render();

  const e0 = f.entries[0];
  w.toggleBookmark(e0.id); // creates the auto-managed "Bookmarks" node (syncBookmarksFilterNode)
  const bmNode = Object.values(T.state.nodes).find(n => n.filterType === "bookmarks");
  assert(bmNode, "sanity: bookmarking creates the auto-managed Bookmarks filter node");
  w.setHighlightColor(bmNode.id, "#abcdef"); // full render() here, as any color-picker action does

  const markerColor = () => {
    const el = d.querySelector('#tableRows [data-entry-id="' + e0.id + '"] .hl-marker');
    return el && el.style.background;
  };
  assert(markerColor() === "rgb(171, 205, 239)" || markerColor() === "#abcdef", "sanity: e0's row shows the Bookmarks node's color-mark once colored");

  const e1 = f.entries[1];
  // BUGFIX: toggling a SECOND bookmark must update e1's color-mark and the
  // gutter's max-count immediately — no w.render()/view-switch in between,
  // reproducing the reported bug exactly (previously highlightColorMap only
  // got recomputed inside the full render pipeline).
  w.toggleBookmark(e1.id);
  assert(!!d.querySelector('#tableRows [data-entry-id="' + e1.id + '"] .hl-marker'),
    "BUGFIX: newly bookmarking e1 shows the Bookmarks node's color-mark on its row immediately, with no separate render() call");
  assert(T.highlightColorMap.get(e1.id) && T.highlightColorMap.get(e1.id).includes("#abcdef"),
    "highlightColorMap itself is recomputed by toggleBookmark, not just the DOM");

  w.toggleBookmark(e1.id); // revert
  assert(!d.querySelector('#tableRows [data-entry-id="' + e1.id + '"] .hl-marker'),
    "...and unbookmarking removes it again immediately, same path");
});

await withApp(async (w, d, T) => {
  section("106d. Bugfix: a note under a fading temp-anchor row is removed when the fade completes, not orphaned");
  const f = await w.addFile("a.log", makeLog(0, 5), () => {});
  const keepFilter = w.createFilterNode(f.id, "text", "message");   // matches everything
  const narrowFilter = w.createFilterNode(f.id, "text", "message 2"); // matches only entry 2
  T.state.activeId = keepFilter.id;
  const skip1Id = f.entries[1].id; // NOT matched by narrowFilter -> becomes the temp anchor when switching to it
  T.state.selectedId = skip1Id;
  w.render();

  fireClick(d.querySelector(".toggle-notes"), w); // show notes
  T.state.notes.set(skip1Id, "orphan me not");
  w.applyTempAnchorFadeSeconds(0.5);
  const modeSelect = d.querySelector("#settingsTempAnchorMode");
  modeSelect.value = "fade";
  modeSelect.dispatchEvent(new w.Event("change", { bubbles: true }));

  T.state.tempAnchor = null;
  w.render();
  fireClick(d.querySelector('.tree-row[data-node-id="' + narrowFilter.id + '"]'), w);
  const anchorRow = d.querySelector("#tableRows .log-row.temp-anchor-row");
  assert(!!anchorRow, "sanity: fade mode draws the anchor row right after the switch");
  const noteRowBefore = anchorRow.nextElementSibling;
  assert(noteRowBefore && noteRowBefore.classList.contains("note-row") && noteRowBefore.dataset.entryId === skip1Id,
    "sanity: the anchor row's note renders as its sibling note-row while the row is still shown");

  await waitFor(() => d.querySelector("#tableRows .log-row.temp-anchor-row") === null); // past the 0.5s fade duration
  assert(d.querySelector("#tableRows .log-row.temp-anchor-row") === null, "the fading anchor row is removed once its fade completes");
  assert(d.querySelector('#tableRows .note-row[data-entry-id="' + skip1Id + '"]') === null,
    "BUGFIX: its note-row is removed in the same step, not left behind orphaned under nothing");
});

/* ============================================================
   GROUP 107 — Settings: "Close to system tray" (FEATURE_BACKLOG.md #51)
   Origin: this session (2026-08-25). Purely a local app-behavior
   preference (localStorage, like GROUP 76's quit-on-last-close), default
   ON this time (unlike GROUP 76's default off) since that's the requested
   desktop-build default. The wrapper (untestable under jsdom) mirrors this
   same key out of localStorage and consults it when a window close is
   requested; this file only owns persisting the checkbox state.
   ============================================================ */
group(107);
await withApp(async (w, d, T) => {
  section("107. Settings: \"Close to system tray\" (default on)");

  const checkbox = d.getElementById("settingsCloseToTray");
  assert(checkbox.checked === true, "on by default");
  assert(w.localStorage.getItem("philogg-close-to-tray") === null, "nothing persisted yet — default comes from the null->true fallback, not a stored value");

  checkbox.checked = false;
  checkbox.dispatchEvent(new w.Event("change", { bubbles: true }));
  assert(w.localStorage.getItem("philogg-close-to-tray") === "0", "disabling the checkbox persists it");

  checkbox.checked = true;
  checkbox.dispatchEvent(new w.Event("change", { bubbles: true }));
  assert(w.localStorage.getItem("philogg-close-to-tray") === "1", "re-enabling persists back to \"1\"");
});

/* ============================================================
   GROUP 108 — Bugfix: plain arrow-key nav after Alt+Arrow-switching onto a
   Link filter no longer navigates the STALE previous filter's entries
   (person-reported, this session: "after switching filters with Alt+Arrow,
   plain arrow keys seem to still navigate the old list — the entry detail
   panel updates but nothing highlights in the Log list").
   Root cause: renderMainView() calls renderLinkView() instead of
   renderTable() while a Link filter is active, so currentViewEntries (which
   only renderTable() repopulates) keeps whatever filter's list was active
   before the switch. The plain ArrowUp/ArrowDown handler didn't know this
   and called moveSelection(), which found some entry in that stale list,
   selected it (updating the detail panel via entryIndex, which works for
   ANY id), but no row in the (unrelated) Link view's DOM ever matches that
   id, so updateSelectedRowClass finds nothing to mark "selected" — exactly
   the reported symptom. Fixed with the same guard extractWrap already had:
   Up/Down no-ops while linkWrap is the visible Filtered-pane content,
   instead of running against stale data (the Link view has its own
   click-driven pair selection, no Up/Down of its own to route into).
   ============================================================ */
group(108);
await withApp(async (w, d, T) => {
  section("108. Bugfix: arrow-key nav doesn't use a stale currentViewEntries after switching onto a Link filter");

  const f = await w.addFile("app.log", makeLog(0, 6, { suffix: i => (i % 2 === 0 ? "keep" : "skip") }), () => {});
  const keepFilter = w.createFilterNode(f.id, "text", "keep"); // matches entries 0,2,4
  const skipFilter = w.createFilterNode(f.id, "text", "skip"); // matches entries 1,3,5
  const linkFilter = w.createLinkNode(keepFilter.id, skipFilter.id, "after", 1);
  w.render();

  T.state.activeId = keepFilter.id;
  T.state.entriesView = "filter";
  T.state.focusRegion = "entries";
  w.render();
  fireClick(d.querySelectorAll("#tableRows .log-row")[0], w); // select "keep" entry 0
  const keep0Id = T.state.selectedId;
  assert(!!keep0Id, "sanity: clicking a Filtered-view row selects it");

  // Switch the active node onto the Link filter (same net effect as an
  // Alt+Arrow tree-nav step — see GROUP 99 — deliberately not touching
  // focusRegion/entriesView/selectedId); linkFilter's own position in the
  // tree (always directly under FILE now, see GROUP 128) isn't what this
  // group is testing, just the stale-currentViewEntries guard once it's active.
  T.state.activeId = linkFilter.id;
  w.render();
  assert(T.state.activeId === linkFilter.id, "sanity: active node switched onto the Link filter");
  assert(d.querySelector("#linkWrap").style.display !== "none", "the Link view is now showing in the Filtered pane");

  fireKeydown(d, w, "ArrowDown"); // plain arrow key nav, no Alt
  assert(T.state.selectedId === keep0Id,
    "plain ArrowDown while the Link view is active does NOT change the selection (no stale-list jump)");

  // Switching back to a plain text filter (renderTable() runs again)
  // refreshes currentViewEntries and arrow-key nav works normally again.
  T.state.activeId = keepFilter.id;
  w.render();
  assert(T.state.activeId === keepFilter.id, "sanity: switched back onto keepFilter");
  fireKeydown(d, w, "ArrowDown");
  const keep2Id = d.querySelectorAll("#tableRows .log-row")[1].dataset.entryId;
  assert(T.state.selectedId === keep2Id, "arrow-key nav works normally again once back on a plain (table) filter");
});

/* ============================================================
   GROUP 109 — "Open File Location" (FEATURE_BACKLOG.md #52)
   Origin: this session (person-requested, generalized beyond the backlog
   entry's one-wrapper wording): a file node's context menu offers
   "Open File Location" whenever a real OS path is actually known
   (node.localPath, supplied by the desktop wrapper — simulated here via a
   stub window.philogg, since jsdom can't run a real webview host) AND
   window.philogg exists (i.e. the desktop build) — never in a plain
   browser build, where no web API can resolve a File back to a filesystem
   path at all. A node loaded via a philogg://local/… deep link (desktop
   launch-arg/file-association) gets the same item routed through
   revealLocalUrl instead, since only the wrapper holds that path. Any ?url= node (local or plain http(s)) instead offers
   "Copy URL" for the URL itself, but ONLY for a genuine http(s) link —
   not for the desktop-local scheme, which has no meaningful "URL" to a
   person. Both items are also round-tripped through the session cache
   (persistFileNode/restoreSessionFromCache) so they survive a reload.
   ============================================================ */
group(109);
await withApp(async (w, d, T) => {
  section("109a. \"Open File Location\" / \"Copy URL\": absent outside the desktop build (no window.philogg)");

  const f = await w.addFile("plain.log", makeLog(0, 5), () => {});
  f.localPath = "/home/user/logs/plain.log"; // simulate a resolved path even though nothing can act on it
  T.state.activeId = f.id;
  w.render();
  fireContextMenu(d.querySelector('.tree-row[data-node-id="' + f.id + '"]'), w);
  assert(!d.querySelector('#treeContextMenu [data-action="revealLocation"]'),
    "no \"Open File Location\" item without window.philogg, even with a localPath set");
  w.closeTreeContextMenu();
});

await withApp(async (w, d, T) => {
  section("109b. \"Open File Location\": local path resolved via window.philogg (in-app picker / drag-drop / folder watch)");

  let revealedPath = null;
  w.philogg = { getPathForFile: () => null, revealPath: p => { revealedPath = p; }, revealLocalUrl: () => {} };

  const f = await w.addFile("app.log", makeLog(0, 5), () => {});
  f.localPath = "/home/user/logs/app.log";
  T.state.activeId = f.id;
  w.render();

  fireContextMenu(d.querySelector('.tree-row[data-node-id="' + f.id + '"]'), w);
  const revealItem = d.querySelector('#treeContextMenu [data-action="revealLocation"]');
  assert(revealItem, "\"Open File Location\" offered once window.philogg + node.localPath are both present");
  assert(!d.querySelector('#treeContextMenu [data-action="copyUrl"]'), "no \"Copy URL\" — this node has no sourceUrl");
  fireClick(revealItem, w);
  assert(revealedPath === "/home/user/logs/app.log", "clicking it calls philogg.revealPath with the node's localPath, got " + revealedPath);
});

await withApp(async (w, d, T) => {
  section("109c. \"Open File Location\": desktop launch-arg file (philogg://local/… sourceUrl, no localPath)");

  let revealedLocalUrl = null;
  w.philogg = { getPathForFile: () => null, revealPath: () => { throw new Error("should not be called"); }, revealLocalUrl: u => { revealedLocalUrl = u; } };

  const f = await w.addFile("launched.log", makeLog(0, 5), () => {});
  f.sourceUrl = "philogg://local/3/launched.log"; // set directly — loadUrlIntoTree itself needs a live fetch, out of scope here
  T.state.activeId = f.id;
  w.render();

  fireContextMenu(d.querySelector('.tree-row[data-node-id="' + f.id + '"]'), w);
  const revealItem = d.querySelector('#treeContextMenu [data-action="revealLocation"]');
  assert(revealItem, "\"Open File Location\" offered for a philogg://local/… sourceUrl even with no localPath");
  assert(!d.querySelector('#treeContextMenu [data-action="copyUrl"]'), "no \"Copy URL\" for the desktop-local scheme — it's not a real URL to a person");
  fireClick(revealItem, w);
  assert(revealedLocalUrl === "philogg://local/3/launched.log", "clicking it calls philogg.revealLocalUrl with the node's sourceUrl, got " + revealedLocalUrl);
});

