/* ============================================================
   GROUP 112 — Three person-reported follow-ups to GROUP 111's own
   settings work (this session): Log text size not rescaling ROW_HEIGHT
   (rows overflowed/clipped at larger scales), "On open, scroll log to"
   End firing before a large file finished loading, and a stale
   state.multiSelect entry leaving a second file's sidebar row showing
   the SAME highlight as the newly active file's row.
   ============================================================ */
group(112);
await withApp(async (w, d, T) => {
  section("112a. Bugfix: Log text size rescales ROW_HEIGHT (and EXTRACT_ROW_HEIGHT/LINK_PAIR_ROW_HEIGHT), not just font-size");

  const f = await w.addFile("a.log", makeLog(0, 5), () => {});
  w.render();
  const rowBefore = d.querySelector(".log-row");
  assert(rowBefore && rowBefore.style.height === "28px", "sanity: a row is 28px tall at 100% log text size");

  const logUp = d.querySelector("#logTextScaleUp");
  // 100% -> 110% -> 120% -> ... -> 160% (six clicks of the default 10% step).
  for (let i = 0; i < 6; i++) fireClick(logUp, w);
  assert(d.querySelector("#logTextScaleValue").textContent === "160%", "sanity: Log text size is now 160%");

  const rowAfter = d.querySelector(".log-row");
  assert(rowAfter.style.height === "45px", "row height rescaled proportionally with Log text size (28 * 1.6 = 44.8, rounded to 45), got " + rowAfter.style.height);

  // The extraction table and link/pair views use the same --log-text-scale
  // var in their CSS (#extractTable, .pair-row-time/.pair-row-msg — see
  // :root) — their own fixed-pixel row heights must rescale in lockstep.
  assert(T.EXTRACT_ROW_HEIGHT === 45, "EXTRACT_ROW_HEIGHT rescaled the same way, got " + T.EXTRACT_ROW_HEIGHT);
  assert(T.LINK_PAIR_ROW_HEIGHT === 42, "LINK_PAIR_ROW_HEIGHT rescaled the same way (26 * 1.6 = 41.6, rounded to 42), got " + T.LINK_PAIR_ROW_HEIGHT);

  // Resetting back to 100% restores the original heights exactly (no
  // rounding drift left over from the round trip).
  fireClick(d.querySelector("#logTextScaleReset"), w);
  assert(d.querySelector(".log-row").style.height === "28px", "resetting Log text size back to 100% restores the original 28px row height");
  assert(T.EXTRACT_ROW_HEIGHT === 28 && T.LINK_PAIR_ROW_HEIGHT === 26, "EXTRACT_ROW_HEIGHT/LINK_PAIR_ROW_HEIGHT also reset to their base values");
});

await withApp(async (w, d, T) => {
  section("112b. Bugfix: \"On open, scroll log to\" End keeps trailing the bottom through every load tick, not just the first one");

  const select = d.querySelector("#settingsOpenScrollPosition");
  select.value = "end";
  select.dispatchEvent(new w.Event("change", { bubbles: true }));

  const tableBody = d.querySelector("#tableBody");
  Object.defineProperty(tableBody, "scrollHeight", { value: 3000, configurable: true });

  // Simulate a large file: the real row (createFileNode) exists and is
  // active, entries have streamed in from an early parse chunk, but the
  // node is still mid-load (loadFraction a number, not yet deleted — see
  // loadOneFileIntoTree's `finally`). Before the fix, renderTable()
  // consumed and deleted the one-shot _openScrollToEnd flag on this very
  // first non-empty render, landing at whatever "end" existed at that
  // instant instead of the file's true end.
  const node = w.createFileNode("big.log");
  assert(node._openScrollToEnd === true, "sanity: the one-shot flag was set at file creation (\"End\" is selected)");
  await w.parseLogTextAsync(makeLog(0, 20), node, () => {});
  node.loadFraction = 0.4; // still loading — a later chunk hasn't landed yet
  w.renderTable();
  assert(tableBody.scrollTop === tableBody.scrollHeight, "mid-load: still trails to the (partial) bottom on this tick");
  assert(node._openScrollToEnd === true, "mid-load: the flag is NOT consumed yet — the file isn't done loading");

  // More entries land on a later chunk (grows scrollHeight, as a real
  // parse tick would) while still mid-load.
  Object.defineProperty(tableBody, "scrollHeight", { value: 5000, configurable: true });
  w.renderTable();
  assert(tableBody.scrollTop === 5000, "still-loading: keeps re-trailing to the NEW bottom as more entries stream in, not stuck at the old one");
  assert(node._openScrollToEnd === true, "still-loading: flag still held");

  // Loading finishes for real.
  delete node.loadFraction;
  w.renderTable();
  assert(tableBody.scrollTop === 5000, "load finished: settles at the true final bottom");
  assert(node._openScrollToEnd === undefined, "load finished: the one-shot flag is NOW consumed");

  // One-shot, still: a later re-render (e.g. switching away and back) must
  // not re-trigger the jump now that the flag is gone (same guarantee
  // GROUP 111d already covers for the non-chunked case).
  tableBody.scrollTop = 0;
  w.renderTable();
  assert(tableBody.scrollTop !== 5000, "post-completion re-render does not re-force the scroll back to the bottom (flag already consumed)");

  select.value = "start";
  select.dispatchEvent(new w.Event("change", { bubbles: true }));
});

await withApp(async (w, d, T) => {
  section("112c. Bugfix: loading a second file no longer leaves a stale multi-selected highlight on the first file's row");

  const f1 = await w.addFile("app-1.log", makeLog(0, 5), () => {});
  w.render();

  // A plain (non-Ctrl) click on a file's own tree row — completely
  // ordinary navigation, e.g. switching to inspect it — sets
  // state.multiSelect to that row alone (renderNode's click handler).
  const row1 = d.querySelector('.tree-row[data-node-id="' + f1.id + '"]');
  fireClick(row1, w);
  assert(T.state.multiSelect.has(f1.id) && T.state.multiSelect.size === 1, "sanity: clicking app-1.log's tree row sets multiSelect to just that row");

  // Select a log entry too, matching the person's own repro description.
  const logRow = d.querySelector(".log-row");
  if (logRow) fireClick(logRow, w);

  // Load a second file (drag-and-drop and the file input both funnel
  // through loadFileDescriptors -> createFileNode/activateQueuedFileNode).
  const f2 = await w.addFile("app-2.log", makeLog(100, 3), () => {});
  w.render();

  assert(T.state.activeId === f2.id, "sanity: app-2.log is now the active file");
  assert(!T.state.multiSelect.has(f1.id), "loading app-2.log clears the stale multiSelect entry pointing at app-1.log's row");

  const rows = [...d.querySelectorAll(".tree-row")];
  const highlighted = rows.filter(r => r.classList.contains("active") || r.classList.contains("multi-selected"));
  assert(highlighted.length === 1, "exactly one tree row carries an active/selected visual state after loading the second file, got " + highlighted.length);
  assert(highlighted[0].dataset.nodeId === f2.id, "...and it's the newly loaded, genuinely active file's row");
});

/* ============================================================
   GROUP 113 — Desktop-only UI font extension: window.philogg.listSystemFonts
   Origin: this session (person-requested follow-up to GROUP 111f). The
   plain HTML build can't enumerate installed fonts (no permission-prompt
   UI for the Local Font Access API), but the desktop wrapper can shell out
   to the OS via the wrapper's listSystemFonts bridge with no permission
   dialog needed, since it's a native process. On
   the desktop build the picker appends every reported name as an extra
   <option> (deduped against the curated list); selecting one stores a
   "sys:<name>" id and applies '"<name>",<default fallback stack>' as
   --font-ui. Outside the desktop build (no window.philogg) nothing changes
   from GROUP 111f's plain curated-list behavior.
   ============================================================ */
group(113);
await withApp(async (w, d, T) => {
  section("113a. No window.philogg (plain HTML build): font list stays curated-only");

  const select = d.querySelector("#settingsUiFontSelect");
  const before = select.options.length;
  assert(!select.querySelector("optgroup"), "no system-fonts optgroup without window.philogg");
  assert(select.options.length === before, "option count unchanged from the curated list");
});

await withApp(async (w, d, T) => {
  section("113b. window.philogg.listSystemFonts (desktop build): extra fonts appended and selectable");

  const select = d.querySelector("#settingsUiFontSelect");
  const curatedCount = select.options.length;

  // initUiFont() already ran during JSDOM's synchronous script execution and
  // kicked off the listSystemFonts().then(...) microtask; await it directly.
  await w.philogg.listSystemFonts().then(() => Promise.resolve());
  // Let the microtask queue (the real .then() chain inside initUiFont) flush.
  await new Promise(r => setTimeout(r, 0));

  const group = select.querySelector("optgroup");
  assert(group, "a system-fonts optgroup is appended once listSystemFonts resolves");
  assert(select.options.length > curatedCount, "extra options beyond the curated list are present");
  const firaOption = [...select.options].find(o => o.textContent === "Fira Code");
  assert(firaOption, "\"Fira Code\" (reported by the stub) is offered as an option");
  assert(firaOption.value === "sys:Fira Code", "its option value carries the sys: prefix + exact reported name");
  assert(![...select.options].some(o => o.textContent === "Arial"), "a name duplicating the curated list (\"Arial\") is not appended twice");

  select.value = firaOption.value;
  select.dispatchEvent(new w.Event("change", { bubbles: true }));
  assert(w.document.documentElement.style.getPropertyValue("--font-ui").startsWith('"Fira Code",'),
    "selecting a system font sets --font-ui to the quoted name plus the default fallback stack");
  assert(w.localStorage.getItem("philogg-ui-font") === "sys:Fira Code", "the sys:-prefixed id persists to localStorage like any other font choice");
}, { philogg: { getPathForFile: () => null, revealPath: () => {}, revealLocalUrl: () => {}, listSystemFonts: () => Promise.resolve(["Fira Code", "Iosevka", "Arial"]) } });

/* ============================================================
   GROUP 114 — Shortcut Manager in Settings (FEATURE_BACKLOG.md #48)
   Origin: this session. Replaces the old standalone #shortcutsPanel popup
   (GROUP 26) with a dedicated "Shortcuts" section inside Settings: a
   rebindable-actions table (matchesShortcut(ev, actionId) looks up
   localStorage-backed overrides instead of a hardcoded key check).
   Updated (FEATURE_BACKLOG.md #55): the old usage-instruction prose above
   the table and the separate "fixed reference" text block below it are
   gone. Fixed (non-rebindable) shortcuts are now appended as extra,
   greyed-out rows (.shortcut-row-fixed, no rebind/reset controls) inside
   the SAME #shortcutBindingsList, so the list still reads as complete.
   ============================================================ */
group(114);
await withApp(async (w, d, T) => {
  section("114a. Settings' Shortcuts section: rebindable rows + greyed-out fixed rows, no prose");

  assert(d.querySelector("#settingsDialog").classList.contains("hidden"), "sanity: Settings starts closed");
  w.openSettingsDialog();
  assert(!d.querySelector("#settingsDialog").classList.contains("hidden"), "openSettingsDialog opens Settings");
  assert(d.querySelector("#settingsSectionShortcuts"), "a dedicated Shortcuts section exists in Settings");
  assert(!d.querySelector("#settingsSectionShortcuts .settings-section-desc"), "the usage-instruction prose under the section title is gone");
  const rebindableRows = d.querySelectorAll("#shortcutBindingsList > div[data-action-id]");
  assert(rebindableRows.length === 20, "the rebindable-actions rows render one per registered action");
  const fixedRows = d.querySelectorAll("#shortcutBindingsList > div.shortcut-row-fixed");
  assert(fixedRows.length > 0, "fixed (non-rebindable) shortcuts are listed too, so the list stays complete");
  fixedRows.forEach(row => {
    assert(!row.querySelector(".shortcut-rebind-btn") && !row.querySelector(".shortcut-reset-btn"),
      "a fixed row has no Change/Reset controls — it can't be edited or deleted");
  });
  assert(d.querySelector("#shortcutBindingsList").children.length === rebindableRows.length + fixedRows.length,
    "rebindable and fixed rows together make up the whole list");
});

await withApp(async (w, d, T) => {
  section("114b. Rebinding an action changes which key triggers it");

  const f = await w.addFile("a.log", makeLog(0, 5), () => {});
  w.render();
  w.selectEntry(f.entries[1].id);

  // Default: bare "B" bookmarks the selected row.
  fireKeydown(d, w, "b");
  assert(T.state.bookmarks.has(f.entries[1].id), "sanity: default 'B' shortcut still bookmarks");
  w.toggleBookmark(f.entries[1].id); // undo, back to a clean slate

  w.openSettingsDialog();
  // Each render*/rebind step rebuilds #shortcutBindingsList's rows from
  // scratch (renderShortcutBindingsList), so every query below is re-run
  // fresh against the DOM rather than caching a row/button reference across
  // a re-render (which would silently go stale/detached).
  fireClick(d.querySelector("[data-action-id='bookmark'] .shortcut-rebind-btn"), w);
  assert(d.querySelector("[data-action-id='bookmark'] .shortcut-rebind-btn").classList.contains("recording"),
    "the rebind button shows a recording state while listening");
  fireKeydown(d, w, "k");
  assert(w.localStorage.getItem("philogg.shortcutBindings") === JSON.stringify({ bookmark: { ctrl: false, shift: false, alt: false, key: "k" } }),
    "the new combo persists to localStorage under the action's id");
  assert(!d.querySelector("[data-action-id='bookmark'] .shortcut-rebind-btn").classList.contains("recording"),
    "recording ends once a key is captured (row re-rendered)");

  fireKeydown(d, w, "b");
  assert(!T.state.bookmarks.has(f.entries[1].id), "'B' no longer bookmarks after being rebound");
  fireKeydown(d, w, "k");
  assert(T.state.bookmarks.has(f.entries[1].id), "the newly bound 'K' now bookmarks the selected row instead");
});

await withApp(async (w, d, T) => {
  section("114c. Conflict detection, reset-one, and reset-all");

  w.openSettingsDialog();

  // Conflict: try to rebind "toggleDetail" (default Ctrl+J) onto "editFilter"'s (Ctrl+E) combo.
  fireClick(d.querySelector("[data-action-id='toggleDetail'] .shortcut-rebind-btn"), w);
  fireKeydown(d, w, "e", { ctrlKey: true });
  assert(!d.querySelector("#shortcutConflictNote").classList.contains("hidden"), "a conflicting combo shows the conflict note");
  assert(d.querySelector("#shortcutConflictNote").textContent.includes("Edit a filter"), "the conflict note names the action already using that combo");
  assert(w.localStorage.getItem("philogg.shortcutBindings") === null || !JSON.parse(w.localStorage.getItem("philogg.shortcutBindings") || "{}").toggleDetail,
    "the conflicting rebind is rejected — no override is stored for toggleDetail");
  fireKeydown(d, w, "Escape"); // cancel the still-active recording

  // Reset a single rebound action back to its default.
  fireClick(d.querySelector("[data-action-id='bookmark'] .shortcut-rebind-btn"), w);
  fireKeydown(d, w, "k");
  fireClick(d.querySelector("[data-action-id='bookmark'] .shortcut-reset-btn"), w);
  assert(!JSON.parse(w.localStorage.getItem("philogg.shortcutBindings") || "{}").bookmark, "the reset button clears that action's override");

  // Reset-all.
  fireClick(d.querySelector("[data-action-id='closeFile'] .shortcut-rebind-btn"), w);
  fireKeydown(d, w, "q", { ctrlKey: true });
  assert(JSON.parse(w.localStorage.getItem("philogg.shortcutBindings")).closeFile, "sanity: an override is stored before reset-all");
  fireClick(d.querySelector("#btnResetShortcuts"), w);
  assert(JSON.parse(w.localStorage.getItem("philogg.shortcutBindings")) && Object.keys(JSON.parse(w.localStorage.getItem("philogg.shortcutBindings"))).length === 0,
    "\"Reset all to defaults\" clears every override");
});

/* ============================================================
   GROUP 115 — Back/forward "where I looked" navigation (FEATURE_BACKLOG.md
   #53) and the toolbar regroup (FEATURE_BACKLOG.md #56).
   Origin: this session, person-requested. #53: a browser/IDE-style history
   of visited filter nodes (+ per-node scroll position), distinct from
   Undo/Redo (which never touches navHistory — see the undo()/redo() code,
   unchanged). #56: "Session…"/"Open…" toolbar buttons became "Open…"
   (files/folder/import-session) and "Save" (export-session only), moved out
   of #toolbar entirely into #sidebarHeader.
   Follow-up (same session, person-requested): the version tag moved OUT of
   #toolbar's right side into its own line directly under the "PhiLogg"
   wordmark (`.brand` is now a column: `.brand-row` for mark+name, then
   `.brand-version` below — the wordmark's own position is unchanged). The
   back/forward buttons moved OUT of #sidebarHeader into #toolbar itself,
   in the same row as Settings/Undo/Redo but left-aligned right next to the
   brand (via `.toolbar-spacer` absorbing the rest of the row's width) —
   closer to the wordmark than the other toolbar-right buttons, which stay
   flush right exactly as before.
   ============================================================ */
group(115);
await withApp(async (w, d, T) => {
  section("115a. Toolbar regroup: nav buttons live in #toolbar near the wordmark, open/save in #sidebarHeader, #btnSession is gone, version tag under the wordmark");
  assert(!!d.querySelector("#toolbar #btnNavBack"), "back button lives in #toolbar");
  assert(!!d.querySelector("#toolbar #btnNavForward"), "forward button lives in #toolbar");
  assert(d.querySelector("#sidebarHeader #btnNavBack") === null, "back button no longer lives in #sidebarHeader");
  assert(d.querySelector("#sidebarHeader #btnNavForward") === null, "forward button no longer lives in #sidebarHeader");
  assert(!!d.querySelector("#sidebarHeader #btnOpen"), "Open button lives in #sidebarHeader");
  assert(!!d.querySelector("#sidebarHeader #btnSave"), "Save button lives in #sidebarHeader");
  assert(d.querySelector("#toolbar #btnOpen") === null, "Open button is not in the top toolbar");
  assert(d.querySelector("#btnSession") === null, "#btnSession no longer exists");
  assert(d.querySelector("#sessionMenu") === null, "#sessionMenu no longer exists");
  assert(!!d.querySelector(".brand #brandVersion"), "version tag sits under the wordmark, inside .brand");
  assert(d.querySelector(".toolbar-right #brandVersion") === null, "version tag no longer sits in the toolbar's right side");
  assert(!!d.querySelector(".brand .brand-row .brand-name"), "the wordmark itself stays in its own row, unmoved");
  // Nav group must come right after .brand and before the spacer that
  // pushes the rest of the toolbar's controls to the far right.
  const toolbarChildren = [...d.querySelector("#toolbar").children].map(c => c.className || c.id);
  const brandIdx = toolbarChildren.findIndex(c => c === "brand");
  const navIdx = toolbarChildren.findIndex(c => c === "toolbar-group" || c.includes("toolbar-group"));
  const spacerIdx = toolbarChildren.findIndex(c => c === "toolbar-spacer");
  assert(brandIdx === 0 && navIdx === 1 && spacerIdx === 2,
    "DOM order is brand, nav group, spacer, then the rest — got " + toolbarChildren.join(","));
  assert(d.querySelector("#btnNavBack").disabled, "back starts disabled with nothing visited yet");
  assert(d.querySelector("#btnNavForward").disabled, "forward starts disabled with nothing visited yet");
});

await withApp(async (w, d, T) => {
  section("115b. Back/forward steps through visited filter nodes, distinct from Undo/Redo");
  const f = await w.addFile("a.log", makeLog(0, 20), () => {});
  const n1 = w.createFilterNode(f.id, "text", "message");
  w.render();
  const n2 = w.createFilterNode(f.id, "text", "ERROR");
  w.render();
  assert(T.state.activeId === n2.id, "sanity: creating n2 made it active");
  assert(T.navHistory.length === 3, "history has file + n1 + n2, got " + T.navHistory.length); // file root counts as the first visit
  assert(!d.querySelector("#btnNavBack").disabled, "back is enabled after two navigations");
  assert(d.querySelector("#btnNavForward").disabled, "forward is disabled at the head of history");

  fireClick(d.querySelector("#btnNavBack"), w);
  assert(T.state.activeId === n1.id, "back moved active node from n2 to n1");
  assert(!d.querySelector("#btnNavForward").disabled, "forward is enabled after going back");

  fireClick(d.querySelector("#btnNavBack"), w);
  assert(T.state.activeId === f.id, "back again moved to the file root");
  assert(d.querySelector("#btnNavBack").disabled, "back is disabled at the start of history");

  fireClick(d.querySelector("#btnNavForward"), w);
  fireClick(d.querySelector("#btnNavForward"), w);
  assert(T.state.activeId === n2.id, "forward twice returns to n2");

  // Undo/Redo is untouched by any of this — it only ever tracks tree edits.
  assert(T.undoStack.length === 0, "sanity: Undo/Redo stayed empty, back/forward is not recorded as an edit");
});

await withApp(async (w, d, T) => {
  section("115c. A fresh navigation truncates any forward history, same as browser back/forward");
  const f = await w.addFile("a.log", makeLog(0, 20), () => {});
  const n1 = w.createFilterNode(f.id, "text", "message");
  w.render();
  const n2 = w.createFilterNode(f.id, "text", "ERROR");
  w.render();
  fireClick(d.querySelector("#btnNavBack"), w); // back to n1
  assert(T.state.activeId === n1.id, "sanity: back landed on n1");

  const n3 = w.createFilterNode(f.id, "text", "warn");
  w.render();
  assert(T.state.activeId === n3.id, "sanity: creating n3 made it active");
  assert(d.querySelector("#btnNavForward").disabled, "forward is disabled — n2 was dropped by the new branch");
  fireClick(d.querySelector("#btnNavBack"), w);
  assert(T.state.activeId === n1.id, "back from n3 goes to n1, not the discarded n2");
});

// Rewritten in place this session: scrolling used to overwrite the current
// waypoint's raw scrollTop on EVERY scroll event, which both destroyed the
// place being left and made a scroll unable to be a waypoint of its own.
// It is now B1 (scroll + dwell + one viewport of travel) plus an anchor row
// instead of a raw pixel offset — see the nav-history comment in
// philogg.html for the full tier list.
await withApp(async (w, d, T) => {
  section("115d. A scroll the person dwells on becomes its own waypoint, restored via its anchor row");
  const f = await w.addFile("a.log", makeLog(0, 200), () => {});
  const n1 = w.createFilterNode(f.id, "text", "message");
  w.render();
  const tableBody = d.querySelector("#tableBody");
  const rowH = T.ROW_HEIGHT;
  // renderTable's own reset-to-top is a programmatic scroll; a person's
  // scroll landing inside its 150ms window is deliberately ignored (same
  // guard the tail-follow listeners use), so step outside it first.
  await sleep(PROGRAMMATIC_SCROLL_SETTLE);
  // Well past one viewport (clientHeight is stubbed at 400 in this suite),
  // then held still — that is what makes it a place worth returning to.
  tableBody.scrollTop = rowH * 50 + 10;
  tableBody.dispatchEvent(new w.Event("scroll", { bubbles: true }));
  await sleep(NAV_DWELL_WAIT);
  assert(T.navHistory.length === 3, "scroll + dwell appended a waypoint after the file + filter visits, got " + T.navHistory.length);

  const n2 = w.createFilterNode(f.id, "text", "ERROR");
  w.render();
  tableBody.scrollTop = 0; // n2's own view starts at the top

  fireClick(d.querySelector("#btnNavBack"), w);
  assert(T.state.activeId === n1.id, "sanity: back landed on n1");
  // Row-granular by design: the waypoint remembers the ENTRY that was at the
  // top of the viewport (robust against a tail tick, a level-filter change or
  // a re-sort shifting every pixel offset underneath it), and puts that row
  // back at the top.
  assert(tableBody.scrollTop === rowH * 50, "going back lands the anchor row back at the top of the viewport, got " + tableBody.scrollTop);
});

await withApp(async (w, d, T) => {
  section("115e. Deleting the node a stale history entry points at doesn't break further back/forward");
  const f = await w.addFile("a.log", makeLog(0, 20), () => {});
  const n1 = w.createFilterNode(f.id, "text", "message");
  w.render();
  const n2 = w.createFilterNode(f.id, "text", "ERROR");
  w.render();
  fireClick(d.querySelector("#btnNavBack"), w); // active is n1, n2 still ahead in forward history
  assert(T.state.activeId === n1.id, "sanity: back landed on n1");

  w.deleteNode(n2.id);
  w.render();

  // Forward history still references the now-deleted n2 — must not throw
  // and must not get stuck on a dangling id.
  fireClick(d.querySelector("#btnNavForward"), w);
  assert(T.state.nodes[T.state.activeId] !== undefined, "forward after a deleted target lands on a node that still exists, got " + T.state.activeId);
});

await withApp(async (w, d, T) => {
  section("115f. Mouse back/forward buttons (button 3/4) drive the same navigation");
  const f = await w.addFile("a.log", makeLog(0, 20), () => {});
  const n1 = w.createFilterNode(f.id, "text", "message");
  w.render();
  w.createFilterNode(f.id, "text", "ERROR");
  w.render();

  d.dispatchEvent(new w.MouseEvent("mouseup", { bubbles: true, cancelable: true, button: 3 }));
  assert(T.state.activeId === n1.id, "mouse back-button (button 3) navigates back");

  d.dispatchEvent(new w.MouseEvent("mouseup", { bubbles: true, cancelable: true, button: 4 }));
  assert(T.state.activeId !== n1.id, "mouse forward-button (button 4) navigates forward");
});

await withApp(async (w, d, T) => {
  section("115g. A scroll burst is ONE waypoint at the destination; a short scroll is none");
  const f = await w.addFile("a.log", makeLog(0, 300), () => {});
  w.createFilterNode(f.id, "text", "message");
  w.render();
  const tableBody = d.querySelector("#tableBody");
  const before = T.navHistory.length;
  await sleep(PROGRAMMATIC_SCROLL_SETTLE); // see 115d — step clear of renderTable's own reset-to-top

  // Three rapid scroll events with no dwell between them: the timer restarts
  // each time, so only the resting position counts.
  for (const top of [300, 900, 1800]) {
    tableBody.scrollTop = top;
    tableBody.dispatchEvent(new w.Event("scroll", { bubbles: true }));
    await sleep(40);
  }
  await sleep(NAV_DWELL_WAIT);
  assert(T.navHistory.length === before + 1, "a scroll burst produces exactly one waypoint, got " + (T.navHistory.length - before));

  // Under one viewport of travel from the waypoint just made: refreshed in
  // place, not appended.
  const afterBurst = T.navHistory.length;
  tableBody.scrollTop = 1900;
  tableBody.dispatchEvent(new w.Event("scroll", { bubbles: true }));
  await sleep(NAV_DWELL_WAIT);
  assert(T.navHistory.length === afterBurst, "a scroll shorter than one viewport adds no waypoint, got " + (T.navHistory.length - afterBurst));
});

await withApp(async (w, d, T) => {
  section("115h. A programmatic scroll (tail-follow, a jump, a history restore) is never a waypoint");
  const f = await w.addFile("a.log", makeLog(0, 300), () => {});
  w.createFilterNode(f.id, "text", "message");
  w.render();
  const tableBody = d.querySelector("#tableBody");
  const before = T.navHistory.length;
  w.setTableScroll(3000); // stamps lastProgrammaticScrollTs, same as follow/jump/restore do
  tableBody.dispatchEvent(new w.Event("scroll", { bubbles: true }));
  await sleep(NAV_DWELL_WAIT);
  assert(T.navHistory.length === before, "a code-driven scroll adds no waypoint, got " + (T.navHistory.length - before));
});

await withApp(async (w, d, T) => {
  section("115i. A double-click reveal into the Context view is its own waypoint; Back returns to the Filtered pane");
  const f = await w.addFile("a.log", makeLog(0, 60), () => {});
  w.render();
  w.applyFhView("filter");
  const before = T.navHistory.length;

  w.revealInHighlightView(f.entries[30]);
  assert(T.fhActiveTab === "highlight", "sanity: the reveal switched to the Context pane");
  assert(T.navHistory.length === before + 1, "the reveal appended one waypoint, got " + (T.navHistory.length - before));

  fireClick(d.querySelector("#btnNavBack"), w);
  assert(T.fhActiveTab === "filter", "back returns to the Filtered pane the jump started from");
  fireClick(d.querySelector("#btnNavForward"), w);
  assert(T.fhActiveTab === "highlight", "forward returns to the Context pane");
  assert(T.state.selectedId === f.entries[30].id, "forward restores the entry the reveal had selected");
});

