await withApp(async (w, d, T) => {
  section("169e. XSS safety: an unmatched '<script>'-shaped fragment and formatted output both stay inert markup");

  const f = await w.addFile("app.log", makeLog(0, 1), () => {});
  // <img ...> is unclosed (no matching </img>, and its own src= attribute
  // isn't even quoted, so it isn't a valid candidate tag at all) — must
  // never become real DOM markup. <safe a="&amp;"/> IS well-formed XML (a
  // self-closing tag with a properly-escaped attribute value); its
  // formatted output must re-escape that "&" rather than emit it raw.
  f.entries[0].message = 'payload <img src=x onerror="alert(1)"> unclosed and <safe a="&amp;"/> ok';
  T.state.selectedId = f.entries[0].id;
  w.updateDetailPanel();
  const el = d.querySelector("#detailMessage");
  assert(!el.querySelector("img"), "an unmatched (unclosed) tag never becomes real DOM markup, only escaped text");
  const selfClosing = el.querySelector(".syn-block.syn-xml");
  assert(selfClosing, "the well-formed self-closing <safe .../> fragment IS detected and formatted");
  assert(selfClosing.innerHTML.includes('<span class="syn-attr-value">"&amp;"</span>'),
    "the attribute's decoded '&' is HTML-re-escaped in the output, not injected raw, got " + selfClosing.innerHTML);
});

await withApp(async (w, d, T) => {
  section("169f. Theme template download/import: optional syntaxHighlightColors round trip");

  const template = JSON.parse(w.buildThemeTemplateJson());
  assert(template.syntaxHighlightColors && typeof template.syntaxHighlightColors === "object",
    "buildThemeTemplateJson includes a syntaxHighlightColors block");
  assert(T.SYNTAX_COLOR_KEYS.every(k => typeof template.syntaxHighlightColors[k] === "string" && template.syntaxHighlightColors[k].length > 0),
    "the block is seeded with every SYNTAX_COLOR_KEYS key from the active theme's computed colors");
  assert(typeof template._syntaxHighlightColors_comment === "string" && /optional/i.test(template._syntaxHighlightColors_comment),
    "a sibling hint field marks the block optional");

  // Import WITH a custom syntaxHighlightColors block: those colors are
  // applied inline as CSS vars (mirrors THEME_COLOR_KEYS' optional-set
  // pattern), and the hint field is not stored on the custom theme object.
  const withSyntax = JSON.parse(JSON.stringify(template));
  withSyntax.name = "With Syntax Colors";
  withSyntax.syntaxHighlightColors["syntax-tag"] = "#ff00ff";
  w.importThemeJson(JSON.stringify(withSyntax));
  assert(T.customThemes.length === 1, "theme with a syntaxHighlightColors block imports fine");
  let imported = T.customThemes[0];
  assert(imported.syntaxColors && imported.syntaxColors["syntax-tag"] === "#ff00ff", "the custom syntax color is stored on the theme");
  assert(!("_syntaxHighlightColors_comment" in imported), "the hint comment field is never stored on the custom theme object");
  let cs = w.getComputedStyle(d.documentElement);
  assert(cs.getPropertyValue("--syntax-tag").trim() === "#ff00ff", "the custom theme's syntax-tag color is applied inline as a CSS var, got " + cs.getPropertyValue("--syntax-tag"));

  // Import WITHOUT any syntaxHighlightColors block at all: valid (not
  // rejected, unlike a missing THEME_COLOR_KEYS entry), and the app falls
  // back to whatever :root/[data-theme] declares — no inline var set.
  const noSyntax = JSON.parse(JSON.stringify(template));
  noSyntax.name = "No Syntax Colors";
  delete noSyntax.syntaxHighlightColors;
  delete noSyntax._syntaxHighlightColors_comment;
  w.importThemeJson(JSON.stringify(noSyntax));
  assert(T.customThemes.length === 2, "a theme file with NO syntaxHighlightColors block is still accepted");
  imported = T.customThemes.find(t => t.name === "No Syntax Colors");
  assert(imported && !imported.syntaxColors, "no syntaxColors is stored for a theme that didn't provide the block");
  cs = w.getComputedStyle(d.documentElement);
  assert(cs.getPropertyValue("--syntax-tag").trim() === "#e8a94a",
    "with no per-theme override, --syntax-tag falls back to the :root default (Dark's own hardcoded value) via the cascade, got " + JSON.stringify(cs.getPropertyValue("--syntax-tag")));
});

await withApp(async (w, d, T) => {
  section("169g. .NET-style ToString() dump ('{ Key = Value, ... }', not valid JSON) is detected as its own fragment type");

  const f = await w.addFile("app.log", makeLog(0, 1), () => {});
  f.entries[0].message = "Setting selected test procedure to 'Evaluate' with parameters 'TestProcedureParameters { Type = MyProgramRecipe, ViewerName = , MyProgramRecipeId = 4c382e97-c47e-4227-a034-8e1f14ddabc4, CapabilityName = MyProgram }'.";
  T.state.selectedId = f.entries[0].id;
  w.updateDetailPanel();
  const el = d.querySelector("#detailMessage");
  const html = el.innerHTML;
  assert(el.querySelector(".syn-block"), "the dump block is detected and formatted, got " + html);
  assert(html.includes('<span class="syn-key">Type</span>'), "unquoted key highlighted, got " + html);
  assert(html.includes('<span class="syn-string">MyProgramRecipe</span>'), "unquoted value highlighted");
  assert(html.includes('<span class="syn-key">ViewerName</span><span class="syn-punct"> = </span><span class="syn-punct">,</span>') ||
    /syn-key">ViewerName<\/span><span class="syn-punct"> = <\/span>\n?\s*<span class="syn-punct">,<\/span>/.test(html),
    "a blank value ('ViewerName = ,') renders with no stray value span, got " + html);
  assert(el.textContent.startsWith("Setting selected test procedure") && el.textContent.trim().endsWith("."),
    "surrounding plain text (including the outer 'TestProcedureParameters' name and quotes) is preserved outside the { } block");

  section("169h. A brace block whose segments don't all fit 'key = value' stays plain (no misfire)");
  f.entries[0].message = "if (x < y) { do(); other() } and { a = 1, just some text }";
  w.updateDetailPanel();
  assert(!d.querySelector("#detailMessage").querySelector(".syn-block"),
    "neither brace block is a valid JSON object nor does every segment match 'key = value', so nothing is highlighted");

  section("169i. Every fragment block gets its own line (a newline before and after), so it renders left-aligned");
  f.entries[0].message = 'before <root a="1"/> mid {"x":1} after';
  w.updateDetailPanel();
  const text169i = d.querySelector("#detailMessage").textContent;
  assert(text169i.startsWith("before \n") && /\n mid \n/.test(text169i) && text169i.trim().endsWith("after"),
    "a newline precedes and follows each fragment, got " + JSON.stringify(text169i));
  assert(text169i.split("\n").length >= 5, "at least 4 line breaks for 2 fragments (one before + one after each), got " + JSON.stringify(text169i));

  section("169j. No spurious blank line when the message already puts the fragment on its own line");
  f.entries[0].message = 'before\n<root a="1"/>\nafter';
  w.updateDetailPanel();
  const text169j = d.querySelector("#detailMessage").textContent;
  assert(!text169j.includes("\n\n"), "no doubled newline when the surrounding text already had one, got " + JSON.stringify(text169j));

  section("169k. A fragment at the very start/end of the message doesn't get a leading/trailing blank line");
  f.entries[0].message = '<root a="1"/> after';
  w.updateDetailPanel();
  assert(!d.querySelector("#detailMessage").textContent.startsWith("\n"), "a fragment at the very start has no leading blank line");
  f.entries[0].message = 'before <root a="1"/>';
  w.updateDetailPanel();
  assert(!d.querySelector("#detailMessage").textContent.endsWith("\n"), "a fragment at the very end has no trailing blank line");
});

/* ============================================================
   GROUP 170 — Wildcard/[*:...] patterns span line breaks
   Origin: this session (2026-09-04), person-reported: a "text" filter's
   [*]/[*:...] wildcard pattern (compileExtractPattern) never matched a
   message containing a literal newline (a stack trace, a wrapped line),
   because JS `.`/`.*` doesn't match "\n" without the "s" (dotAll) flag.
   Fixed by adding "s" to every place that compiles/recompiles that regex:
   compileExtractPattern itself, textFilterMatchSpec, both
   getEntriesUncached "text" branches, evaluateLiveMatch (filter popup live
   count), and updateFilterPatternPreview.
   ============================================================ */
group(170);
await withApp(async (w, d, T) => {
  section("170. [*]/[*:...] wildcard patterns match across an embedded newline");

  const f = await w.addFile("multiline170.log",
    `2024-01-15 10:00:00,000\tERROR\t"main"\tC:\\src\\Foo.cs\tline 1\t[DoWork]\t"boom"\n` +
    `  at Foo.Bar()\n  at Foo.Baz()\n` +
    `2024-01-15 10:00:01,000\tINFO\t"main"\tC:\\src\\Foo.cs\tline 2\t[DoWork]\t"next entry"\n`,
    () => {});
  assert(f.entries[0].message.includes("\n"), "fixture entry 0's message really does contain a newline");
  assert(f.entries.length === 2, "fixture has 2 header lines, got " + f.entries.length);

  const spec = w.compileExtractPattern("boom[*]Foo.Baz()");
  assert(spec && spec.regex.flags.includes("s"), "compileExtractPattern's own regex carries the dotAll flag");
  assert(spec.regex.test(f.entries[0].message), "the compiled regex itself matches across the embedded newline");

  T.state.activeId = f.id;
  w.render();
  const wildcardNode = w.createFilterNode(f.id, "text", "boom[*]Foo.Baz()");
  w.invalidateAllCaches();
  assert(w.getEntries(wildcardNode.id).length === 1, "the [*] wildcard filter matches the multi-line entry (getEntriesUncached)");

  const spec170 = w.textFilterMatchSpec(wildcardNode);
  assert(spec170 && spec170.wildcardRegex.flags.includes("s"), "textFilterMatchSpec's rebuilt wildcardRegex also carries dotAll");
  assert(w.wildcardMatch(spec170.wildcardRegex, spec170.wildcardColumns, f.entries[0].message), "wildcardMatch (highlighting path) matches across the newline too");

  // Live-match count in the filter popup (evaluateLiveMatch, debounced 150ms)
  T.state.activeId = f.id;
  w.render();
  w.openFilterPopup();
  const filterInput = d.querySelector("#filterInput");
  filterInput.value = "boom[*]Foo.Baz()";
  fireInput(filterInput, w);
  await new Promise(r => setTimeout(r, 200));
  assert(d.querySelector("#filterLiveMatch").textContent.includes("1 of 2"), "live match count also finds the multi-line entry, got " + d.querySelector("#filterLiveMatch").textContent);
});

/* ============================================================
   GROUP 171 — "Filter for this message" survives a multi-line message
   Origin: this session (2026-09-04), person-reported follow-up to Group
   170: even with the dotAll fix, "Filter for this ___" still didn't find
   the multi-line message it was built from, because #filterInput is a
   single-line <input> — the browser's own value-sanitization algorithm
   silently strips "\r"/"\n" the instant openFilterForEntryColumn assigns
   a pattern containing one to filterInput.value, corrupting the pattern
   before it's ever submitted. collapseNewlinesToWildcard() now replaces
   each newline with the bare [*] token (which, since Group 170, spans a
   newline) before it reaches the input.
   ============================================================ */
group(171);
await withApp(async (w, d, T) => {
  section("171. 'Filter for this message' turns an embedded newline into [*] instead of losing it");

  const f = await w.addFile("multiline171.log",
    `2024-01-15 10:00:00,000\tERROR\t"main"\tC:\\src\\Foo.cs\tline 1\t[DoWork]\t"boom"\n` +
    `  at Foo.Bar()\n  at Foo.Baz()\n` +
    `2024-01-15 10:00:01,000\tINFO\t"main"\tC:\\src\\Foo.cs\tline 2\t[DoWork]\t"next entry"\n`,
    () => {});
  T.state.activeId = f.id;
  w.render();

  assert(w.collapseNewlinesToWildcard("boom\nat Foo.Baz()") === "boom[*]at Foo.Baz()", "collapseNewlinesToWildcard replaces a bare newline with the [*] token");
  assert(w.collapseNewlinesToWildcard("a\r\nb") === "a[*]b", "a CRLF pair collapses to a single [*] token, not two");

  fireContextMenu(d.querySelector(".log-row"), w, 50, 50);
  fireClick(d.querySelector("#ctxFilterForColumn"), w);
  const filterInput = d.querySelector("#filterInput");
  assert(!filterInput.value.includes("\n") && !filterInput.value.includes("\r"), "no raw newline ever reaches the single-line #filterInput, got " + JSON.stringify(filterInput.value));
  assert(filterInput.value === "boom[*]  at Foo.Bar()[*]  at Foo.Baz()", "each of the message's two newlines becomes its own [*] token, got " + JSON.stringify(filterInput.value));

  fireSubmit(d.querySelector("#filterForm"), w);
  w.invalidateAllCaches();
  const node = T.state.nodes[T.state.activeId];
  assert(node && node.filterType === "text" && node.value === filterInput.value, "submitting creates a plain 'text' filter node carrying that exact [*] pattern");
  assert(w.getEntries(node.id).length === 1, "the committed filter node matches the very multi-line entry it was generated from");
});

/* ============================================================
   GROUP 172 — Person-requested (2026-09-04): the "Export as CSV…" dialog
   (extraction table right-click) gets a new "Include full log entry
   column" checkbox, default off, that appends each row's original raw
   log line (r.entry.raw — timestamp, level, thread, everything, not just
   the message text the pattern matched against) as an extra, correctly
   CSV-escaped column.
   ============================================================ */
group(172);
await withApp(async (w, d, T) => {
  section("172a. 'Include full log entry column' checkbox on the CSV export dialog");

  const log = [0, 1].map(i => `2024-01-15 10:00:0${i},000\tINFO\t"main"\tC:\\src\\Foo.cs\tline ${i}\t[DoWork]\t"id=${i} score=${i}.5"`).join("\n") + "\n";
  const f = await w.addFile("a.log", log, () => {});
  T.state.activeId = f.id;
  w.render();
  const node = w.createFilterNode(f.id, "text", "id=[*:int] score=[*:float]");
  T.state.activeId = node.id;
  w.render();
  w.applyFhView("table");

  const body = d.querySelector("#extractBody");
  fireContextMenu(body, w, 50, 50);
  fireClick(d.querySelector("#ctxExportCsv"), w);
  assert(d.querySelector("#csvExportFullEntryInput").checked === false, "the checkbox defaults to unchecked");

  let saved = null;
  w.downloadCsvFallback = (text, name) => { saved = { text, name }; };

  // Left unchecked (default): no extra column.
  fireClick(d.querySelector("#csvExportConfirm"), w);
  const noEntryLines = saved.text.split("\r\n");
  assert(!noEntryLines[0].includes("Log entry"), "with the checkbox off (its default), no 'Log entry' column is appended");

  // Checked: appends the entry's full raw line (e.raw — includes the
  // timestamp/level/thread/etc. tab-separated fields, not just the matched
  // message text), quoted since the raw line contains both tabs and '"'
  // (the quoted "main"/"id=0 score=0.5" fields) which need RFC4180 escaping
  // regardless of the configured delimiter.
  fireContextMenu(body, w, 50, 50);
  fireClick(d.querySelector("#ctxExportCsv"), w);
  d.querySelector("#csvExportDelimiterSelect").value = ",";
  d.querySelector("#csvExportFullEntryInput").checked = true;
  fireClick(d.querySelector("#csvExportConfirm"), w);
  const fullEntryLines = saved.text.split("\r\n");
  assert(fullEntryLines[0].split(",").pop() === "Log entry", "header row gets an appended 'Log entry' column when the checkbox is on, got " + JSON.stringify(fullEntryLines[0]));
  assert(fullEntryLines[1].includes('2024-01-15 10:00:00,000\tINFO\t""main""') && fullEntryLines[1].includes("id=0 score=0.5"), "the appended column carries the entry's full raw line — timestamp, level, thread, everything — not just the matched message, got " + JSON.stringify(fullEntryLines[1]));
});

/* ============================================================
   GROUP 173 — This session (2026-09-04): Table/Plot upward-lookup
   inheritance. A filter node created under an extraction-pattern "text"
   node (findExtractionAncestor/nodeIsExtractionView) now ALSO shows a
   Table/Plot view — narrowing filters (timerange, idset, level, ...) and
   context/countContext are transparent for this purpose; a "link" filter
   is not (its paired entries change shape), so nothing above a link node
   counts. renderExtractTable applies the inherited ANCESTOR's pattern to
   the CHILD's own (already-narrowed) entries.
   ============================================================ */
group(173);
await withApp(async (w, d, T) => {
  section("173a. a timerange filter under an extraction node inherits Table/Plot, applying the ancestor's pattern to its own narrowed entries");

  const log = [0, 1, 2].map(i =>
    `2024-01-15 10:00:0${i},000\tINFO\t"main"\tC:\\src\\Foo.cs\tline ${i}\t[DoWork]\t"id=${i} score=${i}.5"`
  ).join("\n") + "\n";
  const f = await w.addFile("a.log", log, () => {});
  const extractNode = w.createFilterNode(f.id, "text", "id=[*:int] score=[*:float]");
  assert(w.nodeHasExtractableWildcards(extractNode) === true, "sanity: the pattern node itself is extraction-capable");

  // Narrow to just the last two entries (ts >= entry 1's timestamp).
  const allEntries = w.getEntries(extractNode.id);
  const timeNode = w.createFilterNode(extractNode.id, "timerange", { from: allEntries[1].ts, to: null });
  assert(w.nodeHasExtractableWildcards(timeNode) === false, "the timerange node itself carries no pattern");
  assert(w.nodeIsExtractionView(timeNode) === true, "but it INHERITS extraction-view from its 'text' ancestor");
  assert(w.findExtractionAncestor(timeNode) && w.findExtractionAncestor(timeNode).id === extractNode.id,
    "findExtractionAncestor resolves to the pattern-bearing ancestor node");

  T.state.activeId = timeNode.id;
  w.render();
  w.applyFhView("table");
  assert(T.fhActiveTab === "table", "the Table tab is reachable for the inherited node");

  const narrowedEntries = w.getEntries(timeNode.id);
  assert(narrowedEntries.length === 2, "sanity: the timerange filter narrowed to entries 1 and 2, got " + narrowedEntries.length);
  assert(T.extractRowsData.length === 2, "the extraction table built exactly the CHILD's own (narrowed) 2 rows, not the ancestor's 3");
  assert(T.extractColumns.some(c => c.name === "value"), "the table's columns come from the ANCESTOR's pattern ([*:int]/[*:float])");
  assert(T.extractRowsData[0].values[0] === "1", "row values are the ancestor's pattern applied to the child's own first (narrowed) entry, got " + JSON.stringify(T.extractRowsData.map(r => r.values[0])));

  section("173b. a filter under a LINK node does not inherit Table/Plot from further up, even past a real extraction node");

  // Link nodes are normally created via a two-node pairing UI action (see
  // GROUP 8/128's coverage of that flow); findExtractionAncestor only cares
  // about .type/.filterType/.parentId, so a minimal hand-built node is
  // enough to exercise the walk without going through that flow.
  const linkNode = { id: w.uid("n"), type: "filter", filterType: "link", name: "Link", parentId: extractNode.id, children: [], value: {} };
  T.state.nodes[linkNode.id] = linkNode;
  T.state.nodes[extractNode.id].children.push(linkNode.id);
  const underLink = w.createFilterNode(linkNode.id, "level", ["INFO"]);
  assert(w.findExtractionAncestor(underLink) === null, "walking a link node's child upward stops AT the link node — null, no extraction ancestor");
  assert(w.nodeIsExtractionView(underLink) === false, "so the node under the link filter does not show Table/Plot");
  assert(w.nodeIsExtractionView(linkNode) === false, "the link node itself is not extraction-view either (unchanged pre-existing behavior)");

  section("173c. a plain narrowing chain with no extraction ancestor stays non-extraction (regression baseline)");

  const plainText = w.createFilterNode(f.id, "text", "INFO");
  const plainTime = w.createFilterNode(plainText.id, "timerange", { from: null, to: null });
  assert(w.nodeHasExtractableWildcards(plainText) === false, "sanity: a plain literal 'text' filter has no wildcards");
  assert(w.findExtractionAncestor(plainTime) === null, "no extraction-pattern ancestor anywhere up this chain");
  assert(w.nodeIsExtractionView(plainTime) === false, "so this ordinary narrowing chain never shows Table/Plot");
});

/* ============================================================
   GROUP 174 — This session (2026-09-04): "Time filter from selection" —
   right-clicking a 2+ row multi-selection (state.logMultiSelect) offers a
   new context-menu item, #ctxTimeRangeFromSelection, that creates one
   "timerange" filter node spanning from the EARLIEST to the LATEST ts
   among the selected rows (inclusive both ends), same bound semantics as
   the existing single-row "Filter after/before this". Hidden for a
   single-row selection (0-1 rows), same threshold currentSelectionRowIds
   already uses for "Filter from selection".
   ============================================================ */
group(174);
await withApp(async (w, d, T) => {
  section("174. \"Time filter from selection\": timerange node spanning selected rows' min/max ts");

  const f = await w.addFile("timesel.log", makeLog(0, 10), () => {});
  T.state.activeId = f.id;
  w.render();

  const rowAt = i => d.querySelector('#tableRows [data-entry-id="' + f.entries[i].id + '"]');
  const clickWith = (el, opts) => el.dispatchEvent(new w.MouseEvent("click", { bubbles: true, cancelable: true, ...opts }));

  // --- Single selected/right-clicked row: the item is hidden ---
  clickWith(rowAt(2), {});
  assert(T.state.logMultiSelect.size <= 1, "sanity: no 2+ row multi-selection active");
  w.openContextMenu({ clientX: 10, clientY: 10 }, f.entries[2]);
  assert(isVisible(d.querySelector("#ctxTimeRangeFromSelection"), w) === false,
    "with a single row selected, \"Time filter from selection\" is hidden (already covered by Filter after/before this)");
  w.closeContextMenu();

  // --- Multi-select 3 rows out of order (2, 7, 4) — the resulting filter
  // must span the actual MIN/MAX ts among them, not just first/last picked. ---
  clickWith(rowAt(2), {});
  clickWith(rowAt(7), { ctrlKey: true });
  clickWith(rowAt(4), { ctrlKey: true });
  assert(T.state.logMultiSelect.size === 3, "sanity: 3 rows multi-selected");

  w.openContextMenu({ clientX: 10, clientY: 10 }, f.entries[4]);
  assert(isVisible(d.querySelector("#ctxTimeRangeFromSelection"), w) === true,
    "with a 2+ row multi-selection, the item is shown");

  const beforeChildren = f.children.slice();
  fireClick(d.querySelector("#ctxTimeRangeFromSelection"), w);
  assert(f.children.length === beforeChildren.length + 1, "creates exactly one new filter node");
  const addedId = f.children.find(id => !beforeChildren.includes(id));
  const node = T.state.nodes[addedId];
  assert(node.filterType === "timerange", "the created node is a \"timerange\" filter");
  assert(node.value.from === f.entries[2].ts && node.value.to === f.entries[7].ts,
    "from/to span the EARLIEST and LATEST ts among the 3 selected rows (entries 2 and 7), regardless of click order, got " + JSON.stringify(node.value));
  assert(T.state.activeId === node.id, "creating it reveals it as the active node");

  const narrowed = w.getEntries(node.id);
  assert(narrowed.length === 6 && narrowed[0].id === f.entries[2].id && narrowed[narrowed.length - 1].id === f.entries[7].id,
    "the filter is inclusive on both ends, keeping every entry from row 2 through row 7, got " + narrowed.length);

  // --- Context menu closes and clears ctxEntry as usual ---
  assert(isVisible(d.querySelector("#contextMenu"), w) === false, "the context menu closes after the action");
});

/* ============================================================
   Group 175 — this session (2026-09-04), person-requested:
   1. Removed #statusStrip ("N of M shown" bar) entirely.
   2. Added a "view toolbar" to the Filtered view (#filteredToolbar, inside
      #tableWrap, same real-row-under-the-header pattern as #contextToolbar)
      and to the Table view (#tableToolbar, inside #extractWrap, same pattern
      as #plotToolbar) — both currently empty, buttons land later. Stacked
      layout shows both #contextToolbar and #filteredToolbar at once since
      both panels are simply visible together in that layout.
   ============================================================ */
group(175);
await withApp(async (w, d, T) => {
  section("175. Status strip removed; Filtered/Table views get their own toolbar row");

  assert(d.querySelector("#statusStrip") === null, "#statusStrip no longer exists in the DOM");

  const fa = await w.addFile("a.log", makeLog(0, 10), () => {});
  const extractNode = w.createFilterNode(fa.id, "text", "message [*:int]");
  T.state.activeId = fa.id;
  w.render();

  // --- Filtered view: toolbar row is present whenever the Filtered panel is ---
  w.applyFhView("filter");
  assert(d.querySelector("#filteredToolbar") !== null, "#filteredToolbar exists in the Filtered view");
  assert(isVisible(d.querySelector("#filteredToolbar"), w) === true, "#filteredToolbar is visible while on the Filtered tab");

  // --- Stacked view: both Context's and Filtered's toolbars are on screen at once ---
  w.applyFhView("stacked");
  assert(isVisible(d.querySelector("#filteredToolbar"), w) === true, "#filteredToolbar stays visible in Stacked layout");
  assert(d.querySelector("#contextToolbar") !== null, "#contextToolbar (Context view's own toolbar) still exists alongside it");

  // --- Table view: #tableToolbar shows only while Table is the active tab, not Plot ---
  T.state.activeId = extractNode.id;
  w.render();
  w.applyFhView("table");
  assert(isVisible(d.querySelector("#tableToolbar"), w) === true, "#tableToolbar is visible on the Table tab");
  assert(d.querySelector("#tableToolbar").classList.contains("hidden") === false, "#tableToolbar has no .hidden class while on Table");

  w.applyFhView("plot");
  assert(d.querySelector("#tableToolbar").classList.contains("hidden") === true, "#tableToolbar gets .hidden when switching to the Plot tab");
  assert(d.querySelector("#plotToolbar") !== null, "#plotToolbar (Plot view's own, pre-existing toolbar) is still there");

  w.applyFhView("table");
  assert(d.querySelector("#tableToolbar").classList.contains("hidden") === false, "#tableToolbar reappears when switching back to Table");
});

/* ============================================================
   Group 176 — this session (2026-09-04), person-requested ("Filter-
   Toolbar" reorganization, follow-up to Group 175): the full row-/
   selection-action button set (Bookmark this row, Add note, Filter after
   this, Filter before this, Filter for this message, Time filter from
   selection, Add to selection) is a permanently visible, selection-
   dependent icon button group living in #viewBar itself (right of the
   level filter — `[data-row-actions="viewbar"]`) — same underlying
   functions the pre-existing right-click context menu already used, just
   fed the current single/multi row selection instead of whichever row was
   right-clicked. EXTENDED same session, person-requested follow-up: moved
   from being duplicated inside #contextToolbar/#filteredToolbar into this
   single #viewBar copy instead, and the breadcrumb's placement (its own
   row, but between the timeline minimap and #viewBar, not below it) — see
   Group 26's updated DOM-order assertion for that half. Also: Plot's two
   filter buttons switched from text to the same icon-button look, and the
   extraction table's "Export as CSV…" got a second entry point in
   #tableToolbar.
   ============================================================ */
group(176);
await withApp(async (w, d, T) => {
  section("176a. Row-action buttons (in #viewBar): disabled state follows the current selection");

  const f = await w.addFile("a.log", makeLog(0, 10), () => {});
  T.state.activeId = f.id;
  w.render();

  // Bookmark/Note/Add-to-selection moved OUT of #viewBar this session
  // (person-requested follow-up: they're actions on the current selection,
  // not filter creation, so they belong in each log view's own toolbar's
  // Actions group instead — see 176e below for their new home) — only the
  // four that genuinely create a filter node stay in the Filter-Toolbar.
  const actions = [...d.querySelector('[data-row-actions="viewbar"]').querySelectorAll("[data-row-action]")];
  // "Extract" (next to "Message") joined this group in Paket A (see Group 186).
  // Reordered (person-requested, 2026-09-08 — see Group 187/188): Before/
  // After/Time range first, so they never shift position depending on
  // whether Message/Extract are visible (Context/Filtered only). "New" was
  // then broken out into its own group (#viewbarNew, see Group 194), so it's
  // no longer part of this standard-filters group.
  const expectedActions = ["filterBefore", "filterAfter", "timeRangeFromSelection", "filterForMessage", "extractMessage"];
  assert(actions.map(b => b.dataset.rowAction).join(",") === expectedActions.join(","),
    "the Filter-Toolbar's standard row-actions group has the five filter-creating actions in order, got " + actions.map(b => b.dataset.rowAction).join(","));
  const newBtnRef = d.querySelector('#viewbarNew [data-row-action="newFilter"]');
  assert(newBtnRef, "New lives in its own #viewbarNew group now, not the standard row-actions group");
  assert(d.querySelector('[data-row-actions="viewbar"] [data-row-action="bookmark"]') === null &&
    d.querySelector('[data-row-actions="viewbar"] [data-row-action="note"]') === null &&
    d.querySelector('[data-row-actions="viewbar"] [data-row-action="addToSelection"]') === null,
    "bookmark/note/addToSelection are NOT in #viewBar any more");

  // --- Circle-with-hover-pill shape (person-requested, this session): each
  // button is a plain circle (.row-action-btn, matching .level-btn's own
  // rounded-end radius) with a hidden .row-action-label that CSS reveals on
  // hover/focus, carrying the exact same text as the button's title. ---
  actions.forEach(btn => {
    assert(btn.classList.contains("row-action-btn"), btn.dataset.rowAction + " has the .row-action-btn circle/hover-pill class");
    const label = btn.querySelector(".row-action-label");
    assert(label !== null, btn.dataset.rowAction + " has a .row-action-label span");
    assert(label.textContent === btn.title && btn.title.length > 0,
      btn.dataset.rowAction + "'s label text matches its title exactly, got label=" + JSON.stringify(label.textContent) + " title=" + JSON.stringify(btn.title));
    assert(btn.querySelector(".row-action-hit svg") !== null, btn.dataset.rowAction + "'s icon is wrapped in a fixed-size .row-action-hit span");
  });

  const filterAfterBtn = actions.find(b => b.dataset.rowAction === "filterAfter");
  const byAction = action => actions.find(b => b.dataset.rowAction === action);

  // --- No selection: single-row actions disabled, time-range disabled ---
  expectedActions.forEach(action => {
    assert(byAction(action).disabled === true, action + " starts disabled with no selection");
  });
  // "New" only needs an active filter tree (state.activeId, already set above),
  // not a selected row, so it's enabled from the start (see Group 186b). It's
  // in its own #viewbarNew group now.
  assert(newBtnRef.disabled === false, "newFilter needs no row selection, only an active filter tree");

  // --- Single row selected: single-row actions enabled, time-range still disabled ---
  w.selectEntry(f.entries[2].id);
  ["filterAfter", "filterBefore", "filterForMessage", "extractMessage"].forEach(action => {
    assert(byAction(action).disabled === false, action + " enabled with exactly one row selected");
  });
  assert(byAction("timeRangeFromSelection").disabled === true, "timeRangeFromSelection stays disabled with only one row selected");

  // --- Expand/collapse keys off the .row-action-hit circle's position AS
  // MEASURED WHILE THE GROUP IS COLLAPSED (setupHitExpandGroups), not off a
  // plain mouseenter/mouseleave on the (now width-changing) button itself —
  // that avoids the flicker bug where a preceding sibling's growing box
  // keeps shoving the next hit-zone back and forth under a stationary
  // cursor mid-animation (person-reported, 2026-09-05). filterAfterBtn is
  // enabled here (one row selected above). ---
  // Every sibling hit in the group needs its own non-overlapping stub rect —
  // the harness's default getBoundingClientRect (see withApp's setup) is a
  // huge 800x400 box that would otherwise match (10,10) for WHICHEVER
  // sibling happens to come first in DOM order, masking filterAfterBtn's
  // own rect regardless of the reorder below.
  const group = filterAfterBtn.parentElement;
  [...group.querySelectorAll(".row-action-hit")].forEach((h, i) => {
    h.getBoundingClientRect = () => ({ top: 0, left: i * 30, right: i * 30 + 28, bottom: 28, width: 28, height: 28, x: i * 30, y: 0 });
  });
  const filterAfterHit = filterAfterBtn.querySelector(".row-action-hit");
  const filterAfterRect = filterAfterHit.getBoundingClientRect();
  const midX = (filterAfterRect.left + filterAfterRect.right) / 2;
  assert(!filterAfterBtn.classList.contains("expanded"), "sanity: starts collapsed");
  group.dispatchEvent(new w.MouseEvent("mousemove", { bubbles: false, clientX: midX, clientY: 10 }));
  assert(filterAfterBtn.classList.contains("expanded"), "moving into the circle's (collapsed-state) rect expands the button");
  group.dispatchEvent(new w.MouseEvent("mousemove", { bubbles: false, clientX: 5000, clientY: 5000 }));
  assert(!filterAfterBtn.classList.contains("expanded"), "moving off the circle's rect collapses it again");
  group.dispatchEvent(new w.MouseEvent("mouseleave", { bubbles: false }));

  // --- 2+ rows multi-selected: timeRangeFromSelection enables. filterAfter/
  // filterBefore ALSO stay enabled now (person-requested follow-up,
  // 2026-09-08): they resolve inclusively across the whole selection (see
  // afterBeforeActionEntries) — earliest/latest ts becomes the bound —
  // unlike filterForMessage/extractMessage, which still need exactly one. ---
  T.state.logMultiSelect = new Set([f.entries[1].id, f.entries[4].id]);
  w.updateRowActionButtons();
  assert(byAction("timeRangeFromSelection").disabled === false, "timeRangeFromSelection enables with 2+ rows multi-selected");
  assert(byAction("filterAfter").disabled === false, "filterAfter stays enabled with 2+ rows multi-selected (inclusive earliest-ts bound)");
  assert(byAction("filterBefore").disabled === false, "filterBefore stays enabled with 2+ rows multi-selected (inclusive latest-ts bound)");
  assert(byAction("filterForMessage").disabled === true, "filterForMessage still needs exactly one reference entry — disabled with 2+ multi-selected");
  assert(byAction("extractMessage").disabled === true, "extractMessage still needs exactly one reference entry — disabled with 2+ multi-selected");

  // --- A button that becomes disabled while its pill happens to be expanded
  // (e.g. the selection changed via keyboard, not by the mouse leaving the
  // circle) doesn't get stuck expanded — updateRowActionButtons() drops it.
  // filterAfter no longer disables on 2+ multi-select, so use
  // filterForMessage (still single-entry-only) to exercise this guard. ---
  T.state.logMultiSelect = new Set();
  w.selectEntry(f.entries[3].id);
  const filterForMessageBtn = byAction("filterForMessage");
  filterForMessageBtn.classList.add("expanded"); // simulate: mouse still sitting over the circle
  T.state.logMultiSelect = new Set([f.entries[1].id, f.entries[4].id]); // disables filterForMessage again
  w.updateRowActionButtons();
  assert(filterForMessageBtn.disabled === true, "sanity: disabled again");
  assert(!filterForMessageBtn.classList.contains("expanded"), "a newly-disabled button's stuck-open pill is force-collapsed");

  // --- Stays visible/functional on Table too (Table/Plot presence — see Group 26/158a) ---
  // NOTE: on Table/Plot, After/Before/Extract/Time range are all now
  // context-aware and stay visible (Message hides only on Plot) —
  // see Group 178 for that coverage; not re-checked here.
  const extractNode = w.createFilterNode(f.id, "text", "message [*:int]");
  T.state.activeId = extractNode.id;
  w.render();
  w.applyFhView("table");
  assert(isVisible(d.querySelector('[data-row-actions="viewbar"]'), w) === true, "row-actions group stays visible on the Table tab — it's part of the universal Filter-Toolbar");
});

await withApp(async (w, d, T) => {
  section("176b. Row-action buttons: bookmark/note reflect state, and clicking one produces the same effect as the context-menu equivalent");

  const f = await w.addFile("a.log", makeLog(0, 10), () => {});
  const textNode = w.createFilterNode(f.id, "text", "message");
  T.state.activeId = textNode.id;
  w.render();
  const entry = f.entries[3];
  w.selectEntry(entry.id);

  // bookmark/note now live in the log views' own "Actions" group (moved
  // out of #viewBar this session — see 176a/176e) — querySelector picks up
  // whichever copy comes first in the DOM (Context's, since #highlightWrap
  // precedes #filterSlot); either copy reacts identically, same shared
  // state/click-delegation as the six log-display toggles.
  const bookmarkBtn = d.querySelector('[data-row-action="bookmark"]');
  const noteBtn = d.querySelector('[data-row-action="note"]');
  assert(!bookmarkBtn.classList.contains("active"), "bookmark button starts unmarked (not bookmarked yet)");
  fireClick(bookmarkBtn, w);
  assert(T.state.bookmarks.has(entry.id), "clicking the toolbar bookmark button bookmarks the selected row");
  assert(bookmarkBtn.classList.contains("active"), "bookmark button reflects the bookmarked state immediately");
  fireClick(bookmarkBtn, w);
  assert(!T.state.bookmarks.has(entry.id), "clicking again removes the bookmark");

  assert(!noteBtn.classList.contains("active"), "note button starts unmarked (no note yet)");
  fireClick(noteBtn, w);
  assert(isVisible(d.querySelector("#noteDialog"), w) === true, "clicking the toolbar note button opens the note dialog, same as the context-menu entry");
  d.querySelector("#noteDialogInput").value = "toolbar note";
  fireClick(d.querySelector("#noteDialogSave"), w);
  assert(T.state.notes.get(entry.id) === "toolbar note", "saving from the toolbar-opened dialog sets the note");
  assert(noteBtn.classList.contains("active"), "note button reflects the now-present note");

  // --- Filter after this / Filter before this: same "timerange" node the context-menu path creates ---
  const beforeChildCount = textNode.children.length;
  fireClick(d.querySelector('[data-row-action="filterAfter"]'), w);
  assert(textNode.children.length === beforeChildCount + 1, "Filter-after-this creates one new filter node");
  const afterNode = T.state.nodes[T.state.activeId];
  assert(afterNode.filterType === "timerange" && afterNode.value.from === entry.ts && afterNode.value.to === null,
    "created node is a timerange filter spanning from this entry's ts onward");
  assert(T.state.activeId === afterNode.id, "creating it activates the new node, same as the context-menu path");
});

await withApp(async (w, d, T) => {
  section("176c. Time filter from selection / Add to selection toolbar buttons match the context-menu behavior");

  const f = await w.addFile("a.log", makeLog(0, 10), () => {});
  T.state.activeId = f.id;
  w.render();
  T.state.logMultiSelect = new Set([f.entries[2].id, f.entries[7].id, f.entries[4].id]);
  w.updateRowActionButtons();

  const beforeChildCount = f.children.length;
  fireClick(d.querySelector('[data-row-action="timeRangeFromSelection"]'), w);
  assert(f.children.length === beforeChildCount + 1, "creates exactly one new filter node");
  const rangeNode = T.state.nodes[T.state.activeId];
  assert(rangeNode.filterType === "timerange" && rangeNode.value.from === f.entries[2].ts && rangeNode.value.to === f.entries[7].ts,
    "spans the earliest/latest ts among the 3 selected rows, regardless of click order");

  // --- Add to selection: opens the same #addToSelectionMenu, anchored to the clicked button ---
  T.state.activeId = f.id;
  T.state.logMultiSelect = new Set([f.entries[1].id, f.entries[5].id]);
  w.updateRowActionButtons();
  const addBtn = d.querySelector('[data-row-action="addToSelection"]');
  fireClick(addBtn, w);
  assert(isVisible(d.querySelector("#addToSelectionMenu"), w) === true, "clicking Add-to-selection opens the same popup the context-menu entry uses");
  const createItem = d.querySelector('#addToSelectionMenu [data-selection-action="create"]');
  assert(createItem !== null, "'Create new selection filter' option is present");
  fireClick(createItem, w);
  const created = Object.values(T.state.nodes).find(n => n.selectionFilter);
  assert(created && created.value.length === 2 && created.value.includes(f.entries[1].id) && created.value.includes(f.entries[5].id),
    "creates a selection filter node containing exactly the 2 multi-selected rows");
});

